/**
 * Api.gs : ฟังก์ชันที่หน้าเว็บเรียกใช้ (google.script.run)
 * เหตุการณ์ไฟฟ้าขัดข้อง, อุปกรณ์, วัสดุ, ค่าตรวจวัด, ประวัติการแก้ไข
 * ทุกฟังก์ชันรับ token เป็นพารามิเตอร์แรก และคืนค่าเป็น object ที่ไม่มี Date (แปลงเป็นข้อความแล้ว)
 */

// =====================================================================  Bootstrap
function apiBootstrap(token) {
  return bootstrapFor_(auth_(token));
}

/** ข้อมูลตั้งต้นของแอป: ส่วนคงที่เก็บใน cache 10 นาที (ล้างอัตโนมัติเมื่อมีการแก้ข้อมูล) */
function bootstrapFor_(s) {
  let st = null;
  const raw = getChunked_('boot_static');
  if (raw) { try { st = JSON.parse(raw); } catch (e) { st = null; } }
  if (!st) { st = bootstrapStatic_(); putChunked_('boot_static', JSON.stringify(st), CACHE_TTL); }
  const evs = events_();
  const open = evs.filter(e => e.status && e.status !== STATUS.CLOSED).length;
  const alerts = table_(SH.ALERTS).rows.filter(a => a.status !== 'ปิดแล้ว').length;
  return Object.assign({}, st, {
    user: Object.assign({ perms: permsOf_(s), roleLabel: ROLE_LABEL[s.role] }, s),
    counts: { open, alerts, total: evs.length },
    shift: { key: currentShiftKey_(), date: fmtDate_(currentShift_().date), name: currentShift_().name },
    rosterOk: !!rosterCurrent_(),
    sheetUrl: ROLES[s.role].indexOf('admin') >= 0 || s.role === 'supervisor' ? ss_().getUrl() : '',
  });
}

function bootstrapStatic_() {
  const list = (name, key) => table_(name).rows.map(r => r[key || 'name']).filter(v => v !== '' && v != null).map(String);
  const active = r => String(r.active).toUpperCase() !== 'FALSE';
  const staff = table_(SH.STAFF).rows.filter(active);
  const devices = table_(SH.DEVICES).rows.map(d => [String(d.code), String(d.tambon || ''), String(d.location || '').slice(0, 40)]);
  const directory = table_(SH.DIR).rows.filter(active).map(d => [String(d.emp_id), String(d.title || ''), String(d.name), String(d.position || ''), String(d.dept || ''), String(d.phone || ''), String(d.note || '')]);
  return {
    org: setting_('org_name', 'กฟส.กำแพงแสน'),
    version: APP.version,
    shifts: shifts_().map(x => ({ name: x.name, start: x.start, end: x.end })),
    settings: {
      repeat_count: settingNum_('repeat_count', 3), repeat_days: settingNum_('repeat_days', 30),
      repeat_count_short: settingNum_('repeat_count_short', 2), repeat_days_short: settingNum_('repeat_days_short', 7),
      max_outage_hours: settingNum_('max_outage_hours', 12), v_min: settingNum_('v_min', 200),
      v_max: settingNum_('v_max', 242), load_warn_pct: settingNum_('load_warn_pct', 80),
      unbal_warn_pct: settingNum_('unbal_warn_pct', 20), lv_ll_voltage: settingNum_('lv_ll_voltage', 400),
    },
    masters: {
      center: staff.filter(r => r.position === 'ศูนย์สั่งการ').map(r => String(r.name)),
      leads: staff.filter(r => r.position === 'พชง.').map(r => String(r.name)),
      crews: staff.filter(r => r.position !== 'ศูนย์สั่งการ').map(r => String(r.name)),
      eventTypes: table_(SH.ETYPE).rows.map(r => ({ code: String(r.code), voltage: String(r.voltage), desc: String(r.desc || '') })),
      causes: table_(SH.CAUSE).rows.map(r => ({ name: String(r.name), voltage: String(r.voltage || 'HV/LV') })),
      actions: list(SH.ACTION), notify: list(SH.NOTIFY), weather: list(SH.WEATHER),
      vehicles: table_(SH.VEHICLE).rows.filter(active).map(r => String(r.name)),
      materials: table_(SH.MATERIAL).rows.map(r => ({ code: String(r.code), name: String(r.name), unit: String(r.unit || ''), sizes: String(r.sizes || '').split(',').map(x => x.trim()).filter(Boolean) })),
      tambons: table_(SH.TAMBON).rows.map(r => ({ name: String(r.name), amphoe: String(r.amphoe), lat: +r.lat, lon: +r.lon })),
      substations: table_(SH.SUBST).rows.map(r => ({ code: String(r.code), name: String(r.name || '') })),
      statuses: [STATUS.OPEN, STATUS.PENDING, STATUS.CLOSED],
    },
    devices, directory,
    lineEnabled: !!(setting_('line_channel_token') && setting_('line_to')) || !!setting_('gchat_webhook'),
    lineEnabledPm: !!(setting_('line_channel_token') && setting_('line_to_pm')),
    training: isTraining_(), dept: APP.dept, sessionHours: sessHours_(),
    pmCategories: pmCategories_(), v15: v15Static_(), v16: v16Static_(), v17: v17Static_(), v191: v191Static_(), pmStatuses: PM_STATUS, plannedStatuses: PLANNED_STATUS,
    reportEmails: setting_('report_emails'),
    features: featuresMap_(), reqTypes: REQ_TYPES, reqChannels: REQ_CHANNELS, reqStatuses: REQ_STATUS,
    inspTypes: INSP_TYPES, inspSeverity: INSP_SEVERITY, agValues: AG_VALUES, agParts: AG_PARTS,
    photo: { px: settingNum_('photo_max_px', 1280), kb: settingNum_('photo_target_kb', 250) },
  };
}

// =====================================================================  Events: read
function isDeleted_(r) { return r.deleted === true || String(r.deleted).toUpperCase() === 'TRUE'; }

/** เหตุการณ์ทั้งหมดที่ยังไม่ถูกลบ (Date objects) */
function events_(includeDeleted) {
  return table_(SH.EVENTS).rows.filter(r => r.id && (includeDeleted || !isDeleted_(r))).map(r => {
    if (!(r.date instanceof Date)) r.date = parseDT_(r.date);
    EVENT_DT_FIELDS.forEach(k => { if (r[k] && !(r[k] instanceof Date)) r[k] = parseDT_(r[k]); });
    return r;
  });
}
function evTime_(r) { return r.t_notify || r.t_off || r.date; }

function serEvent_(r) {
  const o = {};
  SCHEMA.Events.forEach(([k]) => {
    const v = r[k];
    if (k === 'date') o[k] = fmtDate_(v);
    else if (v instanceof Date) o[k] = fmtDT_(v);
    else o[k] = v === null || v === undefined ? '' : v;
  });
  o.deleted = isDeleted_(r);
  return o;
}

function apiListEvents(token, f) {
  auth_(token, 'view');
  f = f || {};
  const from = parseDT_(f.from), to = parseDT_(f.to);
  if (to) to.setDate(to.getDate() + 1);
  let rows = filterEvents_(f);
  rows.sort((a, b) => (evTime_(b) || 0) - (evTime_(a) || 0));
  const total = rows.length;
  const limit = Math.min(+f.limit || 300, 2000);
  rows = rows.slice(0, limit);
  return {
    total,
    rows: rows.map(r => ({
      id: r.id, date: fmtDate_(r.date), time: fmtHM_(r.t_notify || r.t_off), shift: r.shift, voltage: r.voltage,
      type: r.type, status: r.status, device: r.device, tambon: r.tambon, location: String(r.location).slice(0, 60),
      cause_cat: r.cause_cat, cause: String(r.cause).slice(0, 80), off_min: r.off_min, lead: r.lead,
      receiver: r.receiver, dq: r.dq && !r.dq_ok ? 1 : 0, edited: r.updated_at ? 1 : 0, deleted: isDeleted_(r), parent_id: r.parent_id || '', team: r.team || '',
      // v1.9.1 ข้อ 79/81
      materials: String(r.materials || '').slice(0, 80), sap_cut: r.sap_cut || '', sap_cut_note: r.sap_cut_note || '', br1_total: r.br1_total || '', sap_iw31: r.sap_iw31 || '', sap_iw32: r.sap_iw32 || '', sap_vf01: r.sap_vf01 || '', sap_vf02: r.sap_vf02 || '',
    })),
  };
}
function filterEvents_(f) {
  const from = parseDT_(f.from), to = parseDT_(f.to);
  if (to) to.setDate(to.getDate() + 1);
  const q = String(f.q || '').trim().toLowerCase();
  return events_(!!f.includeDeleted).filter(r => {
    const t = evTime_(r);
    if (from && (!t || t < from)) return false;
    if (to && (!t || t >= to)) return false;
    if (f.voltage && r.voltage !== f.voltage) return false;
    if (f.type && r.type !== f.type) return false;
    if (f.status && r.status !== f.status) return false;
    if (f.tambon && r.tambon !== f.tambon) return false;
    if (f.cause_cat && r.cause_cat !== f.cause_cat) return false;
    if (f.device && !sameDevice_(r.device, normDevice_(f.device).code)) return false;
    if (f.dqOnly && !r.dq) return false;
    if (q) {
      const hay = [r.id, r.device, r.device2, r.location, r.cause, r.action, r.lead, r.crew1, r.crew2, r.oms, r.sap, r.feeder, r.tambon, r.br1_book, r.br1_no, r.br1_book && r.br1_no ? r.br1_book + '/' + r.br1_no : ''].join(' ').toLowerCase();
      if (hay.indexOf(q) < 0) return false;
    }
    return true;
  });
}

function apiGetEvent(token, id) {
  auth_(token, 'view');
  const r = events_(true).find(x => x.id === id);
  if (!r) return { ok: false, error: 'ไม่พบรายการ ' + id };
  const mats = table_(SH.MATUSE).rows.filter(m => m.event_id === id)
    .map(m => ({ code: m.code, name: m.name, size: m.size, qty: m.qty, unit: m.unit, raw: m.raw, sap: m.sap_code, sap_name: m.sap_name }));
  const history = table_(SH.AUDIT).rows.filter(a => a.ref === id)
    .map(a => ({ ts: fmtDT_(a.ts), user: a.user, action: a.action, changes: a.changes, reason: a.reason })).reverse();
  const reg = regOf_(r.device);
  const all = events_();
  const children = all.filter(x => x.parent_id === id).map(x => ({ id: x.id, time: fmtDT_(evTime_(x)), device: x.device, location: String(x.location).slice(0, 50), notify: x.notify }));
  const lockRep = lockedReportFor_(evTime_(r));
  const pms = table_(SH.PM).rows.filter(p => String(p.event_ids).split(/[,\s]+/).indexOf(id) >= 0).map(p => ({ id: p.id, category: p.category, status: p.status, priority: p.priority }));
  const reqs = table_(SH.EDITREQ).rows.filter(q => q.event_id === id && q.status === 'รออนุมัติ').map(q => ({ id: q.id, by: q.requested_by, at: fmtDT_(q.requested_at), reason: q.reason }));
  return { ok: true, event: serEvent_(r), materials: mats, history, device: reg ? regInfo_(reg) : null,
    measurements: measOfEvent_(id), children, locked: lockRep ? { id: lockRep.id, date: fmtDate_(lockRep.date instanceof Date ? lockRep.date : parseDT_(lockRep.date)), version: lockRep.version } : null,
    pm: pms, pendingRequests: reqs };
}

function apiOpenEvents(token) {
  auth_(token, 'view');
  return events_().filter(e => e.status && e.status !== STATUS.CLOSED)
    .sort((a, b) => (evTime_(a) || 0) - (evTime_(b) || 0))
    .map(r => ({ id: r.id, time: fmtDT_(evTime_(r)), type: r.type, device: r.device, location: r.location, status: r.status, lead: r.lead, mins: Math.round((Date.now() - (r.t_off || evTime_(r))) / 60000) }));
}

// =====================================================================  Device code
const FEEDER_RE = /^([A-Z]{2,3})?(\d{1,2})(VB|R|F|S|AS|LB|DS|SW|CB)-?(\d{1,3})(\/\d{1,2})?\.*$/;

let __devIdx = null;
/** ดัชนีอุปกรณ์ตามรหัสค้นหา */
function deviceIndex_() {
  if (__devIdx && __tables[SH.DEVICES]) return __devIdx;
  __devIdx = {};
  table_(SH.DEVICES).rows.forEach(d => { __devIdx[deviceKey_(d.code)] = d; });
  return __devIdx;
}
function regOf_(code) { return code ? deviceIndex_()[deviceKey_(code)] || null : null; }
function regInfo_(reg) {
  const n = v => (v === '' || v == null || isNaN(+v)) ? '' : +v;
  return { code: String(reg.code), kind: reg.kind, tambon: reg.tambon, location: reg.location, feeder: reg.feeder, kva: reg.kva,
    lat: n(reg.lat), lon: n(reg.lon), customers: reg.customers, phase: reg.phase, source: reg.source, note: reg.note,
    ag: reg.ag_date ? { hv: reg.ag_hv, lv: reg.ag_lv, do: reg.ag_do, la: reg.ag_la, date: reg.ag_date instanceof Date ? fmtDate_(reg.ag_date) : String(reg.ag_date), by: reg.ag_by } : null };
}
function sameDevice_(a, b) { return !!a && !!b && deviceKey_(a) === deviceKey_(b); }
const DEVICE_KIND = { VB: 'เบรกเกอร์ (VB)', R: 'รีโคลสเซอร์ (R)', F: 'ฟิวส์/ดร็อปเอาท์ (F)', S: 'สวิตช์ (S)' };

/** ทำรหัสอุปกรณ์ให้เป็นรูปแบบมาตรฐาน + จำแนกชนิด */
function normDevice_(raw) {
  let s = String(raw == null ? '' : raw).toUpperCase().replace(/\s+/g, '').replace(/^PEA\.?/, '');
  const out = { code: s, kind: '', substation: '', feeder: '', kva: '', valid: false, note: '' };
  if (!s) return out;
  let m = s.match(FEEDER_RE);
  if (m) {
    const st = m[1] || 'KSA';
    const code = st + ('0' + (+m[2])).slice(-2) + m[3] + '-' + ('0' + (+m[4])).slice(-2) + (m[5] ? '/' + ('0' + m[5].slice(1)).slice(-2) : '');
    if (!m[1]) out.note = 'เติมรหัสสถานี KSA ให้อัตโนมัติ';
    return Object.assign(out, { code, kind: DEVICE_KIND[m[3]] || 'อุปกรณ์ในฟีดเดอร์', substation: st, feeder: st + ('0' + (+m[2])).slice(-2), valid: true });
  }
  m = s.match(/^(\d{2})-(\d{5,7})(?:\/(\d{2,4}))?(?:KVA)?$/);
  if (m) {
    const base = deviceKey_(m[1] + '-' + m[2]);
    let kva = m[3] ? +m[3] : '';
    if (kva === '') { try { const r = regOf_(base); if (r && r.kva) kva = +r.kva; } catch (e) { /* registry not ready */ } }
    const code = base + (kva !== '' ? '/' + kva : '');
    if (code !== s) out.note = 'ปรับรูปแบบรหัสหม้อแปลงเป็น ' + code;
    return Object.assign(out, { code, kind: 'หม้อแปลง', kva, valid: true });
  }
  if (/^\d{7,11}$/.test(s)) return Object.assign(out, { kind: 'มิเตอร์ (PEA No.)', valid: true });
  if (/^0\d{11}$/.test(s)) return Object.assign(out, { kind: 'CA ผู้ใช้ไฟ', valid: true });
  out.kind = 'อื่นๆ';
  out.note = 'รูปแบบรหัสไม่ตรงมาตรฐาน (ตัวอย่าง KSA01F-05, 61-015091/160, 6602458309)';
  return out;
}

function apiDeviceInfo(token, raw, tOff, selfId) {
  auth_(token, 'view');
  const n = normDevice_(raw);
  if (!n.code) return { ok: false };
  const reg = regOf_(n.code);
  const now = new Date();
  const hist = events_().filter(e => sameDevice_(e.device, n.code) || sameDevice_(e.device2, n.code))
    .sort((a, b) => (evTime_(b) || 0) - (evTime_(a) || 0));
  const within = d => hist.filter(e => evTime_(e) && (now - evTime_(e)) <= d * 86400000).length;
  const rc = settingNum_('repeat_count', 3), rd = settingNum_('repeat_days', 30);
  const rcs = settingNum_('repeat_count_short', 2), rds = settingNum_('repeat_days_short', 7);
  return {
    ok: true, norm: n,
    registry: reg ? regInfo_(reg) : null,
    counts: { d7: within(7), d30: within(30), d90: within(90), d365: within(365), all: hist.length },
    // +1 = นับรวมเหตุการณ์ที่กำลังจะบันทึก
    repeat: (within(rd) + 1 >= rc) || (within(rds) + 1 >= rcs),
    rule: { rc, rd, rcs, rds },
    history: hist.slice(0, 15).map(e => ({ id: e.id, time: fmtDT_(evTime_(e)), type: e.type, cause_cat: e.cause_cat, cause: String(e.cause).slice(0, 60), off_min: e.off_min })),
    related: relatedEvents_(n, reg, parseDT_(tOff) || new Date(), selfId),
  };
}

/** ข้อ 25: เหตุการณ์ที่อาจเป็นเหตุเดียวกัน (อุปกรณ์เดียวกันหรือฟีดเดอร์เดียวกัน ภายใน ±60 นาที) */
function relatedEvents_(n, reg, t, selfId) {
  const feeder = n.feeder || (reg && reg.feeder) || '';
  return events_().filter(e => !e.parent_id && e.id !== selfId && evTime_(e) && Math.abs(evTime_(e) - t) <= 60 * 60000 &&
    (sameDevice_(e.device, n.code) || (feeder && e.feeder === feeder && e.voltage === 'HV')))
    .sort((a, b) => Math.abs(evTime_(a) - t) - Math.abs(evTime_(b) - t)).slice(0, 5)
    .map(e => ({ id: e.id, time: fmtDT_(evTime_(e)), type: e.type, device: e.device, feeder: e.feeder, location: String(e.location).slice(0, 40), same: sameDevice_(e.device, n.code) }));
}

// =====================================================================  Events: write
const REQUIRED_LABEL = {
  date: 'วันที่', voltage: 'ระดับแรงดัน', type: 'ประเภทเหตุการณ์', device: 'รหัสอุปกรณ์', tambon: 'ตำบล',
  location: 'สถานที่', cause_cat: 'กลุ่มสาเหตุ', notify: 'ช่องทางรับแจ้ง', t_notify: 'เวลารับแจ้ง',
  receiver: 'ผู้รับแจ้ง', t_off: 'เวลาไฟดับ', status: 'สถานะ',
};

function nz_(v) { const n = num_(v); return n === null ? '' : n; }
function num_(v) { if (v === '' || v === null || v === undefined) return null; const n = Number(v); return isNaN(n) ? null : n; }
function diffMin_(a, b) { return a && b ? Math.round((b - a) / 60000) : ''; }

/** แปลงข้อมูลจากฟอร์ม → object พร้อมบันทึก (Date objects) */
function normalizeEventInput_(ev) {
  const e = {};
  SCHEMA.Events.forEach(([k]) => { if (ev[k] !== undefined) e[k] = typeof ev[k] === 'string' ? ev[k].trim() : ev[k]; });
  e.date = parseDT_(ev.date);
  ['t_notify', 't_off', 't_on', 't_depart', 't_back'].forEach(k => { e[k] = parseDT_(ev[k]); });
  const d = normDevice_(ev.device);
  e.device = d.code; e.device_kind = d.kind;
  if (d.substation) e.substation = d.substation;
  if (d.feeder) e.feeder = d.feeder;
  if (d.kva !== '') e.kva = d.kva;
  e._deviceNorm = d;
  const reg = regOf_(d.code);
  if (reg) {
    if (!e.feeder && reg.feeder) { e.feeder = String(reg.feeder); e.substation = String(reg.feeder).slice(0, 3); }
    if ((e.kva === '' || e.kva == null) && reg.kva) e.kva = +reg.kva;
  }
  e.device2 = ev.device2 ? normDevice_(ev.device2).code : '';
  e.off_min = diffMin_(e.t_off, e.t_on);
  e.work_min = diffMin_(e.t_depart, e.t_back);
  e.shift = shiftOf_(e.t_notify || e.t_off).name;
  e.customers = num_(ev.customers) === null ? '' : num_(ev.customers);
  e.moo = num_(ev.moo) === null ? '' : num_(ev.moo);
  e.type = String(ev.type || '').trim();
  e.voltage = String(ev.voltage || '').trim().toUpperCase();
  return e;
}

/** ตรวจความถูกต้อง: errors = ห้ามบันทึก, warnings = ต้องยืนยันก่อน */
function validateEvent_(e, existingId) {
  const errors = [], warnings = [];
  const closed = e.status === STATUS.CLOSED;
  Object.keys(REQUIRED_LABEL).forEach(k => { if (e[k] === '' || e[k] == null) errors.push('กรุณาระบุ ' + REQUIRED_LABEL[k]); });
  const et = table_(SH.ETYPE).rows.find(r => String(r.code) === e.type);
  if (e.type && !et) errors.push('ประเภทเหตุการณ์ "' + e.type + '" ไม่อยู่ในรายการ');
  if (et && e.voltage && String(et.voltage).indexOf(e.voltage) < 0) errors.push('ประเภท ' + e.type + ' ใช้กับแรงดัน ' + et.voltage + ' เท่านั้น');
  if (e.voltage && ['HV', 'LV'].indexOf(e.voltage) < 0) errors.push('ระดับแรงดันต้องเป็น HV หรือ LV');
  if (e.tambon && !table_(SH.TAMBON).rows.some(r => r.name === e.tambon)) errors.push('ตำบล "' + e.tambon + '" ไม่อยู่ในรายการ');
  if (e.cause_cat && !table_(SH.CAUSE).rows.some(r => r.name === e.cause_cat)) errors.push('กลุ่มสาเหตุไม่อยู่ในรายการ');
  const now = new Date();
  ['t_notify', 't_off', 't_on', 't_depart', 't_back'].forEach(k => {
    if (e[k] && e[k] - now > 15 * 60000) errors.push('เวลา "' + k + '" อยู่ในอนาคต');
  });
  if (e.t_off && e.t_on && e.t_on < e.t_off) errors.push('เวลาจ่ายไฟได้ ต้องไม่ก่อนเวลาไฟดับ');
  if (e.t_depart && e.t_back && e.t_back < e.t_depart) errors.push('เวลาเข้า ต้องไม่ก่อนเวลาออกปฏิบัติงาน');
  if (e.t_notify && e.t_depart && e.t_depart < e.t_notify) errors.push('เวลาออกปฏิบัติงาน ต้องไม่ก่อนเวลารับแจ้ง');
  if (closed) {
    if (!e.t_on) errors.push('ปิดงาน: กรุณาระบุเวลาจ่ายไฟได้');
    if (!e.action_cat && e.type !== 'T/R') errors.push('ปิดงาน: กรุณาระบุกลุ่มการแก้ไข');
    if (!e.lead && e.type !== 'T/R' && e.notify !== 'SCADA') errors.push('ปิดงาน: กรุณาระบุ พชง. ผู้ปฏิบัติงาน');
  }
  if (e.parent_id) {
    e.parent_id = String(e.parent_id).toUpperCase().trim();
    const par = events_().find(r => r.id === e.parent_id);
    if (!par) errors.push('ไม่พบเหตุการณ์หลัก ' + e.parent_id);
    else if (par.parent_id) errors.push(e.parent_id + ' เป็นเหตุการณ์ย่อยอยู่แล้ว ให้ผูกกับเหตุการณ์หลัก ' + par.parent_id + ' แทน');
    else if (existingId && e.parent_id === existingId) errors.push('ผูกเหตุการณ์กับตัวเองไม่ได้');
    else if (existingId && events_().some(r => r.parent_id === existingId)) errors.push(existingId + ' มีเหตุการณ์ย่อยอยู่แล้ว จึงเป็นเหตุการณ์ย่อยของรายการอื่นไม่ได้');
  }
  if (e.t_on && e.status === STATUS.OPEN) warnings.push('มีเวลาจ่ายไฟได้แล้ว แต่สถานะยังเป็น "กำลังดำเนินการ"');
  const crew = [e.lead, e.crew1, e.crew2].filter(Boolean);
  if (new Set(crew).size !== crew.length) errors.push('ชื่อผู้ปฏิบัติงานซ้ำกัน');
  if (e.customers !== '' && e.customers < 0) errors.push('จำนวนผู้ใช้ไฟต้องไม่ติดลบ');

  // ---- warnings
  const dn = e._deviceNorm || {};
  if (e.device && !dn.valid) warnings.push('รหัสอุปกรณ์ "' + e.device + '" ไม่ตรงรูปแบบมาตรฐาน');
  if (dn.note && dn.valid) warnings.push('รหัสอุปกรณ์: ' + dn.note + ' → ' + e.device);
  const kindHint = { 'D/F': ['ฟิวส์/ดร็อปเอาท์ (F)', 'หม้อแปลง'], 'T/R': ['รีโคลสเซอร์ (R)', 'เบรกเกอร์ (VB)', 'สวิตช์ (S)'], 'T/L': ['รีโคลสเซอร์ (R)', 'เบรกเกอร์ (VB)', 'สวิตช์ (S)'], LT: ['หม้อแปลง'], MT: ['มิเตอร์ (PEA No.)', 'CA ผู้ใช้ไฟ'] };
  if (kindHint[e.type] && dn.kind && kindHint[e.type].indexOf(dn.kind) < 0) warnings.push('ประเภท ' + e.type + ' แต่รหัสอุปกรณ์เป็นชนิด "' + dn.kind + '" — ตรวจสอบอีกครั้ง');
  const maxH = settingNum_('max_outage_hours', 12);
  if (e.off_min !== '' && e.off_min > maxH * 60) warnings.push('ไฟดับรวม ' + minToText_(e.off_min) + ' (เกิน ' + maxH + ' ชม.) ถูกต้องหรือไม่');
  if (e.t_off && e.t_notify && Math.abs(e.t_notify - e.t_off) > 6 * 3600000) warnings.push('เวลารับแจ้งห่างจากเวลาไฟดับเกิน 6 ชม.');
  if (e.date && e.t_notify && Math.abs(e.t_notify - e.date) > 2 * 86400000) warnings.push('วันที่ กับ เวลารับแจ้ง ห่างกันเกิน 1 วัน');
  if (e.oms && !/^\d{10}$/.test(String(e.oms))) warnings.push('เลขที่ OMS ไม่ใช่ตัวเลข 10 หลัก');
  if (e.sap && !/^\d{10,12}$/.test(String(e.sap))) warnings.push('เลขที่ SAP ไม่ใช่ตัวเลข 10–12 หลัก');
  if (!e.weather) warnings.push('ยังไม่ได้ระบุสภาพอากาศ');
  const others = events_().filter(r => r.id !== existingId);
  if (e.device && e.t_off) {
    const dup = others.find(r => r.id !== e.parent_id && sameDevice_(r.device, e.device) && r.t_off && Math.abs(r.t_off - e.t_off) <= 60 * 60000);
    if (dup) warnings.push('อาจบันทึกซ้ำ: ' + dup.id + ' อุปกรณ์เดียวกันไฟดับ ' + fmtDT_(dup.t_off));
  }
  if (e.oms && /^\d{10}$/.test(String(e.oms))) {
    const d2 = others.find(r => String(r.oms) === String(e.oms));
    if (d2) warnings.push('เลขที่ OMS ซ้ำกับ ' + d2.id);
  }
  if (e.device) {
    const t0 = e.t_off || e.t_notify || now;
    const cnt = days => others.filter(r => !r.parent_id && sameDevice_(r.device, e.device) && evTime_(r) && t0 - evTime_(r) >= 0 && t0 - evTime_(r) <= days * 86400000).length + 1;
    const rc = settingNum_('repeat_count', 3), rd = settingNum_('repeat_days', 30);
    const rcs = settingNum_('repeat_count_short', 2), rds = settingNum_('repeat_days_short', 7);
    if (e.parent_id) { /* สายแจ้งย่อย ไม่นับซ้ำ */ } else if (cnt(rds) >= rcs) warnings.push('⚠ ขัดข้องซ้ำ: ' + e.device + ' เป็นครั้งที่ ' + cnt(rds) + ' ใน ' + rds + ' วัน');
    else if (cnt(rd) >= rc) warnings.push('⚠ ขัดข้องซ้ำ: ' + e.device + ' เป็นครั้งที่ ' + cnt(rd) + ' ใน ' + rd + ' วัน');
  }
  return { errors, warnings };
}

function nextEventId_(d) {
  const prefix = 'OUT-' + ('0' + ((d.getFullYear() + 543) % 100)).slice(-2) + ('0' + (d.getMonth() + 1)).slice(-2) + '-';
  let max = 0;
  idColumn_(SH.EVENTS).forEach(id => {
    if (id.indexOf(prefix) === 0) max = Math.max(max, +id.slice(prefix.length) || 0);
  });
  return prefix + ('000' + (max + 1)).slice(-4);
}

function materialRows_(items, eventId, date, user) {
  const master = {};
  table_(SH.MATERIAL).rows.forEach(m => { master[m.code] = m; });
  const rows = [], text = [];
  (items || []).forEach(it => {
    const m = master[it.code];
    const qty = num_(it.qty);
    if (!m) return;
    if (qty === null && !(it.code === 'M99' && it.name)) return;
    if (qty !== null && qty <= 0) return;
    const name = it.code === 'M99' && it.name ? it.name : m.name;
    const sp = sapResolve_(it.code, name, it.size || '', it.sap);
    rows.push({ id: '', event_id: eventId, date, code: it.code, name, size: it.size || '', qty: qty === null ? '' : qty, unit: it.unit || m.unit, raw: '', created_by: user, created_at: new Date(), work_type: 'CM', ref_id: eventId, sap_code: sp.code, sap_name: sp.name, price: sp.price });
    text.push(name + (it.size ? ' ' + it.size : '') + (qty === null ? '' : ' ×' + qty + ' ' + (it.unit || m.unit)));
  });
  return { rows, text: text.join('; ') };
}

function nextIds_(sheetName, prefix, n) {
  let max = 0;
  idColumn_(sheetName).forEach(id => { if (id.indexOf(prefix) === 0) max = Math.max(max, +id.slice(prefix.length) || 0); });
  return Array.from({ length: n }, (_, i) => prefix + ('00000' + (max + i + 1)).slice(-6));
}

/**
 * บันทึก/แก้ไขเหตุการณ์
 * payload = {event, materials:[{code,size,qty,unit,name}], confirm:boolean, reason:string}
 */
function apiSaveEvent(token, payload) {
  const s = auth_(token, 'event.write');
  const input = payload.event || {};
  const isUpdate = !!input.id;
  // ข้อ 21: ต้องจัดเวรกะปัจจุบันก่อนบันทึกเหตุการณ์ใหม่
  if (!isUpdate && !rosterCurrent_()) {
    return { ok: false, rosterRequired: true, errors: ['ยังไม่ได้จัดเวรของกะปัจจุบัน กรุณาจัดเวรก่อนบันทึกเหตุการณ์ใหม่'] };
  }
  return withLock_(() => {
    let existing = null;
    if (isUpdate) {
      existing = events_(true).find(r => r.id === input.id);
      if (!existing) return { ok: false, errors: ['ไม่พบรายการ ' + input.id] };
      if (isDeleted_(existing)) return { ok: false, errors: ['รายการนี้ถูกลบแล้ว'] };
      if (!String(payload.reason || '').trim()) return { ok: false, errors: ['กรุณาระบุเหตุผลการแก้ไข'] };
    }
    // ข้อ 30: รายงานประจำวันที่อนุมัติแล้ว → ล็อก
    const tNew = parseDT_(input.t_notify) || parseDT_(input.t_off) || parseDT_(input.date);
    const lockRep = lockedReportFor_(tNew) || (existing ? lockedReportFor_(evTime_(existing)) : null);
    if (lockRep) {
      const e0 = normalizeEventInput_(input);
      const v0 = validateEvent_(e0, isUpdate ? input.id : null);
      if (v0.errors.length) return { ok: false, errors: v0.errors };
      if (v0.warnings.length && !payload.confirm) return { ok: false, needConfirm: true, warnings: v0.warnings };
      if (ROLES[s.role].indexOf('report.approve') < 0) {
        const rq = createEditRequest_(s, isUpdate ? 'UPDATE' : 'CREATE', isUpdate ? input.id : '', lockRep, payload, existing ? diffEvent_(existing, e0) : summaryLine_(e0));
        return { ok: true, pendingApproval: true, requestId: rq, report: lockRep.id };
      }
      if (!payload.confirmLocked) return { ok: false, needLockConfirm: true, report: lockRep.id, reportDate: fmtDate_(lockRep.date instanceof Date ? lockRep.date : parseDT_(lockRep.date)) };
    }
    return saveEventCore_(payload, s, { existing, lockRep });
  });
}

/** บันทึกจริง (ใช้ทั้งบันทึกปกติและตอนอนุมัติคำขอแก้ไขหลังปิดรายงาน) — ต้องอยู่ใน withLock_ */
function saveEventCore_(payload, s, opt) {
  opt = opt || {};
  const input = payload.event || {};
  const isUpdate = !!input.id;
  const existing = opt.existing || (isUpdate ? events_(true).find(r => r.id === input.id) : null);
  const e = normalizeEventInput_(input);
  const v = validateEvent_(e, isUpdate ? input.id : null);
  if (v.errors.length) return { ok: false, errors: v.errors, warnings: v.warnings };
  if (v.warnings.length && !payload.confirm) return { ok: false, needConfirm: true, warnings: v.warnings };

  const now = new Date();
  const id = isUpdate ? input.id : nextEventId_(e.date);
  const mats = payload.materials ? materialRows_(payload.materials, id, e.date, s.display) : null;
  const rec = {};
  SCHEMA.Events.forEach(([k]) => { if (e[k] !== undefined) rec[k] = e[k] === null ? '' : e[k]; });
  delete rec.created_by; delete rec.created_at; delete rec.legacy; delete rec.dq; delete rec.deleted; delete rec.dq_ok;
  rec.id = id;
  if (rec.cause_type !== undefined) rec.excl = OMS_EXCL.indexOf(String(rec.cause_type || '')) >= 0 ? true : '';
  if (mats) rec.materials = mats.text;
  if (v.warnings.length) rec.dq = 'ยืนยันคำเตือน: ' + v.warnings.join(' ; ');
  // ข้อ 26: จำนวนผู้ใช้ไฟจาก GIS ถ้าไม่ได้กรอก
  if (rec.customers === '' || rec.customers == null) {
    const c = customersFromGis_(rec.type, regOf_(rec.device));
    if (c !== '') { rec.customers = c; rec.customers_src = 'GIS'; }
  } else if (input.customers_src !== 'GIS') rec.customers_src = 'กรอกเอง';
  const afterLock = !!opt.lockRep;

  if (!isUpdate) {
    rec.created_by = s.display; rec.created_at = now; rec.deleted = false;
    appendRows_(SH.EVENTS, [rec]);
    audit_(s.display, afterLock ? 'CREATE_AFTER_LOCK' : 'CREATE', 'Events', id, summaryLine_(rec),
      [opt.requestNote || '', v.warnings.length ? 'ยืนยันคำเตือน: ' + v.warnings.join(' ; ') : ''].filter(Boolean).join(' | '));
    if (afterLock) markReportChanged_(opt.lockRep, { event_id: id, kind: 'เพิ่มรายการ', by: opt.requestedBy || s.display, approved_by: s.display, reason: payload.reason || '', diff: summaryLine_(rec) });
  } else {
    const changes = {};
    Object.keys(rec).forEach(k => {
      const a = cmpVal_(existing[k]), b = cmpVal_(rec[k]);
      if (a !== b) changes[k] = [a, b];
    });
    const measDirty = !!payload.measurements;
    if (!Object.keys(changes).length && !mats && !measDirty && !payload.pm && !payload.animalGuard) return { ok: true, id, unchanged: true };
    if (Object.keys(changes).length || (mats && cmpVal_(existing.materials) !== cmpVal_(mats.text))) {
      rec.updated_by = s.display; rec.updated_at = now;
      if (!v.warnings.length) rec.dq = '';
      const rowNo = findRowById_(SH.EVENTS, input.id);
      if (!rowNo) return { ok: false, errors: ['ไม่พบแถวของ ' + input.id + ' ในชีต'] };
      updateRow_(SH.EVENTS, rowNo, rec);
      audit_(s.display, afterLock ? 'UPDATE_AFTER_LOCK' : 'UPDATE', 'Events', id, labelChanges_(changes),
        [payload.reason || '', opt.requestNote || ''].filter(Boolean).join(' | '));
      if (afterLock) markReportChanged_(opt.lockRep, { event_id: id, kind: 'แก้ไข', by: opt.requestedBy || s.display, approved_by: s.display, reason: payload.reason || '', diff: labelChanges_(changes) });
    }
  }
  if (mats) replaceMaterials_(id, mats.rows);
  if (payload.animalGuard && feature_('animal_guard')) saveAnimalGuard_(Object.assign({}, existing || {}, rec), payload.animalGuard, s.display);
  if (payload.measurements) syncEventMeasurements_(id, rec, payload.measurements, s.display);
  let pmId = '';
  if (payload.pm && payload.pm.category && ROLES[s.role].indexOf('pm.create') >= 0) pmId = pmFromEvent_(rec, payload.pm, s.display);
  if (payload.plannedId) linkPlannedEvent_(payload.plannedId, id, s.display);
  upsertDevice_(rec, s.display);
  invalidate_(SH.EVENTS);
  const alert = rec.parent_id ? null : syncAlertForDevice_(rec.device);
  if (!isUpdate && rec.type === 'T/L' && String(setting_('notify_hv_immediately', 'TRUE')).toUpperCase() === 'TRUE') {
    sendNotify_('⚡ T/L ' + rec.device, '⚡ เหตุการณ์ T/L\n' + summaryLine_(rec) + '\nบันทึกโดย ' + s.display);
  }
  try { hvAfterSave_(rec, existing, s); } catch (err) { console.warn('hvAfterSave_: ' + err.message); }
  return { ok: true, id, alert, pmId, afterLock, customers: rec.customers, customers_src: rec.customers_src || '' };
}

/** ข้อ 26: จำนวนผู้ใช้ไฟจาก GIS ตามประเภทเหตุการณ์ */
function customersFromGis_(type, reg) {
  if (type === 'MT') return 1;
  if (!reg) return '';
  const c = Number(reg.customers);
  if (!(c > 0)) return '';
  if (type === 'LT') return /หม้อแปลง/.test(String(reg.kind)) ? c : '';
  if (['D/F', 'T/L', 'บร.1'].indexOf(type) >= 0) return c;
  return '';
}

function diffEvent_(existing, e) {
  const ch = {};
  SCHEMA.Events.forEach(([k]) => {
    if (e[k] === undefined || ['created_by', 'created_at', 'legacy', 'dq', 'deleted', 'dq_ok', 'updated_by', 'updated_at'].indexOf(k) >= 0) return;
    const a = cmpVal_(existing[k]), b = cmpVal_(e[k] === null ? '' : e[k]);
    if (a !== b) ch[k] = [a, b];
  });
  return labelChanges_(ch);
}

/** ข้อ 15: ค่าตรวจวัดหน้างานจากฟอร์มเหตุการณ์ → ชีต Measurements (เพิ่ม/แก้/ลบ ตามรายการที่ส่งมา) */
function syncEventMeasurements_(eventId, rec, list, user) {
  const t = table_(SH.MEAS, true);
  const mine = t.rows.filter(r => r.event_id === eventId && !isDeleted_(r));
  const keep = {};
  const when = rec.t_on || rec.t_notify || rec.t_off || rec.date;
  const adds = [];
  (list || []).forEach(m => {
    const hasVal = ['ia', 'ib', 'ic', 'in', 'van', 'vbn', 'vcn', 'fuse_a', 'fuse_old_a'].some(k => num_(m[k]) !== null);
    if (!hasVal) return;
    const calc = calcMeasurement_(Object.assign({}, m, { kva: rec.kva, circuit: m.circuit || 'รวม' }));
    const row = {
      date: when instanceof Date ? new Date(when.getFullYear(), when.getMonth(), when.getDate()) : rec.date,
      time: when instanceof Date ? fmtHM_(when) : '', device: rec.device, device_kind: rec.device_kind, kva: rec.kva || '',
      circuit: m.circuit || 'รวม', ia: nz_(m.ia), ib: nz_(m.ib), ic: nz_(m.ic), in: nz_(m.in), van: nz_(m.van), vbn: nz_(m.vbn), vcn: nz_(m.vcn),
      fuse_a: nz_(m.fuse_a), fuse_old_a: nz_(m.fuse_old_a), fuse_code: rec.device2 || '', load_pct: calc.load_pct, unbal_pct: calc.unbal_pct,
      flags: [calc.flags, num_(m.fuse_old_a) !== null && num_(m.fuse_a) !== null && num_(m.fuse_old_a) !== num_(m.fuse_a) ? 'เปลี่ยนขนาดฟิวส์ ' + m.fuse_old_a + 'A → ' + m.fuse_a + 'A' : ''].filter(Boolean).join(' ; '),
      event_id: eventId, measured_by: rec.lead || '', note: 'จากฟอร์มบันทึกเหตุการณ์',
    };
    const cur = m.id && mine.find(r => r.id === m.id);
    if (cur) { keep[cur.id] = 1; updateRow_(SH.MEAS, cur._row, Object.assign(row, { updated_by: user, updated_at: new Date() })); }
    else adds.push(Object.assign(row, { created_by: user, created_at: new Date(), deleted: false }));
  });
  mine.filter(r => !keep[r.id]).forEach(r => updateRow_(SH.MEAS, r._row, { deleted: true, updated_by: user, updated_at: new Date() }));
  if (adds.length) {
    const ids = nextIds_(SH.MEAS, 'MS-', adds.length);
    adds.forEach((a, i) => { a.id = ids[i]; });
    appendRows_(SH.MEAS, adds);
  }
  invalidate_(SH.MEAS);
}

function measOfEvent_(eventId) {
  return table_(SH.MEAS).rows.filter(r => r.event_id === eventId && !isDeleted_(r)).map(r => ({
    id: r.id, circuit: r.circuit, fuse_old_a: r.fuse_old_a, fuse_a: r.fuse_a, ia: r.ia, ib: r.ib, ic: r.ic, in: r.in,
    van: r.van, vbn: r.vbn, vcn: r.vcn, load_pct: r.load_pct, unbal_pct: r.unbal_pct, flags: r.flags,
    date: fmtDate_(r.date instanceof Date ? r.date : parseDT_(r.date)), time: r.time instanceof Date ? fmtHM_(r.time) : String(r.time || ''),
    measured_by: r.measured_by, note: r.note,
  }));
}

function cmpVal_(v) {
  if (v instanceof Date) return fmtDT_(v).replace(/ 00:00$/, '');
  if (v === null || v === undefined) return '';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  return String(v).trim();
}

function labelChanges_(changes) {
  const lab = {}; SCHEMA.Events.forEach(([k, l]) => { lab[k] = l; });
  return Object.keys(changes).map(k => (lab[k] || k) + ': "' + changes[k][0] + '" → "' + changes[k][1] + '"').join('\n');
}

function summaryLine_(r) {
  const t = r.t_off || r.t_notify;
  return [fmtDT_(t), r.voltage, r.type, r.device, (r.tambon ? 'ต.' + r.tambon : ''), r.location, '| ' + (r.cause_cat || ''), r.cause || ''].filter(Boolean).join(' ');
}

function replaceMaterials_(eventId, rows) {
  const t = table_(SH.MATUSE, true);
  const del = t.rows.filter(r => r.event_id === eventId).map(r => r._row).sort((a, b) => b - a);
  del.forEach(rn => t.sh.deleteRow(rn));
  invalidate_(SH.MATUSE);
  if (rows.length) {
    const ids = nextIds_(SH.MATUSE, 'MU-', rows.length);
    rows.forEach((r, i) => { r.id = ids[i]; });
    appendRows_(SH.MATUSE, rows);
  }
}

function upsertDevice_(rec, user) {
  if (!rec.device) return;
  const d = regOf_(rec.device);
  if (!d) {
    appendRows_(SH.DEVICES, [{ code: rec.device, key: deviceKey_(rec.device), source: 'แอป', customers: '', phase: '', kind: rec.device_kind, substation: rec.substation || '', feeder: rec.feeder || '', kva: rec.kva || '', tambon: rec.tambon || '', location: String(rec.location || '').slice(0, 80), lat: '', lon: '', note: '', updated_by: user, updated_at: new Date() }]);
  } else if (!d.tambon && rec.tambon) {
    const rowNo = findRowById_(SH.DEVICES, d.code, 'code');
    if (rowNo) updateRow_(SH.DEVICES, rowNo, { tambon: rec.tambon, updated_by: user, updated_at: new Date() });
  }
}

function apiDeleteEvent(token, id, reason) {
  const s = auth_(token, 'event.delete');
  if (!String(reason || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลการลบ' };
  return withLock_(() => {
    const r = events_(true).find(x => x.id === id);
    if (!r) return { ok: false, error: 'ไม่พบรายการ' };
    const lockRep = lockedReportFor_(evTime_(r));
    updateRow_(SH.EVENTS, findRowById_(SH.EVENTS, id) || r._row, { deleted: true, updated_by: s.display, updated_at: new Date() });
    audit_(s.display, lockRep ? 'DELETE_AFTER_LOCK' : 'DELETE', 'Events', id, summaryLine_(r), reason);
    if (lockRep) markReportChanged_(lockRep, { event_id: id, kind: 'ลบรายการ', by: s.display, approved_by: s.display, reason, diff: summaryLine_(r) });
    invalidate_(SH.EVENTS);
    syncAlertForDevice_(r.device);
    return { ok: true };
  });
