// =====================================================================  Measurements
function calcMeasurement_(m) {
  const I = ['ia', 'ib', 'ic'].map(k => num_(m[k])).filter(x => x !== null);
  const V = [['van', 'A'], ['vbn', 'B'], ['vcn', 'C']].map(([k, p]) => [num_(m[k]), p]).filter(x => x[0] !== null);
  const flags = [];
  let load = '', unbal = '';
  if (I.length) {
    const avg = I.reduce((a, b) => a + b, 0) / I.length, max = Math.max.apply(null, I);
    if (I.length === 3 && avg > 0) {
      unbal = Math.round((max - avg) / avg * 1000) / 10;
      if (unbal > settingNum_('unbal_warn_pct', 20)) flags.push('กระแสไม่สมดุล ' + unbal + '%');
    }
    const kva = num_(m.kva), fuse = num_(m.fuse_a);
    const whole = !m.circuit || m.circuit === 'รวม';
    if (whole && kva) {
      const irated = kva * 1000 / (Math.sqrt(3) * settingNum_('lv_ll_voltage', 400));
      load = Math.round(avg / irated * 1000) / 10;
      if (load > 100) flags.push('หม้อแปลงโหลดเกิน ' + load + '%');
      else if (load > settingNum_('load_warn_pct', 80)) flags.push('โหลดสูง ' + load + '%');
    } else if (fuse) {
      load = Math.round(max / fuse * 1000) / 10;
      if (load > 100) flags.push('กระแสเกินพิกัดฟิวส์ (' + max + 'A > ' + fuse + 'A)');
      else if (load > settingNum_('load_warn_pct', 80)) flags.push('กระแสสูงเทียบฟิวส์ ' + load + '%');
    }
    const inn = num_(m.in);
    if (inn !== null && avg > 0 && inn > 0.5 * avg) flags.push('กระแสนิวทรัลสูง (' + inn + 'A)');
  }
  const vmin = settingNum_('v_min', 200), vmax = settingNum_('v_max', 242);
  V.forEach(([v, p]) => {
    if (v < vmin) flags.push('แรงดันต่ำ เฟส ' + p + ' = ' + v + 'V');
    if (v > vmax) flags.push('แรงดันสูง เฟส ' + p + ' = ' + v + 'V');
  });
  return { load_pct: load, unbal_pct: unbal, flags: flags.join(' ; ') };
}

