function apiSaveMeasurement(token, m, reason) {
  const s = auth_(token, 'meas.write');
  const n = normDevice_(m.device);
  const errors = [];
  if (!m.date) errors.push('กรุณาระบุวันที่');
  if (!n.code) errors.push('กรุณาระบุรหัสอุปกรณ์');
  ['ia', 'ib', 'ic', 'in', 'van', 'vbn', 'vcn', 'fuse_a', 'kva'].forEach(k => {
    const v = num_(m[k]);
    if (m[k] !== '' && m[k] != null && v === null) errors.push(k + ' ต้องเป็นตัวเลข');
    if (v !== null && v < 0) errors.push(k + ' ต้องไม่ติดลบ');
  });
  ['van', 'vbn', 'vcn'].forEach(k => { const v = num_(m[k]); if (v !== null && (v < 50 || v > 300)) errors.push(k + ' = ' + v + 'V ผิดปกติ (ควรเป็นค่า เฟส-นิวทรัล)'); });
  if (!['ia', 'ib', 'ic', 'van', 'vbn', 'vcn'].some(k => num_(m[k]) !== null)) errors.push('กรุณากรอกกระแสหรือแรงดันอย่างน้อย 1 ค่า');
  if (errors.length) return { ok: false, errors };
  return withLock_(() => {
    const calc = calcMeasurement_(Object.assign({}, m, { kva: num_(m.kva) || n.kva }));
    const rec = {
      date: parseDT_(m.date), time: hmOf_(m.time), device: n.code, device_kind: n.kind, kva: num_(m.kva) || n.kva || '',
