      van: nz_(m.van), vbn: nz_(m.vbn), vcn: nz_(m.vcn), fuse_a: nz_(m.fuse_a),
      fuse_code: String(m.fuse_code || '').toUpperCase(), load_pct: calc.load_pct, unbal_pct: calc.unbal_pct,
