    byMonth[key] = byMonth[key] || {};
    byMonth[key][mk] = (byMonth[key][mk] || 0) + (Number(m.qty) || 0);
  });
  const ms = Array.from(months).sort();
  const rows = Object.keys(agg).map(k => {
    const a = agg[k];
    return { code: a.code, name: a.name, size: a.size, unit: a.unit, qty: Math.round(a.qty * 100) / 100, events: a.events.size, unparsed: a.unparsed, months: ms.map(mm => (byMonth[k] || {})[mm] || 0) };
  }).sort((x, y) => String(x.code).localeCompare(String(y.code)) || (y.qty - x.qty));
  const tsv = [['รหัส', 'วัสดุ', 'ขนาด', 'หน่วย', 'จำนวนรวม', 'จำนวนงาน'].concat(ms.map(monthLabel_)).join('\t')]
    .concat(rows.map(r => [r.code, r.name, r.size, r.unit, r.qty, r.events].concat(r.months).join('\t'))).join('\n');
  return { months: ms.map(monthLabel_), rows, tsv, workType: wtF || 'ทั้งหมด',
