/** v1.12 ข้อ 108: เวลา 'HH:mm' จาก Date / '1899-12-30 23:32' / '23:32' */
function hmOf_(v) {
  if (v instanceof Date) return fmtHM_(v);
  const m = String(v || '').match(/(\d{1,2}):(\d{2})(?!.*\d{1,2}:\d{2})/);
  return m ? ('0' + m[1]).slice(-2) + ':' + m[2] : '';
}

/**
 * Reports.gs : Dashboard, สรุปรายกะ/วัน/สัปดาห์/เดือน/ไตรมาส/ปี, แจ้งเตือนขัดข้องซ้ำ,
 *              แผนที่ Heatmap, การส่งแจ้งเตือน (Email / LINE / Google Chat), งานอัตโนมัติ
 */

const PLANNED_TYPES = ['แผนดับไฟ', 'ปลดเพื่อทำงาน'];

/** ข้อความสถานที่ ไม่ซ้ำหมู่/ตำบลที่มีอยู่แล้วในช่องสถานที่ */
function placeText_(e, maxLen) {
  const loc = String(e.location || '').trim();
  const parts = [];
  if (e.moo && !new RegExp('ม\\.\\s*' + e.moo + '(?!\\d)').test(loc)) parts.push('ม.' + e.moo);
  if (e.tambon && loc.indexOf(e.tambon) < 0) parts.push('ต.' + e.tambon);
  parts.push(maxLen ? loc.slice(0, maxLen) : loc);
  return parts.filter(Boolean).join(' ');
}

// =====================================================================  Period helpers
function dayStart_(d) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
function addDays_(d, n) { const x = new Date(d); x.setDate(x.getDate() + n); return x; }

/**
 * ช่วงเวลาของรายงาน
 * period: shift|day|week|month|quarter|year|custom ; basis: calendar|fiscal (ปีงบประมาณ ต.ค.–ก.ย.)
 */
function periodRange_(o) {
  const base = parseDT_(o.date) || new Date();
  const d0 = dayStart_(base);
  const y = d0.getFullYear(), m = d0.getMonth();
  const fiscal = o.basis === 'fiscal';
  let from, to, label;
  switch (o.period) {
    case 'shift': {
      const sh = shifts_().find(x => x.name === o.shift) || shifts_()[0];
      from = new Date(y, m, d0.getDate(), Math.floor(sh.s / 60), sh.s % 60);
      to = new Date(y, m, d0.getDate(), Math.floor(sh.e / 60), sh.e % 60);
      if (sh.e <= sh.s) to = addDays_(to, 1);
      label = 'ประจำ' + sh.name + ' วันที่ ' + thDate_(d0) + ' (' + sh.start + '–' + sh.end + ' น.)';
      break;
    }
    case 'week': {
      const dow = (d0.getDay() + 6) % 7; // จันทร์ = 0
      from = addDays_(d0, -dow); to = addDays_(from, 7);
      const last = addDays_(to, -1);
      label = 'ประจำสัปดาห์ ' + from.getDate() + (from.getMonth() !== last.getMonth() ? ' ' + TH_MONTH[from.getMonth()] : '') + '–' + thDate_(last);
      break;
    }
    case 'month':
      from = new Date(y, m, 1); to = new Date(y, m + 1, 1);
      label = 'ประจำเดือน' + TH_MONTH_FULL[m] + ' ' + (y + 543);
      break;
    case 'quarter': {
      if (fiscal) {
        const fq = Math.floor(((m + 3) % 12) / 3); // ต.ค.=Q1
        const startMonth = (fq * 3 + 9) % 12;
        const sy = startMonth > m ? y - 1 : y;
        from = new Date(sy, startMonth, 1); to = new Date(sy, startMonth + 3, 1);
        const fy = (startMonth >= 9 ? sy + 1 : sy) + 543;
        label = 'ไตรมาส ' + (fq + 1) + ' ปีงบประมาณ ' + fy + ' (' + TH_MONTH[from.getMonth()] + '–' + TH_MONTH[addDays_(to, -1).getMonth()] + ')';
      } else {
        const q = Math.floor(m / 3);
        from = new Date(y, q * 3, 1); to = new Date(y, q * 3 + 3, 1);
        label = 'ไตรมาส ' + (q + 1) + '/' + (y + 543) + ' (' + TH_MONTH[q * 3] + '–' + TH_MONTH[q * 3 + 2] + ')';
      }
      break;
    }
    case 'year':
      if (fiscal) {
        const fy = m >= 9 ? y + 1 : y;
        from = new Date(fy - 1, 9, 1); to = new Date(fy, 9, 1);
        label = 'ปีงบประมาณ ' + (fy + 543) + ' (1 ต.ค. ' + (fy + 542) + ' – 30 ก.ย. ' + (fy + 543) + ')';
      } else {
        from = new Date(y, 0, 1); to = new Date(y + 1, 0, 1);
        label = 'ประจำปี ' + (y + 543);
      }
      break;
    case 'custom': {
      from = dayStart_(parseDT_(o.from) || d0); to = addDays_(dayStart_(parseDT_(o.to) || d0), 1);
      label = 'ระหว่างวันที่ ' + thDate_(from) + ' – ' + thDate_(addDays_(to, -1));
      break;
    }
    default:
      from = d0; to = addDays_(d0, 1);
      label = 'ประจำวันที่ ' + thDate_(d0);
  }
  return { from, to, label };
}

/** เหตุการณ์ในช่วงเวลา (ไม่นับสายแจ้งย่อยที่ผูกกับเหตุการณ์หลัก — ข้อ 25) */
function inRange_(evs, from, to, includeChildren) {
  return evs.filter(e => { const t = evTime_(e); return t && t >= from && t < to && (includeChildren || !e.parent_id); });
}

function applyFilters_(evs, f) {
  return evs.filter(e => (!f.voltage || e.voltage === f.voltage) && (!f.type || e.type === f.type) &&
    (!f.tambon || e.tambon === f.tambon) && (!f.feeder || e.feeder === f.feeder) && (!f.cause_cat || e.cause_cat === f.cause_cat));
}

function countBy_(arr, fn, top) {
  const m = {};
  arr.forEach(x => { const k = fn(x); if (k === '' || k == null) return; m[k] = (m[k] || 0) + 1; });
  let out = Object.keys(m).map(k => ({ k, n: m[k] })).sort((a, b) => b.n - a.n);
  if (top) out = out.slice(0, top);
  return out;
}
function avg_(arr) { const a = arr.filter(x => x !== '' && x != null && !isNaN(x)).map(Number); return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
function sum_(arr) { return arr.filter(x => x !== '' && x != null && !isNaN(x)).map(Number).reduce((s, x) => s + x, 0); }
function r1_(x) { return x == null ? null : Math.round(x * 10) / 10; }

function kpis_(evs) {
  const unplanned = evs.filter(e => PLANNED_TYPES.indexOf(e.type) < 0);
  const sustained = unplanned.filter(e => Number(e.off_min) >= 1);
  const restore = unplanned.map(e => e.t_notify && e.t_on ? (e.t_on - e.t_notify) / 60000 : null).filter(x => x != null && x >= 0);
  const dispatch = unplanned.map(e => e.t_notify && e.t_depart ? (e.t_depart - e.t_notify) / 60000 : null).filter(x => x != null && x >= 0);
  const custEv = unplanned.filter(e => Number(e.customers) > 0);
  const total = Number(setting_('total_customers')) || 0;
  const ci = sum_(custEv.map(e => e.customers));
  const cmi = sum_(custEv.filter(e => Number(e.off_min) >= 1).map(e => Number(e.customers) * Number(e.off_min)));
  return {
    total: evs.length,
    hv: evs.filter(e => e.voltage === 'HV').length,
    lv: evs.filter(e => e.voltage === 'LV').length,
    planned: evs.length - unplanned.length,
    momentary: unplanned.filter(e => e.type === 'T/R').length,
    offMinTotal: Math.round(sum_(sustained.map(e => e.off_min))),
    offMinAvg: r1_(avg_(sustained.map(e => e.off_min))),
    restoreAvg: r1_(avg_(restore)),
    dispatchAvg: r1_(avg_(dispatch)),
    workMinTotal: Math.round(sum_(evs.map(e => e.work_min))),
    open: evs.filter(e => e.status && e.status !== STATUS.CLOSED).length,
    dq: evs.filter(e => e.dq).length,
    devicesRepeated: countBy_(evs.filter(e => e.device), e => e.device).filter(x => x.n >= 2).length,
    saifi: total ? Math.round(ci / total * 10000) / 10000 : null,
    saidi: total ? Math.round(cmi / total * 100) / 100 : null,
    custCoverage: unplanned.length ? Math.round(custEv.length / unplanned.length * 100) : 0,
  };
}

// =====================================================================  Dashboard
function apiDashboard(token, f) {
  auth_(token, 'view');
  f = f || {};
  const rg = periodRange_(f.period ? f : { period: 'custom', from: f.from, to: f.to });
  const all = events_();
  const evs = applyFilters_(inRange_(all, rg.from, rg.to), f);
  const span = rg.to - rg.from;
  const prev = applyFilters_(inRange_(all, new Date(rg.from - span), rg.from), f);
  const days = Math.round(span / 86400000);

  // แนวโน้ม: รายวันถ้า ≤ 62 วัน, ไม่เช่นนั้นรายเดือน
  const byDay = days <= 62;
  const keyOf = d => byDay ? fmtDate_(d) : Utilities.formatDate(d, APP.tz, 'yyyy-MM');
  const labels = [];
  if (byDay) { for (let d = new Date(rg.from); d < rg.to; d = addDays_(d, 1)) labels.push(fmtDate_(d)); }
  else { for (let d = new Date(rg.from.getFullYear(), rg.from.getMonth(), 1); d < rg.to; d = new Date(d.getFullYear(), d.getMonth() + 1, 1)) labels.push(keyOf(d)); }
  const types = table_(SH.ETYPE).rows.map(r => String(r.code));
  const trend = {};
  types.forEach(t => { trend[t] = labels.map(() => 0); });
  const offTrend = labels.map(() => 0);
  evs.forEach(e => {
    const i = labels.indexOf(keyOf(evTime_(e)));
    if (i < 0) return;
    const ty = e.type || 'ไม่ระบุ';
    if (!trend[ty]) trend[ty] = labels.map(() => 0);
    trend[ty][i]++;
    if (Number(e.off_min) >= 1) offTrend[i] += Number(e.off_min);
  });

  const hours = Array(24).fill(0);
  const heat = Array.from({ length: 7 }, () => Array(24).fill(0));
  evs.forEach(e => {
    const t = e.t_off || e.t_notify;
    if (!t) return;
    hours[t.getHours()]++;
    heat[(t.getDay() + 6) % 7][t.getHours()]++;
  });

  const devAgg = {};
  evs.forEach(e => {
    if (!e.device) return;
    const a = devAgg[deviceKey_(e.device)] || (devAgg[deviceKey_(e.device)] = { device: e.device, kind: e.device_kind, n: 0, off: 0, last: null, tambon: e.tambon, location: e.location, causes: {} });
    a.n++; a.off += Number(e.off_min) || 0;
    if (!a.last || evTime_(e) > a.last) { a.last = evTime_(e); a.location = e.location || a.location; a.tambon = e.tambon || a.tambon; }
    a.causes[e.cause_cat] = (a.causes[e.cause_cat] || 0) + 1;
  });
  const topDevices = Object.keys(devAgg).map(k => devAgg[k]).sort((a, b) => b.n - a.n || b.off - a.off).slice(0, 20)
    .map(a => ({ device: a.device, kind: a.kind, n: a.n, off: a.off, last: fmtDT_(a.last), tambon: a.tambon, location: String(a.location).slice(0, 50), cause: Object.keys(a.causes).sort((x, y) => a.causes[y] - a.causes[x])[0] }));

  const crew = {};
  evs.forEach(e => {
    [e.lead, e.crew1, e.crew2].forEach((p, i) => {
      if (!p) return;
      const c = crew[p] || (crew[p] = { name: p, lead: 0, crew: 0, min: 0 });
      if (i === 0) c.lead++; else c.crew++;
      c.min += Number(e.work_min) || 0;
    });
  });

  const offByCause = {};
  evs.forEach(e => { if (Number(e.off_min) >= 1) offByCause[e.cause_cat] = (offByCause[e.cause_cat] || 0) + Number(e.off_min); });

  return {
    range: { from: fmtDate_(rg.from), to: fmtDate_(addDays_(rg.to, -1)), label: rg.label, days },
    kpi: kpis_(evs), kpiPrev: kpis_(prev),
    trend: { labels: labels.map(l => byDay ? l.slice(8) + '/' + l.slice(5, 7) : monthLabel_(l)), byType: trend, offMin: offTrend, unit: byDay ? 'day' : 'month' },
    byType: countBy_(evs, e => e.type || 'ไม่ระบุ'),
    byVoltage: countBy_(evs, e => e.voltage),
    byCause: countBy_(evs, e => e.cause_cat),
    offByCause: Object.keys(offByCause).map(k => ({ k, n: Math.round(offByCause[k]) })).sort((a, b) => b.n - a.n),
    byTambon: countBy_(evs, e => e.tambon),
    byFeeder: countBy_(evs, e => e.feeder, 20),
    byWeather: countBy_(evs, e => e.weather),
    byShift: countBy_(evs, e => e.shift),
    byAction: countBy_(evs, e => e.action_cat),
    byReceiver: countBy_(evs, e => e.receiver),
    byVehicle: countBy_(evs, e => e.vehicle),
    hours, heat, topDevices,
    crew: Object.keys(crew).map(k => crew[k]).sort((a, b) => (b.lead + b.crew) - (a.lead + a.crew)),
  };
}

