  if (!evs.length) {
    L.push('✅ ไม่มีเหตุการณ์ไฟฟ้าขัดข้อง');
  } else {
    L.push('รวม ' + k.total + ' เหตุการณ์  (HV ' + k.hv + ' | LV ' + k.lv + ')');
    L.push(countBy_(evs, e => e.type).map(x => '• ' + x.k + ' ' + x.n).join('  '));
    L.push('⏱ ไฟดับรวม ' + minToText_(k.offMinTotal) + ' | เฉลี่ย ' + minToText_(k.offMinAvg) + '/ครั้ง');
    if (k.restoreAvg != null) L.push('🚚 รับแจ้ง→จ่ายไฟได้ เฉลี่ย ' + minToText_(k.restoreAvg));
    if (k.saidi != null && k.custCoverage) L.push('📈 SAIFI ' + k.saifi + ' | SAIDI ' + k.saidi + ' นาที (มีข้อมูลผู้ใช้ไฟ ' + k.custCoverage + '% ของเหตุการณ์)');
    L.push('');
    L.push('🔎 สาเหตุหลัก');
    countBy_(evs, e => e.cause_cat, 5).forEach(x => L.push('   - ' + x.k + ' ' + x.n + ' ครั้ง'));
    const tb = countBy_(evs, e => e.tambon, 5);
    if (tb.length) L.push('📍 พื้นที่: ' + tb.map(x => x.k + ' ' + x.n).join(', '));
    const wx = countBy_(evs.filter(e => e.weather && e.weather !== 'ปกติ'), e => e.weather);
    if (wx.length) L.push('🌧 สภาพอากาศ: ' + wx.map(x => x.k + ' ' + x.n).join(', '));
  }
  // ขัดข้องซ้ำ (ณ สิ้นช่วง)
  const asOf = rg.to < new Date() ? rg.to : new Date();
  const rep = computeRepeats_(all, asOf, settingNum_('repeat_count', 3), settingNum_('repeat_days', 30))
    .filter(r => r.events.some(e => evTime_(e) >= rg.from));
  if (rep.length) {
    L.push('');
    L.push('⚠️ อุปกรณ์ขัดข้องซ้ำ (≥' + settingNum_('repeat_count', 3) + ' ครั้ง/' + settingNum_('repeat_days', 30) + ' วัน)');
    rep.slice(0, 10).forEach(r => L.push('   - ' + r.device + ' ' + r.count + ' ครั้ง ' + placeText_(r, 30)));
  }
  const open = evs.filter(e => e.status && e.status !== STATUS.CLOSED);
  if (open.length) {
