    L.push('⏳ งานค้าง ' + open.length + ' รายการ: ' + open.map(e => e.id + ' ' + e.device).join(', '));
  }
  const detailed = ['shift', 'day'].indexOf(o.period || 'day') >= 0 || (o.period === 'custom' && (rg.to - rg.from) <= 2 * 86400000);
  if (detailed && evs.length) {
    L.push('');
    L.push('📝 รายการ');
    evs.forEach((e, i) => {
      const crew = [e.lead, e.crew1, e.crew2].filter(Boolean).map(n => String(n).split(' ')[0]).join('/');
      L.push((i + 1) + ') ' + fmtHM_(e.t_off || e.t_notify) + ' ' + e.type + ' ' + (e.device || '-') + ' ' + placeText_(e, 40));
      L.push('    สาเหตุ: ' + (e.cause || e.cause_cat) + (e.action ? ' / แก้ไข: ' + e.action : '') +
        (Number(e.off_min) >= 1 ? ' (' + minToText_(e.off_min) + ')' : '') + (crew ? ' ทีม: ' + crew : ''));
    });
    const heads = countBy_(evs, e => e.head).map(x => x.k);
    if (heads.length) { L.push(''); L.push('หัวหน้าเวร: ' + heads.join(', ')); }
  } else if (evs.length) {
    // ตารางรายเดือน/รายวันย่อ
    const span = (rg.to - rg.from) / 86400000;
    const keyOf = span > 35 ? (d => Utilities.formatDate(d, APP.tz, 'yyyy-MM')) : (d => fmtDate_(d));
    const g = countBy_(evs, e => keyOf(evTime_(e))).sort((a, b) => a.k.localeCompare(b.k));
    L.push('');
    L.push(span > 35 ? '📅 รายเดือน' : '📅 รายวัน');
    g.forEach(x => {
      const sub = evs.filter(e => keyOf(evTime_(e)) === x.k);
      const lab = span > 35 ? monthLabel_(x.k) : thDate_(parseDT_(x.k));
      L.push('   ' + lab + ': ' + x.n + ' (' + typeBreak_(sub) + ')');
    });
    const top = countBy_(evs.filter(e => e.device), e => e.device, 5);
    if (top.length) { L.push(''); L.push('🏷 อุปกรณ์ขัดข้องบ่อย: ' + top.map(x => x.k + ' (' + x.n + ')').join(', ')); }
  }
  L.push('');
  L.push('ข้อมูล ณ ' + Utilities.formatDate(new Date(), APP.tz, 'dd/MM/') + (new Date().getFullYear() + 543) + ' ' + fmtHM_(new Date()) + ' น.');

  const cols = ['รหัส', 'วันที่', 'เวลาไฟดับ', 'เวลาจ่ายไฟ', 'นาที', 'กะ', 'แรงดัน', 'ประเภท', 'รหัสอุปกรณ์', 'ตำบล', 'สถานที่', 'กลุ่มสาเหตุ', 'สาเหตุ', 'การแก้ไข', 'พชง.', 'ชชง.1', 'ชชง.2', 'ผู้รับแจ้ง', 'สถานะ'];
  const clean = v => String(v == null ? '' : v).replace(/[\t\n\r]+/g, ' ');
  const tsv = [cols.join('\t')].concat(evs.map(e => [e.id, fmtDate_(e.date), fmtHM_(e.t_off), fmtHM_(e.t_on), e.off_min, e.shift, e.voltage, e.type, e.device, e.tambon, e.location, e.cause_cat, e.cause, e.action, e.lead, e.crew1, e.crew2, e.receiver, e.status].map(clean).join('\t'))).join('\n');
  return { title: 'สรุปไฟฟ้าขัดข้อง ' + rg.label, label: rg.label, text: L.join('\n'), tsv, count: evs.length, from: fmtDT_(rg.from), to: fmtDT_(rg.to) };
}

/** ข้อ 20: แยกตามประเภทเหตุการณ์ เรียง T/L · T/R · D/F · LT · MT · อื่นๆ แสดงเฉพาะที่มี */
function typeBreak_(evs) {
  const order = ['T/L', 'T/R', 'D/F', 'LT', 'MT'];
  const c = {}; evs.forEach(e => { const t = order.indexOf(e.type) >= 0 ? e.type : 'อื่นๆ'; c[t] = (c[t] || 0) + 1; });
  return order.concat(['อื่นๆ']).filter(t => c[t]).map(t => t + ' ' + c[t]).join(' · ');
}

// =====================================================================  Repeat alerts
/** อุปกรณ์ที่ขัดข้อง ≥ count ครั้ง ภายใน days วันก่อน asOf */
function computeRepeats_(evs, asOf, count, days) {
  const since = new Date(asOf - days * 86400000);
  const g = {};
  evs.forEach(e => {
    const t = evTime_(e);
    if (!e.device || e.parent_id || !t || t <= since || t > asOf) return;
    (g[deviceKey_(e.device)] = g[deviceKey_(e.device)] || []).push(e);
  });
  return Object.keys(g).filter(k => g[k].length >= count).map(k => {
    const list = g[k].sort((a, b) => evTime_(a) - evTime_(b));
    const last = list[list.length - 1];
    return { device: last.device, count: list.length, events: list, first: evTime_(list[0]), last: evTime_(last), tambon: last.tambon, location: last.location, kind: last.device_kind, feeder: last.feeder };
  }).sort((a, b) => b.count - a.count || b.last - a.last);
}

/** ค้นย้อนหลัง: อุปกรณ์ที่เคยมีหน้าต่าง days วันใดๆ ที่ขัดข้อง ≥ count ครั้ง */
function scanRepeatsHistory_(evs, count, days) {
  const g = {};
  evs.forEach(e => { if (e.device && !e.parent_id && evTime_(e)) (g[deviceKey_(e.device)] = g[deviceKey_(e.device)] || []).push(e); });
  const out = [];
  Object.keys(g).forEach(k => {
    const l = g[k].sort((a, b) => evTime_(a) - evTime_(b));
    let best = 0, bi = 0, bj = 0, i = 0;
    for (let j = 0; j < l.length; j++) {
      while (evTime_(l[j]) - evTime_(l[i]) > days * 86400000) i++;
      if (j - i + 1 > best) { best = j - i + 1; bi = i; bj = j; }
    }
    if (best >= count) out.push({ device: l[l.length - 1].device, count: best, total: l.length, events: l.slice(bi, bj + 1), first: evTime_(l[bi]), last: evTime_(l[bj]), tambon: l[bj].tambon, location: l[bj].location, kind: l[bj].device_kind, feeder: l[bj].feeder });
  });
  return out.sort((a, b) => b.count - a.count || b.total - a.total);
}

function serRepeat_(r) {
  return { device: r.device, count: r.count, total: r.total || r.count, first: fmtDT_(r.first), last: fmtDT_(r.last), tambon: r.tambon, location: String(r.location || '').slice(0, 60), kind: r.kind, feeder: r.feeder,
    events: r.events.map(e => ({ id: e.id, time: fmtDT_(evTime_(e)), type: e.type, cause_cat: e.cause_cat, cause: String(e.cause).slice(0, 70), action: String(e.action).slice(0, 50), off_min: e.off_min, phase: e.phase })) };
}

function apiRepeats(token, o) {
  auth_(token, 'view');
  o = o || {};
  const count = +o.count || settingNum_('repeat_count', 3);
  const days = +o.days || settingNum_('repeat_days', 30);
  let evs = events_();
  if (o.voltage) evs = evs.filter(e => e.voltage === o.voltage);
  let list;
  if (o.mode === 'history') {
    const rg = periodRange_({ period: 'custom', from: o.from, to: o.to });
    list = scanRepeatsHistory_(inRange_(evs, rg.from, rg.to), count, days);
  } else {
    list = computeRepeats_(evs, o.asOf ? addDays_(parseDT_(o.asOf), 1) : new Date(), count, days);
  }
  const alerts = {};
  table_(SH.ALERTS).rows.forEach(a => { if (a.status !== 'ปิดแล้ว' || !alerts[a.device]) alerts[a.device] = { id: a.id, status: a.status, ack_by: a.ack_by, ack_at: fmtDT_(a.ack_at), note: a.note }; });
  return { count, days, rows: list.slice(0, 300).map(r => Object.assign(serRepeat_(r), { alert: alerts[r.device] || null })) };
}

function apiAlertsList(token) {
  auth_(token, 'view');
  return table_(SH.ALERTS).rows.filter(a => a.id).reverse().map(a => ({ id: a.id, device: a.device, count: a.count, window: a.window, first: fmtDT_(a.first), last: fmtDT_(a.last), events: a.events, status: a.status, ack_by: a.ack_by, ack_at: fmtDT_(a.ack_at), note: a.note, created_at: fmtDT_(a.created_at),
    owner: a.owner || '', due: fmtDate_(a.due instanceof Date ? a.due : parseDT_(a.due)), closed_at: fmtDT_(a.closed_at), recheck: a.recheck || '', pm_id: a.pm_id || '',
    overdue: a.status !== 'ปิดแล้ว' && (a.due instanceof Date ? a.due : parseDT_(a.due)) && addDays_(a.due instanceof Date ? a.due : parseDT_(a.due), 1) < new Date() }));
}

function apiAckAlert(token, o) {
  const s = auth_(token, 'alert.ack');
  const allowed = ['ใหม่', 'รับทราบ', 'กำลังแก้ไข', 'ปิดแล้ว'];
  if (allowed.indexOf(o.status) < 0) return { ok: false, error: 'สถานะไม่ถูกต้อง' };
  if (o.status === 'ปิดแล้ว' && !isManager_(s) && permsOf_(s).indexOf('event.write') < 0) return { ok: false, error: 'ปิดเรื่องแจ้งเตือนได้โดยหัวหน้าหรือเจ้าหน้าที่สั่งการ' }; // v1.11 ข้อ 95
  return withLock_(() => {
    let a = table_(SH.ALERTS, true).rows.find(x => x.id === o.id);
    if (!a && o.device) {
      syncAlertForDevice_(o.device, true);
      a = table_(SH.ALERTS, true).rows.find(x => x.device === o.device && x.status !== 'ปิดแล้ว');
    }
    if (!a && o.device) {
      const id = nextIds_(SH.ALERTS, 'AL-', 1)[0];
      appendRows_(SH.ALERTS, [{ id, device: o.device, count: o.count || '', window: 'บันทึกจากการค้นย้อนหลัง', first: '', last: '', events: o.events || '', status: o.status, ack_by: s.display, ack_at: new Date(), note: o.note || '', created_at: new Date(), owner: o.owner || '', due: parseDT_(o.due) || '', closed_at: o.status === 'ปิดแล้ว' ? new Date() : '' }]);
      audit_(s.display, 'ALERT_' + o.status, 'Alerts', id + ' ' + o.device, o.note || '', '');
      return { ok: true };
    }
    if (!a) return { ok: false, error: 'ไม่พบรายการแจ้งเตือน' };
    const upd = { status: o.status, note: o.note || a.note, ack_by: s.display, ack_at: new Date() };
    if (o.owner !== undefined) upd.owner = o.owner;
    if (o.due !== undefined) upd.due = parseDT_(o.due) || '';
    if (o.status === 'ปิดแล้ว' && a.status !== 'ปิดแล้ว') { upd.closed_at = new Date(); upd.recheck = ''; }
    updateRow_(SH.ALERTS, a._row, upd);
    audit_(s.display, 'ALERT_' + o.status, 'Alerts', a.id + ' ' + a.device, o.note || '', '');
    return { ok: true };
  });
}

/** อัปเดตชีต Alerts สำหรับอุปกรณ์ หลังบันทึก/ลบเหตุการณ์ คืนค่า {level,count,days} ถ้าเข้าเกณฑ์ */
function syncAlertForDevice_(device, force, evsAll, silent) {
  if (!device) return null;
  const evs = (evsAll || events_()).filter(e => sameDevice_(e.device, device));
  const now = new Date();
  const rules = [
    { level: 'เร่งด่วน', count: settingNum_('repeat_count_short', 2), days: settingNum_('repeat_days_short', 7) },
    { level: 'เฝ้าระวัง', count: settingNum_('repeat_count', 3), days: settingNum_('repeat_days', 30) },
  ];
  let hit = null;
  for (const r of rules) {
    const rep = computeRepeats_(evs, now, r.count, r.days)[0];
    if (rep) { hit = Object.assign({ level: r.level, days: r.days }, rep); break; }
  }
  if (!hit && !force) return null;
  if (!hit) return null;
  const t = table_(SH.ALERTS, true);
  const open = t.rows.find(a => a.device === device && a.status !== 'ปิดแล้ว');
  const ids = hit.events.map(e => e.id).join(', ');
  if (open) {
    if (Number(open.count) !== hit.count || String(open.events) !== ids) {
      updateRow_(SH.ALERTS, open._row, { count: hit.count, window: hit.level + ' ' + hit.days + ' วัน', last: hit.last, events: ids, status: open.status === 'ปิดแล้ว' ? 'ใหม่' : open.status });
    }
  } else {
    const id = nextIds_(SH.ALERTS, 'AL-', 1)[0];
    appendRows_(SH.ALERTS, [{ id, device, count: hit.count, window: hit.level + ' ' + hit.days + ' วัน', first: hit.first, last: hit.last, events: ids, status: 'ใหม่', ack_by: '', ack_at: '', note: '', created_at: now }]);
    if (!silent) {
      sendNotify_('⚠️ ขัดข้องซ้ำ ' + device, '⚠️ แจ้งเตือนอุปกรณ์ขัดข้องซ้ำ (' + hit.level + ')\n' + device + ' (' + (hit.kind || '') + ') ขัดข้อง ' + hit.count + ' ครั้งใน ' + hit.days + ' วัน\n' +
        (hit.tambon ? 'ต.' + hit.tambon + ' ' : '') + String(hit.location || '') + '\n' +
        hit.events.map(e => '• ' + fmtDT_(evTime_(e)) + ' ' + e.type + ' ' + (e.cause_cat || '')).join('\n'));
    }
  }
  return { level: hit.level, count: hit.count, days: hit.days, device };
}

// =====================================================================  Map / heatmap
function hashJitter_(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  const a = ((h & 0xffff) / 0xffff) * 2 * Math.PI, r = (((h >>> 16) & 0x7fff) / 0x7fff) * 0.012;
  return [Math.sin(a) * r, Math.cos(a) * r];
}

function apiMapData(token, f) {
  auth_(token, 'view');
  f = f || {};
  const rg = periodRange_(f.period ? f : { period: 'custom', from: f.from, to: f.to });
  const evs = applyFilters_(inRange_(events_(), rg.from, rg.to), f);
  const tam = {};
  table_(SH.TAMBON).rows.forEach(t => { tam[t.name] = { name: t.name, amphoe: t.amphoe, lat: +t.lat, lon: +t.lon, n: 0, off: 0, geometry: t.geometry ? JSON.parse(t.geometry) : null }; });
  const dev = {};
  table_(SH.DEVICES).rows.forEach(d => { dev[deviceKey_(d.code)] = d; });
  const pts = {};
  let unlocated = 0;
  evs.forEach(e => {
    if (e.tambon && tam[e.tambon]) { tam[e.tambon].n++; tam[e.tambon].off += Number(e.off_min) || 0; }
    const d = e.device ? dev[deviceKey_(e.device)] : null;
    let lat = null, lon = null, precise = false;
    if (d && d.lat !== '' && d.lon !== '' && !isNaN(+d.lat) && +d.lat) { lat = +d.lat; lon = +d.lon; precise = true; }
    else {
      const tn = e.tambon || (d && d.tambon);
      if (tn && tam[tn]) { const j = hashJitter_(e.device || e.id); lat = tam[tn].lat + j[0]; lon = tam[tn].lon + j[1]; }
    }
    if (lat == null) { unlocated++; return; }
    const key = (e.device || e.id) + '@' + lat.toFixed(5) + ',' + lon.toFixed(5);
    const p = pts[key] || (pts[key] = { lat, lon, device: e.device || '(ไม่ระบุ)', kind: e.device_kind, n: 0, off: 0, tambon: e.tambon, location: String(e.location || '').slice(0, 50), precise, types: {}, causes: {}, last: null });
    p.n++; p.off += Number(e.off_min) || 0;
    p.types[e.type] = (p.types[e.type] || 0) + 1;
    p.causes[e.cause_cat] = (p.causes[e.cause_cat] || 0) + 1;
    if (!p.last || evTime_(e) > p.last) p.last = evTime_(e);
  });
  return {
    range: { label: rg.label, from: fmtDate_(rg.from), to: fmtDate_(addDays_(rg.to, -1)) },
    total: evs.length, unlocated,
    tambons: Object.keys(tam).map(k => tam[k]),
    points: Object.keys(pts).map(k => { const p = pts[k]; p.last = fmtDT_(p.last); return p; }),
  };
}

// =====================================================================  Notifications
function sendNotify_(title, text) {
  const results = [];
  if (isTraining_()) return results;
  const emails = setting_('alert_emails');
  if (emails) {
    try { MailApp.sendEmail({ to: emails, subject: '[' + setting_('org_name', 'กฟส.กำแพงแสน') + '] ' + title, body: text }); results.push('email'); }
    catch (e) { console.error('email', e); }
  }
  if (sendLineTo_(setting_('line_to'), text)) results.push('line');
  const hook = setting_('gchat_webhook');
  if (hook) {
    try {
      UrlFetchApp.fetch(hook, { method: 'post', contentType: 'application/json; charset=UTF-8', muteHttpExceptions: true, payload: JSON.stringify({ text }) });
      results.push('gchat');
    } catch (e) { console.error('gchat', e); }
  }
  return results;
}

function apiSendSummary(token, o) {
  const s = auth_(token, 'view');
  const sum = buildSummary_(o || {});
  const ch = sendNotify_(sum.title, sum.text);
  audit_(s.display, 'SEND_SUMMARY', 'Report', sum.label, ch.join(','), '');
  return { ok: true, channels: ch };
}

// =====================================================================  Scheduled jobs
/** ทุกวัน 07:30 — ตรวจอุปกรณ์ขัดข้องซ้ำทั้งหมด + ส่งสรุปเมื่อวาน */
function jobDaily() {
  const fresh = withLock_(() => syncAllAlerts_(true)).fresh;
  try { withLock_(() => followUpRecheck_()); } catch (e) { console.error('recheck', e); }
  try { cleanupSessions_(); } catch (e) { console.error('sessions', e); }
  const y = addDays_(new Date(), -1);
  const sum = buildSummary_({ period: 'day', date: fmtDate_(y) });
  const openAlerts = table_(SH.ALERTS, true).rows.filter(a => a.status !== 'ปิดแล้ว');
  let text = sum.text;
  if (openAlerts.length) {
    text += '\n\n🔔 แจ้งเตือนขัดข้องซ้ำที่ยังไม่ปิด ' + openAlerts.length + ' รายการ' + (fresh ? ' (ใหม่ ' + fresh + ')' : '') + '\n' +
      openAlerts.slice(0, 15).map(a => '• ' + a.device + ' ' + a.count + ' ครั้ง [' + a.status + ']' + (a.owner ? ' ผู้รับผิดชอบ ' + a.owner : '')).join('\n');
  }
  sendNotify_(sum.title, text);
}

/** ทุกชั่วโมง — สรุปเมื่อจบกะ (ถ้าเปิดใช้), เตือนแผนดับไฟพรุ่งนี้, เตือนรายงานประจำวันล่าช้า */
function jobHourly() {
  try { plannedReminder_(); } catch (e) { console.error('planned', e); }
  try { dailyReportLateCheck_(); } catch (e) { console.error('daily late', e); }
  if (String(setting_('shift_summary_push', 'FALSE')).toUpperCase() !== 'TRUE') return;
  const now = new Date();
  const props = PropertiesService.getScriptProperties();
  shifts_().forEach(sh => {
    let end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(sh.e / 60), sh.e % 60);
    if (end > now) end = addDays_(end, -1);
    if (now - end > 75 * 60000) return;
    const start = new Date(end); start.setHours(Math.floor(sh.s / 60), sh.s % 60);
    if (start >= end) start.setDate(start.getDate() - 1);
    const key = 'shift_sent_' + sh.name + '_' + fmtDate_(start);
    if (props.getProperty(key)) return;
    const sum = buildSummary_({ period: 'shift', shift: sh.name, date: fmtDate_(start) });
    sendNotify_(sum.title, sum.text);
    props.setProperty(key, '1');
  });
}

/** ทุกคืน 01:00 — สำรองไฟล์ เก็บย้อนหลัง 30 ชุด */
function jobBackup() {
  const folder = getFolder_('backup_folder_id', 'OMS-กำแพงแสน-สำรองข้อมูล');
  const file = DriveApp.getFileById(ss_().getId());
  file.makeCopy('สำรอง_' + ss_().getName() + '_' + Utilities.formatDate(new Date(), APP.tz, 'yyyy-MM-dd_HHmm'), folder);
  const files = [];
  const it = folder.getFiles();
  while (it.hasNext()) files.push(it.next());
  files.sort((a, b) => b.getDateCreated() - a.getDateCreated()).slice(30).forEach(f => f.setTrashed(true));
}

