function pct_(a, b) { return b ? Math.round((a - b) / b * 100) : null; }
function chg_(a, b, lowerBetter) {
  const p = pct_(a, b);
  if (p === null) return '<span style="color:#888">–</span>';
  if (p === 0) return '<span style="color:#888">เท่าเดิม</span>';
  const good = lowerBetter ? p < 0 : p > 0;
  return '<span style="color:' + (good ? '#1b7f3b' : '#c62828') + '">' + (p > 0 ? '▲ ' : '▼ ') + Math.abs(p) + '%</span>';
}
function h_(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

/** ตารางแท่งแนวนอน (ใช้ได้กับตัวแปลง HTML→PDF ของ Apps Script) */
function barTable_(list, opt) {
  opt = opt || {};
  const rows = list.slice(0, opt.top || 12);
  if (!rows.length) return '<p class="muted">ไม่มีข้อมูล</p>';
  const max = Math.max.apply(null, rows.map(x => x.n)) || 1;
  const total = opt.total || rows.reduce((s, x) => s + x.n, 0);
  return '<table class="bars">' + rows.map(x =>
    '<tr><td class="lbl">' + h_(x.k) + '</td><td class="bar"><div style="width:' + Math.max(1, Math.round(x.n / max * 100)) + '%;background:' + (opt.color || '#5B2C83') + '">&nbsp;</div></td>' +
    '<td class="num">' + (opt.fmt ? opt.fmt(x.n) : x.n) + '</td>' + (opt.noPct ? '' : '<td class="pct">' + Math.round(x.n / total * 100) + '%</td>') + '</tr>').join('') + '</table>';
}

function reportData_(o) {
  o = Object.assign({ period: 'month' }, o || {});
  const rg = periodRange_(o);
  const all = events_();
  const evs = inRange_(all, rg.from, rg.to);
  const span = rg.to - rg.from;
  const now = new Date();
  const partial = rg.to > now && rg.from < now; // ช่วงที่ยังไม่จบ → เทียบช่วงก่อนหน้าเท่าระยะเวลาเดียวกัน
  const elapsed = (partial ? now : rg.to) - rg.from;
  const prevFrom = o.period === 'month' ? new Date(rg.from.getFullYear(), rg.from.getMonth() - 1, 1) : new Date(rg.from - span);
  const prevTo = partial ? new Date(Math.min(+rg.from, +prevFrom + elapsed)) : rg.from;
  const prev = inRange_(all, prevFrom, prevTo);
  const lyFrom = new Date(rg.from); lyFrom.setFullYear(lyFrom.getFullYear() - 1);
  const lyTo = new Date(+lyFrom + elapsed);
  const ly = inRange_(all, lyFrom, lyTo);
  const ytdFrom = new Date(rg.from.getFullYear(), 0, 1);
  const ytd = inRange_(all, ytdFrom, rg.to);
  // 12 เดือนย้อนหลัง
  const trend = [];
  for (let i = 11; i >= 0; i--) {
    const a = new Date(rg.from.getFullYear(), rg.from.getMonth() - i, 1), b = new Date(a.getFullYear(), a.getMonth() + 1, 1);
    const e = inRange_(all, a, b);
    trend.push({ k: TH_MONTH[a.getMonth()] + ' ' + String(a.getFullYear() + 543).slice(-2), n: e.length, hv: e.filter(x => x.voltage === 'HV').length, lv: e.filter(x => x.voltage === 'LV').length, off: Math.round(sum_(e.filter(x => Number(x.off_min) >= 1).map(x => x.off_min))) });
  }
  const offByCause = {};
  evs.forEach(e => { if (Number(e.off_min) >= 1) offByCause[e.cause_cat] = (offByCause[e.cause_cat] || 0) + Number(e.off_min); });
  const devAgg = {};
  evs.forEach(e => {
    if (!e.device) return;
    const a = devAgg[deviceKey_(e.device)] || (devAgg[deviceKey_(e.device)] = { device: e.device, kind: e.device_kind, n: 0, off: 0, e });
    a.n++; a.off += Number(e.off_min) || 0;
    if (evTime_(e) > evTime_(a.e)) a.e = e;
  });
  const reps = computeRepeats_(all, rg.to < new Date() ? rg.to : new Date(), settingNum_('repeat_count', 3), settingNum_('repeat_days', 30))
    .filter(r => r.events.some(e => evTime_(e) >= rg.from));
  const alertRows = {};
  table_(SH.ALERTS).rows.forEach(a => { alertRows[a.device] = a; });
  return {
    // v1.12 ข้อ 104/105: ช่วงที่ใช้เทียบ + แยกแรงสูง/แรงต่ำ
    prevRange: { from: prevFrom, to: prevTo }, lyRange: { from: lyFrom, to: lyTo }, prev,
    kH: kpis_(evs.filter(e => e.voltage === 'HV')), kL: kpis_(evs.filter(e => e.voltage === 'LV')),
    o, rg, evs, partial, asOf: partial ? now : null, k: kpis_(evs), kp: kpis_(prev), kl: kpis_(ly), ky: kpis_(ytd), lyHas: ly.length > 0, trend,
    byType: countBy_(evs, e => e.type), byCause: countBy_(evs, e => e.cause_cat),
    byCauseType: countBy_(evs.filter(e => PLANNED_TYPES.indexOf(e.type) < 0), e => e.cause_type || '(ยังไม่ระบุตาม OMS)'), byPart: countBy_(evs.filter(e => e.part), e => e.part),
    known: { k: evs.filter(e => e.known === 'ทราบสาเหตุ' || (e.cause_type && e.known !== 'สันนิษฐาน')).length, p: evs.filter(e => e.known === 'สันนิษฐาน').length, n: evs.filter(e => PLANNED_TYPES.indexOf(e.type) < 0).length }, rcaMonth: o.period === 'month' ? Utilities.formatDate(rg.from, APP.tz, 'yyyy-MM') : '',
    offByCause: Object.keys(offByCause).map(k => ({ k, n: Math.round(offByCause[k]) })).sort((a, b) => b.n - a.n),
    byTambon: countBy_(evs, e => e.tambon), byFeeder: countBy_(evs, e => e.feeder, 10), byShift: countBy_(evs, e => e.shift),
    byWeather: countBy_(evs, e => e.weather),
    topDevices: Object.keys(devAgg).map(k => devAgg[k]).sort((a, b) => b.n - a.n || b.off - a.off).slice(0, 10),
    longest: evs.filter(e => Number(e.off_min) >= 1 && PLANNED_TYPES.indexOf(e.type) < 0).sort((a, b) => b.off_min - a.off_min).slice(0, 5),
    tl: evs.filter(e => e.type === 'T/L'),
    reps, alertRows,
    open: evs.filter(e => e.status && e.status !== STATUS.CLOSED),
  };
}

/** v1.12 ข้อ 104: ช่วงวันที่แบบสั้น (to = ไม่รวม) */
function rangeTh_(a, b) {
  const e = new Date(+b - 1);
  if (a.getFullYear() === e.getFullYear() && a.getMonth() === e.getMonth()) return a.getDate() + (a.getDate() === e.getDate() ? '' : '–' + e.getDate()) + ' ' + TH_MONTH[a.getMonth()] + ' ' + (a.getFullYear() + 543);
  return thDate_(a) + ' – ' + thDate_(e);
}
function chgText_(a, b, label, unit) {
  const p = pct_(a, b);
  return p === null ? '' : (p === 0 ? ' เท่ากับ' : (p > 0 ? ' เพิ่มขึ้น ' : ' ลดลง ') + Math.abs(p) + '% จาก') + label + ' (' + b + (unit || ' ครั้ง') + ')';
}
function execHtml_(L) {
  return L.map(s => s && s.h ? '<div style="font-weight:bold;color:#5B2C83;margin-top:6px">' + h_(s.h) + '</div>' : '<div>• ' + h_(s) + '</div>').join('');
}
/** v1.12 ข้อ 105: บทสรุปผู้บริหาร แยกระบบแรงสูง/แรงต่ำ — คืน [{h}|string] */
function executiveSummary_(d) {
  const k = d.k, kp = d.kp, L = [];
  if (!k.total) return ['ไม่มีเหตุการณ์ไฟฟ้าขัดข้องในช่วงนี้'];
  const pr = d.prevRange ? 'ช่วงก่อนหน้า ' + rangeTh_(d.prevRange.from, d.prevRange.to) : 'ช่วงก่อนหน้า';
  L.push({ h: 'ภาพรวม' });
  L.push('เกิดเหตุการณ์ไฟฟ้าขัดข้องรวม ' + k.total + ' ครั้ง (ระบบแรงสูง ' + k.hv + ' ครั้ง, ระบบแรงต่ำ ' + k.lv + ' ครั้ง)' +
    chgText_(k.total, kp.total, pr) + ' ไฟดับรวม ' + minToText_(k.offMinTotal) + ' เฉลี่ย ' + minToText_(k.offMinAvg) + ' ต่อครั้ง');
  [['HV', 'ระบบแรงสูง'], ['LV', 'ระบบแรงต่ำ']].forEach(([v, name]) => {
    const e = d.evs.filter(x => x.voltage === v); if (!e.length) return;
    const ep = (d.prev || []).filter(x => x.voltage === v), kv = kpis_(e), kvp = kpis_(ep);
    L.push({ h: name + ' (' + e.length + ' ครั้ง)' });
    L.push('จำนวนเหตุการณ์ ' + e.length + ' ครั้ง' + chgText_(e.length, ep.length, pr) + ' · ไฟดับรวม ' + minToText_(kv.offMinTotal) + ' เฉลี่ย ' + minToText_(kv.offMinAvg) + ' ต่อครั้ง');
    const c = countBy_(e, x => x.cause_cat);
    if (c[0]) L.push('สาเหตุอันดับ 1 คือ "' + c[0].k + '" ' + c[0].n + ' ครั้ง (' + Math.round(c[0].n / e.length * 100) + '%)' + (c[1] ? ' รองลงมาคือ "' + c[1].k + '" ' + c[1].n + ' ครั้ง' : ''));
    const t = countBy_(e, x => x.tambon)[0];
    const top = v === 'HV' ? countBy_(e, x => x.feeder)[0] : countBy_(e, x => x.device)[0];
