function hvlvTable_(evs, fn, top, label) {
  const m = {};
  evs.forEach(e => { const k = fn(e); if (k === '' || k == null) return; const a = m[k] || (m[k] = { k, hv: 0, lv: 0, n: 0 }); a.n++; if (e.voltage === 'HV') a.hv++; else if (e.voltage === 'LV') a.lv++; });
  const rows = Object.keys(m).map(k => m[k]).sort((a, b) => b.n - a.n).slice(0, top || 99);
  if (!rows.length) return '<div class="muted">ไม่มีข้อมูล</div>';
  return '<table class="grid"><tr><th style="text-align:left">' + label + '</th><th>แรงสูง</th><th>แรงต่ำ</th><th>รวม</th></tr>' +
    rows.map(r => '<tr><td>' + h_(r.k) + '</td><td class="num">' + (r.hv || '–') + '</td><td class="num">' + (r.lv || '–') + '</td><td class="num b">' + r.n + '</td></tr>').join('') + '</table>';
}

