/** สร้าง PDF เก็บใน Drive (+ ส่งอีเมลถ้า o.email) */
function makeReportPdf_(o, user) {
  const r = buildReportHtml_(o);
  const blob = HtmlService.createHtmlOutput(r.html).getBlob().getAs(MimeType.PDF).setName(r.fileName);
  const folder = getFolder_('report_folder_id', 'OMS-กำแพงแสน-รายงาน');
  const file = folder.createFile(blob);
  let sentTo = '';
  if (o.email && !isTraining_()) {
    sentTo = String(o.to || setting_('report_emails') || '').trim();
    if (sentTo) {
      MailApp.sendEmail({
        to: sentTo,
        subject: '[' + setting_('org_name', 'กฟส.กำแพงแสน') + '] รายงานสรุปเหตุการณ์ไฟฟ้าขัดข้อง ' + r.label,
        body: 'เรียน ผู้บริหาร\n\nขอส่งรายงานสรุปเหตุการณ์ไฟฟ้าขัดข้อง ' + r.label + ' ตามไฟล์แนบ\n\nสรุปโดยย่อ\n' + r.summary.map(s => '• ' + s).join('\n') +
          (o.comment ? '\n\nความเห็นเพิ่มเติม: ' + o.comment : '') + '\n\n' + setting_('report_prepared_by', APP.dept),
        attachments: [blob],
      });
    }
