  audit_(user, 'REPORT_PDF', 'Report', r.label, file.getName() + (sentTo ? ' → ' + sentTo : ''), '');
  return { r, blob, file, sentTo };
}

function apiReportPdf(token, o) {
  const s = auth_(token, 'view');
