/** ส่งข้อความ (เช่น ข้อความแจ้งเหตุ) เข้ากลุ่ม LINE OA / Google Chat */
function apiSendText(token, text, ref) {
  const s = auth_(token, 'event.write');
  if (isTraining_()) return { ok: false, error: 'โหมดฝึกหัด: ระบบไม่ส่งข้อความออก (คัดลอกข้อความได้ตามปกติ)' };
  if (!String(text || '').trim()) return { ok: false, error: 'ไม่มีข้อความ' };
  const lineOk = setting_('line_channel_token') && setting_('line_to');
  const ch = [];
  if (lineOk) {
    const res = UrlFetchApp.fetch('https://api.line.me/v2/bot/message/push', {
      method: 'post', contentType: 'application/json', muteHttpExceptions: true,
      headers: { Authorization: 'Bearer ' + setting_('line_channel_token') },
      payload: JSON.stringify({ to: setting_('line_to'), messages: [{ type: 'text', text: String(text).slice(0, 4900) }] }),
    });
    if (res && res.getResponseCode && res.getResponseCode() !== 200) return { ok: false, error: 'LINE ตอบกลับ ' + res.getResponseCode() + ': ' + res.getContentText().slice(0, 200) };
    ch.push('LINE');
  }
  if (setting_('gchat_webhook')) {
    UrlFetchApp.fetch(setting_('gchat_webhook'), { method: 'post', contentType: 'application/json; charset=UTF-8', muteHttpExceptions: true, payload: JSON.stringify({ text }) });
    ch.push('Google Chat');
  }
  if (!ch.length) return { ok: false, error: 'ยังไม่ได้ตั้งค่า LINE Messaging API หรือ Google Chat ในชีต Settings' };
  audit_(s.display, 'SEND_MESSAGE', 'Events', ref || '', ch.join(','), '');
  return { ok: true, channels: ch };
}

/**
 * Ops.gs (v1.3) : ชุดงานประจำกะ, สถานะชุดปฏิบัติการ, งาน PM, แผนดับไฟ, ตรวจทานข้อมูลเดิม,
 *                 ติดตามผลแจ้งเตือน, โหมดฝึกหัด, การอัปเกรด v1.3
 */

// =====================================================================  Shift helpers
function shiftByName_(name) { return shifts_().find(x => x.name === name) || null; }
function shiftsSorted_() { return shifts_().slice().sort((a, b) => a.s - b.s); }

/** ช่วงเวลาของกะ (date = วันที่เริ่มกะ) */
function shiftRange_(date, name) {
  const sh = shiftByName_(name) || shifts_()[0];
  const d = dayStart_(date);
  const from = new Date(d.getFullYear(), d.getMonth(), d.getDate(), Math.floor(sh.s / 60), sh.s % 60);
  let to = new Date(d.getFullYear(), d.getMonth(), d.getDate(), Math.floor(sh.e / 60), sh.e % 60);
  if (sh.e <= sh.s) to = addDays_(to, 1);
  return { from, to, start: sh.start, end: sh.end };
}

/** กะก่อนหน้า (ติดกัน) */
function prevShift_(date, name) {
  const list = shiftsSorted_();
  const i = list.findIndex(x => x.name === name);
  if (i > 0) return { date: dayStart_(date), name: list[i - 1].name };
  return { date: addDays_(dayStart_(date), -1), name: list[list.length - 1].name };
}

function currentShift_() { const s = shiftOf_(new Date()); return { date: s.date, name: s.name }; }
function currentShiftKey_() { const s = currentShift_(); return fmtDate_(s.date) + '|' + s.name; }

// =====================================================================  Roster (ข้อ 21)
const ROSTER_FIELDS = ['head', 'center', 't1_lead', 't1_crew1', 't1_crew2', 't1_vehicle', 't2_lead', 't2_crew1', 't2_crew2', 't2_vehicle'];
const ROSTER_LABEL = { head: 'หัวหน้าเวร', center: 'เจ้าหน้าที่สั่งการ', t1_lead: 'ชุดที่ 1 พชง.', t1_crew1: 'ชุดที่ 1 ชชง.1', t1_crew2: 'ชุดที่ 1 ชชง.2', t1_vehicle: 'ชุดที่ 1 รถ', t2_lead: 'ชุดที่ 2 พชง.', t2_crew1: 'ชุดที่ 2 ชชง.1', t2_crew2: 'ชุดที่ 2 ชชง.2', t2_vehicle: 'ชุดที่ 2 รถ' };

function rosterId_(date, name) { return 'R' + Utilities.formatDate(date, APP.tz, 'yyyyMMdd') + '-' + String(name).replace(/\s+/g, ''); }

function rosterFor_(date, name) {
  const id = rosterId_(dayStart_(date), name);
  return table_(SH.ROSTER).rows.find(r => r.id === id) || null;
}
function rosterCurrent_() { const c = currentShift_(); return rosterFor_(c.date, c.name); }

function serRoster_(r) {
  if (!r) return null;
  const o = { id: r.id, date: fmtDate_(r.date instanceof Date ? r.date : parseDT_(r.date)), shift: r.shift };
  ROSTER_FIELDS.forEach(k => { o[k] = String(r[k] || ''); });
  try { o.swaps = r.swaps ? JSON.parse(r.swaps) : []; } catch (e) { o.swaps = []; }
  o.extras = extrasOf_(r);
  o.created_by = r.created_by; o.created_at = fmtDT_(r.created_at); o.updated_by = r.updated_by; o.updated_at = fmtDT_(r.updated_at);
  return o;
}

function apiRosterGet(token, o) {
  auth_(token, 'view');
  o = o || {};
  const cur = currentShift_();
  const date = o.date ? parseDT_(o.date) : cur.date;
  const name = o.shift || cur.name;
  const p = prevShift_(date, name);
  const rg = shiftRange_(date, name);
  return {
    date: fmtDate_(date), shift: name, start: rg.start, end: rg.end, key: fmtDate_(date) + '|' + name,
    isCurrent: fmtDate_(date) === fmtDate_(cur.date) && name === cur.name,
    roster: serRoster_(rosterFor_(date, name)),
    prev: serRoster_(rosterFor_(p.date, p.name)), prevLabel: p.name + ' ' + fmtDate_(p.date),
  };
}

function apiRosterSave(token, r) {
  const s = auth_(token, 'roster.write');
  r = r || {};
  const date = parseDT_(r.date) || currentShift_().date;
  const name = r.shift || currentShift_().name;
  if (!shiftByName_(name)) return { ok: false, errors: ['ไม่พบกะ ' + name] };
  const errors = [];
  if (!r.head) errors.push('กรุณาเลือกหัวหน้าเวร');
  if (!r.center) errors.push('กรุณาเลือกเจ้าหน้าที่สั่งการ');
  if (!r.t1_lead) errors.push('กรุณาเลือก พชง. ของชุดที่ 1');
  if ((r.t2_crew1 || r.t2_crew2 || r.t2_vehicle) && !r.t2_lead) errors.push('ชุดที่ 2: กรุณาเลือก พชง. หรือเว้นว่างทั้งชุด');
  const people = ['t1_lead', 't1_crew1', 't1_crew2', 't2_lead', 't2_crew1', 't2_crew2'].map(k => String(r[k] || '').trim()).filter(Boolean);
  if (new Set(people).size !== people.length) errors.push('มีชื่อซ้ำกันในชุดปฏิบัติการ');
  if (people.indexOf(r.center) >= 0) errors.push('เจ้าหน้าที่สั่งการซ้ำกับผู้ปฏิบัติงานในชุด');
  if (r.t1_vehicle && r.t1_vehicle === r.t2_vehicle) errors.push('ชุดที่ 1 และ 2 ใช้รถคันเดียวกัน');
  if (errors.length) return { ok: false, errors };
  return withLock_(() => {
    const id = rosterId_(dayStart_(date), name);
    const cur = table_(SH.ROSTER, true).rows.find(x => x.id === id);
    const rec = { id, date: dayStart_(date), shift: name };
    ROSTER_FIELDS.forEach(k => { rec[k] = String(r[k] || '').trim(); });
    const now = new Date();
    if (cur) {
      const ch = {};
      ROSTER_FIELDS.forEach(k => { if (cmpVal_(cur[k]) !== rec[k]) ch[ROSTER_LABEL[k]] = [cmpVal_(cur[k]), rec[k]]; });
      if (!Object.keys(ch).length) return { ok: true, roster: serRoster_(cur), unchanged: true };
      rec.updated_by = s.display; rec.updated_at = now;
      updateRow_(SH.ROSTER, findRowById_(SH.ROSTER, id) || cur._row, rec);
      audit_(s.display, 'UPDATE', 'ShiftRoster', id, Object.keys(ch).map(k => k + ': "' + ch[k][0] + '" → "' + ch[k][1] + '"').join('\n'), r.reason || '');
    } else {
      rec.swaps = '[]'; rec.created_by = s.display; rec.created_at = now;
      appendRows_(SH.ROSTER, [rec]);
      audit_(s.display, 'CREATE', 'ShiftRoster', id, ROSTER_FIELDS.filter(k => rec[k]).map(k => ROSTER_LABEL[k] + ': ' + rec[k]).join('\n'), '');
    }
    invalidate_(SH.ROSTER);
    return { ok: true, roster: serRoster_(table_(SH.ROSTER, true).rows.find(x => x.id === id)) };
  });
}

/** เปลี่ยนตัวระหว่างกะ: {date, shift, field, name, at:'HH:MM', note} */
function apiRosterSwap(token, o) {
  const s = auth_(token, 'roster.write');
  if (ROSTER_FIELDS.indexOf(o.field) < 0) return { ok: false, error: 'ตำแหน่งไม่ถูกต้อง' };
  const date = parseDT_(o.date) || currentShift_().date;
  const name = o.shift || currentShift_().name;
  return withLock_(() => {
    const id = rosterId_(dayStart_(date), name);
    const cur = table_(SH.ROSTER, true).rows.find(x => x.id === id);
    if (!cur) return { ok: false, error: 'ยังไม่ได้จัดเวรกะนี้' };
    const rg = shiftRange_(date, name);
    let at = new Date();
    if (o.at) {
      const [h, m] = String(o.at).split(':').map(Number);
      at = new Date(rg.from.getFullYear(), rg.from.getMonth(), rg.from.getDate(), h, m);
      if (at < rg.from) at = addDays_(at, 1);
    }
    let swaps = [];
    try { swaps = cur.swaps ? JSON.parse(cur.swaps) : []; } catch (e) { swaps = []; }
    const from = String(cur[o.field] || '');
    swaps.push({ at: fmtDT_(at), field: o.field, label: ROSTER_LABEL[o.field], from, to: String(o.name || ''), by: s.display, note: o.note || '' });
    const upd = { swaps: JSON.stringify(swaps), updated_by: s.display, updated_at: new Date() };
    upd[o.field] = String(o.name || '');
    updateRow_(SH.ROSTER, findRowById_(SH.ROSTER, id) || cur._row, upd);
    audit_(s.display, 'ROSTER_SWAP', 'ShiftRoster', id, ROSTER_LABEL[o.field] + ': "' + from + '" → "' + (o.name || '') + '" มีผล ' + fmtDT_(at), o.note || '');
    invalidate_(SH.ROSTER);
    return { ok: true, roster: serRoster_(table_(SH.ROSTER, true).rows.find(x => x.id === id)), swap: swaps[swaps.length - 1] };
  });
}

// =====================================================================  Crew status (ข้อ 24)
function crewStatus_(roster) {
  if (!roster) return [];
  const since = new Date(Date.now() - 12 * 3600000);
  const evs = events_().filter(e => e.t_depart && e.t_depart >= since);
  const out = [];
  [['t1', 'ชุดที่ 1'], ['t2', 'ชุดที่ 2']].forEach(([p, label]) => {
    const lead = String(roster[p + '_lead'] || '');
    if (!lead) return;
    const members = [lead, roster[p + '_crew1'], roster[p + '_crew2']].filter(Boolean);
    const mine = evs.filter(e => e.team === label || members.indexOf(e.lead) >= 0).sort((a, b) => b.t_depart - a.t_depart);
    const busy = mine.find(e => !e.t_back);
    const last = mine.find(e => e.t_back);
    out.push({
      team: label, lead, crew1: roster[p + '_crew1'] || '', crew2: roster[p + '_crew2'] || '', vehicle: roster[p + '_vehicle'] || '',
      busy: busy ? { id: busy.id, type: busy.type, device: busy.device, location: placeText_(busy, 40), since: fmtDT_(busy.t_depart), mins: Math.round((Date.now() - busy.t_depart) / 60000) } : null,
      lastBack: last ? fmtDT_(last.t_back) : '',
    });
  });
  if (feature_('extra_crew')) extrasOf_(roster).filter(x => !x.released_at).forEach(x => {
    const label = 'ชุดที่ ' + x.no;
    const members = [x.lead, x.crew1, x.crew2].filter(Boolean);
    const mine = evs.filter(e => e.team === label || members.indexOf(e.lead) >= 0).sort((a, b) => b.t_depart - a.t_depart);
    const busy = mine.find(e => !e.t_back), last = mine.find(e => e.t_back);
    out.push({ team: label, extra: true, called_at: x.called_at, reason: x.reason, lead: x.lead, crew1: x.crew1 || '', crew2: x.crew2 || '', vehicle: x.vehicle || '',
      busy: busy ? { id: busy.id, type: busy.type, device: busy.device, location: placeText_(busy, 40), since: fmtDT_(busy.t_depart), mins: Math.round((Date.now() - busy.t_depart) / 60000) } : null,
      lastBack: last ? fmtDT_(last.t_back) : '' });
  });
  return out;
}

// =====================================================================  Home (รวมทุกอย่างในการเรียกครั้งเดียว)
function apiHome(token) {
  const s = auth_(token, 'view');
  const today = fmtDate_(new Date());
  const roster = rosterCurrent_();
  const cur = currentShift_();
  const planned = table_(SH.PLANNED).rows.filter(p => p.id && p.status !== 'ยกเลิก' && fmtDate_(p.date instanceof Date ? p.date : parseDT_(p.date)) === today).map(serPlanned_);
  return {
    today: apiListEvents(token, { from: today, to: today, limit: 200 }),
    open: apiOpenEvents(token),
    alerts: apiAlertsList(token).filter(a => a.status !== 'ปิดแล้ว').slice(0, 20),
    latest: apiListEvents(token, { limit: 12 }),
    shift: { date: fmtDate_(cur.date), name: cur.name, key: currentShiftKey_() },
    roster: serRoster_(roster), crews: crewStatus_(roster), planned,
    dailyReport: dailyReportDue_(),
    pmOpen: table_(SH.PM).rows.filter(p => p.id && ['เสร็จ', 'ยกเลิก'].indexOf(p.status) < 0).length,
    pmMine: feature_('pm') ? table_(SH.PM).rows.filter(p => p.id && pmOpen_(p) && p.owner && String(p.owner) === s.display).length : 0,
    pmOverdue: feature_('pm') ? table_(SH.PM).rows.filter(p => p.id && pmOverdue_(p)).length : 0,
    reqOpen: feature_('requests') ? table_(SH.REQ).rows.filter(r => r.id && reqOpen_(r)).length : 0,
    reqOverdue: feature_('requests') ? table_(SH.REQ).rows.filter(r => r.id && reqOverdue_(r)).length : 0,
    reviewLeft: reviewItems_().length,
    hvOpen: apiHvOpen_(),
  };
}

// =====================================================================  PM queue (ข้อ 29)
const PM_CATEGORIES = ['ตัดต้นไม้', 'เปลี่ยนอุปกรณ์เสื่อมสภาพ', 'ตรวจ Thermoscan/ขันจุดต่อ', 'ติดครอบกันสัตว์', 'ปรับโหลด/ขนาดฟิวส์', 'แก้ไขถาวรหลังแก้ชั่วคราว', 'Hotline (ไม่ดับไฟ)', 'อื่นๆ'];
const HOTLINE_CAT = 'Hotline (ไม่ดับไฟ)';
/** ข้อ 16: รายการประเภทงาน PM แก้ได้ในชีต Settings (pm_categories คั่นด้วย ,) */
function pmCategories_() {
  const v = String(setting_('pm_categories', '') || '').split(',').map(x => x.trim()).filter(Boolean);
  return v.length ? v : PM_CATEGORIES;
}
const PM_STATUS = ['ใหม่', 'รับเรื่อง', 'กำลังดำเนินการ', 'ตีกลับ', 'เสร็จ', 'ยกเลิก'];
function pmOpen_(p) { return ['เสร็จ', 'ยกเลิก'].indexOf(p.status) < 0; }

/** สร้างหรือรวมงาน PM ของอุปกรณ์เดียวกันที่ยังเปิดอยู่ */
function pmUpsert_(o, user) {
  const t = table_(SH.PM, true);
  const reg = regOf_(o.device);
  const open = o.device && !o.noMerge ? t.rows.find(p => pmOpen_(p) && sameDevice_(p.device, o.device) && p.category === o.category) : null;
  const now = new Date();
  if (open) {
    const ids = String(open.event_ids || '').split(/[,\s]+/).filter(Boolean);
    if (o.event_id && ids.indexOf(o.event_id) < 0) ids.push(o.event_id);
    updateRow_(SH.PM, open._row, {
      event_ids: ids.join(', '), detail: [open.detail, o.detail].filter(Boolean).join(' | ').slice(0, 1500),
      priority: o.priority === 'ด่วน' || open.priority === 'ด่วน' ? 'ด่วน' : 'ปกติ', alert_id: open.alert_id || o.alert_id || '',
      updated_by: user, updated_at: now,
    });
    audit_(user, 'PM_MERGE', 'PMQueue', open.id, 'รวม ' + (o.event_id || o.alert_id || '') + ' เข้างานเดิม', '');
    return open.id;
  }
  const id = nextIds_(SH.PM, 'PM-', 1)[0];
  appendRows_(SH.PM, [{
    id, created_at: now, created_by: user, source: o.source || 'เหตุการณ์', event_ids: o.event_id || '', alert_id: o.alert_id || '',
    device: o.device || '', feeder: o.feeder || (reg && reg.feeder) || '', tambon: o.tambon || (reg && reg.tambon) || '',
    location: o.location || (reg && reg.location) || '', lat: reg && reg.lat !== '' ? reg.lat : '', lon: reg && reg.lon !== '' ? reg.lon : '',
    category: o.category, priority: o.priority === 'ด่วน' ? 'ด่วน' : 'ปกติ', detail: String(o.detail || '').slice(0, 1500),
    status: 'ใหม่', result: '', done_at: '', updated_by: '', updated_at: '', recheck: '', sent_at: '',
    owner: '', due: dueFor_(o.priority, now), history: JSON.stringify([{ at: fmtDT_(now), by: user, act: 'สร้างงาน', note: o.source || '' }]),
    photos: '', needs_outage: '', planned_id: '', photos_before: (o.photos_before || []).join(','),
  }]);
  audit_(user, 'PM_CREATE', 'PMQueue', id, [o.category, o.device, o.detail].filter(Boolean).join(' · '), '');
  return id;
}

function pmFromEvent_(rec, pm, user) {
  if (pmCategories_().indexOf(pm.category) < 0) return '';
  return pmUpsert_({ source: 'เหตุการณ์', event_id: rec.id, device: rec.device, feeder: rec.feeder, tambon: rec.tambon, location: placeText_(rec, 80),
    category: pm.category, priority: pm.priority, detail: pm.detail || (rec.cause || rec.cause_cat) }, user);
}

function apiPmCreate(token, o) {
  const s = auth_(token, 'pm.create');
  if (pmCategories_().indexOf(o.category) < 0) return { ok: false, error: 'กรุณาเลือกประเภทงาน' };
  if (!o.device && !o.location) return { ok: false, error: 'กรุณาระบุอุปกรณ์หรือสถานที่' };
  if (o.category === 'อื่นๆ' && !String(o.cat_note || '').trim()) return { ok: false, error: 'กรุณาระบุประเภทงาน (อื่นๆ)' };
  if (/มิเตอร์/.test(String(o.purpose || '')) && !(o.lat && o.lon)) return { ok: false, error: 'งานเปิดทางเข้ามิเตอร์: กรุณาปักหมุดหรือวางพิกัดตำแหน่งมิเตอร์' };
  return withLock_(() => {
    // v1.12 ข้อ 111: กดเพิ่มงานเอง = สร้างงานใหม่เสมอ (รวมงานเดิมเฉพาะที่มาจากแจ้งเตือนขัดข้องซ้ำ)
    const before = table_(SH.PM, true).rows.length;
    const id = pmUpsert_(Object.assign({ source: o.alert_id ? 'แจ้งเตือนขัดข้องซ้ำ' : 'บันทึกเอง' }, o, { device: o.device ? normDevice_(o.device).code : '', noMerge: !o.alert_id }), s.display);
    const merged = table_(SH.PM, true).rows.length === before;
    // ข้อ 3–4: พิกัดที่ปักหมุด · ผู้รับผิดชอบ/กำหนดเสร็จ (เฉพาะหัวหน้า/ผู้ช่วย/วิศวกร)
    const p = table_(SH.PM, true).rows.find(x => x.id === id);
    if (p) {
      const upd = {};
      if (o.category === 'อื่นๆ') upd.cat_note = String(o.cat_note || '').trim().slice(0, 100);
      // ข้อ 43: ตัดต้นไม้เพื่อเปิดทางเข้ามิเตอร์
      if (o.purpose) upd.purpose = String(o.purpose).slice(0, 60);
      if (o.meters) upd.meters = String(o.meters).replace(/[\s;]+/g, ',').replace(/,+/g, ',').replace(/^,|,$/g, '').slice(0, 300);
      if (o.lat && o.lon && !isNaN(+o.lat) && !isNaN(+o.lon)) { upd.lat = +o.lat; upd.lon = +o.lon; if (!p.tambon) upd.tambon = o.tambon || tambonAt_(+o.lat, +o.lon) || ''; }
      if (o.owner && (isManager_(s) || isStaff_(s))) {
        upd.owner = String(o.owner).trim(); upd.due = o.due ? parseDT_(o.due) : (p.due || dueFor_(p.priority));
        if (p.status === 'ใหม่') upd.status = 'รับเรื่อง';
        upd.history = histAdd_(p, s.display, 'assign', 'มอบหมาย ' + upd.owner + ' · กำหนด ' + thNum_(upd.due));
      } else if (o.due && isManager_(s)) upd.due = parseDT_(o.due);
      if (Object.keys(upd).length) updateRow_(SH.PM, p._row, upd);
    }
    if (o.alert_id) {
      const a = table_(SH.ALERTS, true).rows.find(x => x.id === o.alert_id);
      if (a) updateRow_(SH.ALERTS, a._row, { pm_id: id });
    }
    return { ok: true, id, merged };
  });
}

function mapsUrl_(lat, lon) { return lat && lon ? 'https://www.google.com/maps/search/?api=1&query=' + (+lat).toFixed(6) + ',' + (+lon).toFixed(6) : ''; }
function thNum_(d) { return d ? ('0' + d.getDate()).slice(-2) + '/' + ('0' + (d.getMonth() + 1)).slice(-2) + '/' + (d.getFullYear() + 543) : ''; }

function buildPmDaily_(date) {
  const d = date || new Date();
  const since = new Date(d.getTime() - 24 * 3600000);
  const open = table_(SH.PM).rows.filter(p => p.id && pmOpen_(p));
  const fresh = open.filter(p => p.created_at instanceof Date && p.created_at >= since);
  const L = ['🛠 งานส่งต่อ PM ประจำวันที่ ' + thNum_(d), setting_('org_name', 'กฟส.กำแพงแสน') + ' · ใหม่ ' + fresh.length + ' รายการ · ค้างทั้งหมด ' + open.length + ' รายการ', '━━━━━━━━━━━━━━'];
  const item = (p, i) => {
    const out = [(i + 1) + ') ' + p.id + ' ' + p.category + ' · ' + (p.device || '-') + ' ' + [p.tambon ? 'ต.' + p.tambon : '', String(p.location || '').slice(0, 40)].filter(Boolean).join(' ')];
    if (p.owner || p.due) out.push('   ผู้รับผิดชอบ: ' + (p.owner || '-') + (p.due instanceof Date ? ' · กำหนด ' + thNum_(p.due) : '') + (pmOverdue_(p) ? ' ⏰ เลยกำหนด' : ''));
    if (p.detail) out.push('   เหตุ: ' + String(p.detail).slice(0, 120));
    if (p.event_ids) out.push('   อ้างอิง: ' + p.event_ids);
    const u = mapsUrl_(p.lat, p.lon); if (u) out.push('   🗺 ' + u);
    return out.join('\n');
  };
  if (!fresh.length) L.push('✅ ไม่มีงานส่งต่อใหม่ใน 24 ชม.');
  else {
    const urg = fresh.filter(p => p.priority === 'ด่วน'), norm = fresh.filter(p => p.priority !== 'ด่วน');
    if (urg.length) { L.push('🔴 ด่วน'); urg.forEach((p, i) => L.push(item(p, i))); }
    if (norm.length) { L.push('🟡 ปกติ'); norm.forEach((p, i) => L.push(item(p, i))); }
  }
  const old = open.filter(p => fresh.indexOf(p) < 0).sort((a, b) => a.created_at - b.created_at);
  if (old.length) {
    L.push('');
    L.push('📋 งานค้างเดิม ' + old.length + ' รายการ');
    old.slice(0, 15).forEach(p => L.push('• ' + p.id + ' ' + p.category + ' ' + (p.device || '') + ' [' + p.status + '] ค้าง ' + Math.floor((d - p.created_at) / 86400000) + ' วัน' + (p.owner ? ' · ' + p.owner : '') + (pmOverdue_(p) ? ' ⏰ เลยกำหนด' : '')));
    const od = open.filter(pmOverdue_).length;
    if (od) L.push('⏰ เลยกำหนดเสร็จ ' + od + ' รายการ');
  }
  return { text: L.join('\n'), fresh: fresh.map(p => p.id) };
}

function apiPmDaily(token) { auth_(token, 'view'); return buildPmDaily_(new Date()); }

/** รายงานงาน PM ประจำสัปดาห์ (จันทร์–อาทิตย์ ของสัปดาห์ที่มีวันที่ date) */
function buildPmWeekly_(date) {
  const d0 = dayStart_(date || new Date());
  const from = addDays_(d0, -((d0.getDay() + 6) % 7)), to = addDays_(from, 7);
  const all = table_(SH.PM).rows.filter(p => p.id);
  const created = all.filter(p => p.created_at >= from && p.created_at < to);
  const done = all.filter(p => p.done_at instanceof Date && p.done_at >= from && p.done_at < to);
  const open = all.filter(pmOpen_).sort((a, b) => a.created_at - b.created_at);
  const recur = all.filter(p => /ยังเกิดซ้ำ/.test(String(p.recheck)));
  const label = 'สัปดาห์ ' + thNum_(from) + ' – ' + thNum_(addDays_(to, -1));
  const byCat = countBy_(open, p => p.category), byFeeder = countBy_(open, p => p.feeder, 10);
  const L = ['🛠 รายงานงาน PM ประจำ' + label, setting_('org_name', 'กฟส.กำแพงแสน'), '━━━━━━━━━━━━━━',
    'งานใหม่ ' + created.length + ' · เสร็จ ' + done.length + ' · ค้าง ' + open.length + (recur.length ? ' · ⚠ เกิดซ้ำหลังทำ PM ' + recur.length : '')];
  if (done.length) { L.push(''); L.push('✅ เสร็จในสัปดาห์'); done.forEach(p => L.push('• ' + p.id + ' ' + p.category + ' ' + (p.device || '') + ' — ' + String(p.result || '').slice(0, 80))); }
  if (open.length) { L.push(''); L.push('⏳ งานค้าง (เรียงจากเก่าสุด)'); open.slice(0, 25).forEach(p => L.push('• ' + p.id + ' ' + p.category + ' ' + (p.device || '') + ' [' + p.status + '] ' + Math.floor((Date.now() - p.created_at) / 86400000) + ' วัน' + (p.priority === 'ด่วน' ? ' 🔴' : ''))); }
  if (byCat.length) { L.push(''); L.push('📊 งานค้างตามประเภท: ' + byCat.map(x => x.k + ' ' + x.n).join(', ')); }
  if (byFeeder.length) L.push('📊 งานค้างตามฟีดเดอร์: ' + byFeeder.map(x => x.k + ' ' + x.n).join(', '));
  if (recur.length) { L.push(''); L.push('⚠ อุปกรณ์ที่ยังขัดข้องหลังทำ PM'); recur.forEach(p => L.push('• ' + p.id + ' ' + p.device + ' — ' + p.recheck)); }
  const row = p => '<tr><td>' + h_(p.id) + '</td><td>' + h_(p.category) + '</td><td>' + h_(p.device) + '</td><td>' + h_([p.tambon ? 'ต.' + p.tambon : '', p.location].filter(Boolean).join(' ')) + '</td><td>' + h_(p.priority) + '</td><td>' + h_(p.status) + '</td><td class="num">' + Math.floor((Date.now() - p.created_at) / 86400000) + '</td><td>' + h_(p.result || p.detail) + '</td></tr>';
  const head = '<tr><th>รหัส</th><th>ประเภท</th><th>อุปกรณ์</th><th>สถานที่</th><th>ความเร่งด่วน</th><th>สถานะ</th><th>อายุ (วัน)</th><th>รายละเอียด/ผล</th></tr>';
  const html = '<html><head><meta charset="utf-8"><style>@page{size:A4 landscape;margin:12mm}body{font-family:"Sarabun","Tahoma",sans-serif;font-size:10.5pt}h1{font-size:15pt;color:#5B2C83;margin:0}h2{font-size:12pt;color:#5B2C83;border-bottom:2px solid #5B2C83;margin:12px 0 4px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:3px 5px;font-size:9.5pt;vertical-align:top}th{background:#efe9f6}td.num{text-align:right}</style></head><body>' +
    '<h1>รายงานงานบำรุงรักษา (PM) ที่ส่งต่อจากงานแก้ไฟฟ้าขัดข้อง</h1><div>' + h_(setting_('org_name', 'กฟส.กำแพงแสน')) + ' · ' + h_(label) + ' · ออกรายงาน ' + thNum_(new Date()) + ' ' + fmtHM_(new Date()) + ' น.</div>' +
    '<h2>สรุป</h2><div>งานใหม่ ' + created.length + ' · เสร็จ ' + done.length + ' · ค้าง ' + open.length + ' · เกิดซ้ำหลังทำ PM ' + recur.length + '</div>' +
    '<h2>งานใหม่ในสัปดาห์</h2><table>' + head + (created.map(row).join('') || '<tr><td colspan="8">ไม่มี</td></tr>') + '</table>' +
    '<h2>งานที่เสร็จในสัปดาห์</h2><table>' + head + (done.map(row).join('') || '<tr><td colspan="8">ไม่มี</td></tr>') + '</table>' +
    '<h2>งานค้างทั้งหมด</h2><table>' + head + (open.map(row).join('') || '<tr><td colspan="8">ไม่มี</td></tr>') + '</table>' +
    (recur.length ? '<h2>อุปกรณ์ที่ยังขัดข้องหลังทำ PM</h2><table>' + head + recur.map(row).join('') + '</table>' : '') + '</body></html>';
  return { text: L.join('\n'), html, label, fileName: 'รายงานงานPM_' + Utilities.formatDate(from, APP.tz, 'yyyy-MM-dd') + '.pdf' };
}

function apiPmWeekly(token, o) {
  auth_(token, 'view');
  o = o || {};
  const r = buildPmWeekly_(parseDT_(o.date) || new Date());
  const out = { text: r.text, html: r.html, label: r.label, fileName: r.fileName };
  if (o.pdf) {
    const blob = HtmlService.createHtmlOutput(r.html).getBlob().getAs(MimeType.PDF).setName(r.fileName);
    out.dataUrl = 'data:application/pdf;base64,' + Utilities.base64Encode(blob.getBytes());
  }
  return out;
}

function apiPmSendDaily(token) {
  const s = auth_(token, 'pm.create');
  const r = buildPmDaily_(new Date());
  const ok = sendLineTo_(setting_('line_to_pm'), r.text);
  if (!ok) return { ok: false, error: isTraining_() ? 'โหมดฝึกหัด: ไม่ส่งข้อความออก' : 'ยังไม่ได้ตั้งค่า LINE กลุ่ม PM (line_to_pm) ในชีต Settings' };
  markPmSent_(r.fresh);
  audit_(s.display, 'PM_SEND_DAILY', 'PMQueue', r.fresh.join(','), '', '');
