}
function markPmSent_(ids) {
  const t = table_(SH.PM, true);
  t.rows.filter(p => ids.indexOf(p.id) >= 0).forEach(p => updateRow_(SH.PM, p._row, { sent_at: new Date() }));
}

/** 07:45 ทุกวัน */
function jobPmDaily() {
  if (!feature_('pm')) return;
  if (String(setting_('pm_daily_push', 'TRUE')).toUpperCase() !== 'TRUE') return;
  const r = buildPmDaily_(new Date());
  if (sendLineTo_(setting_('line_to_pm'), r.text)) markPmSent_(r.fresh);
}

/** จันทร์ 08:00 — รายงานของสัปดาห์ที่แล้ว */
function jobPmWeekly() {
  if (!feature_('pm')) return;
  const r = buildPmWeekly_(addDays_(new Date(), -7));
  sendLineTo_(setting_('line_to_pm'), r.text);
  const to = setting_('pm_report_emails');
  if (to && !isTraining_()) {
    const blob = HtmlService.createHtmlOutput(r.html).getBlob().getAs(MimeType.PDF).setName(r.fileName);
    MailApp.sendEmail({ to, subject: '[' + setting_('org_name', 'กฟส.กำแพงแสน') + '] รายงานงาน PM ' + r.label, body: r.text, attachments: [blob] });
  }
}

/** ตรวจซ้ำ 30 วันหลังทำ PM เสร็จ / หลังปิดแจ้งเตือน (เรียกจาก jobDaily) */
function followUpRecheck_() {
  const now = new Date();
  const evs = events_().filter(e => !e.parent_id);
  table_(SH.PM, true).rows.filter(p => p.status === 'เสร็จ' && p.done_at instanceof Date && !p.recheck && now - p.done_at >= 30 * 86400000 && p.device).forEach(p => {
    const n = evs.filter(e => sameDevice_(e.device, p.device) && evTime_(e) > p.done_at).length;
    updateRow_(SH.PM, p._row, { recheck: n ? 'ยังเกิดซ้ำ ' + n + ' ครั้งใน 30 วันหลังทำ PM' : 'ได้ผล ไม่เกิดซ้ำใน 30 วัน (' + thNum_(now) + ')' });
  });
  const reopen = [];
  table_(SH.ALERTS, true).rows.filter(a => a.status === 'ปิดแล้ว' && a.closed_at instanceof Date && !a.recheck && now - a.closed_at >= 30 * 86400000).forEach(a => {
    const list = evs.filter(e => sameDevice_(e.device, a.device) && evTime_(e) > a.closed_at);
    updateRow_(SH.ALERTS, a._row, { recheck: list.length ? 'ยังเกิดซ้ำ ' + list.length + ' ครั้ง — เปิดเรื่องใหม่' : 'ได้ผล ไม่เกิดซ้ำใน 30 วัน (' + thNum_(now) + ')' });
    if (list.length) reopen.push({ a, list });
  });
  reopen.forEach(({ a, list }) => {
    const id = nextIds_(SH.ALERTS, 'AL-', 1)[0];
    appendRows_(SH.ALERTS, [{ id, device: a.device, count: list.length, window: 'เกิดซ้ำหลังปิดเรื่อง ' + a.id, first: evTime_(list[0]), last: evTime_(list[list.length - 1]),
      events: list.map(e => e.id).join(', '), status: 'ใหม่', ack_by: '', ack_at: '', note: 'เปิดใหม่อัตโนมัติ: ยังขัดข้องหลังแก้ไขตาม ' + a.id, created_at: now, owner: a.owner || '' }]);
  });
  return reopen.length;
}

// =====================================================================  Planned outages (ข้อ 27)
const PLANNED_STATUS = ['วางแผน', 'แจ้งแล้ว', 'ดำเนินการแล้ว', 'ยกเลิก', 'เสนอ (รอยืนยัน)']; // v1.11 ข้อ 95: พนักงานเสนอร่างแผน → หัวหน้า/สั่งการยืนยัน
function serPlanned_(p) {
  const d = p.date instanceof Date ? p.date : parseDT_(p.date);
  const hm = v => v instanceof Date ? fmtHM_(v) : String(v || '');
  return { id: p.id, date: fmtDate_(d), t_start: hm(p.t_start), t_end: hm(p.t_end), device: p.device, feeder: p.feeder, tambon: p.tambon, location: p.location,
