function syncAllAlerts_(silent) {
  const evs = events_();
  const devices = {};
  const since = addDays_(new Date(), -Math.max(settingNum_('repeat_days', 30), settingNum_('repeat_days_short', 7)));
  evs.forEach(e => { if (e.device && !e.parent_id && evTime_(e) >= since) devices[deviceKey_(e.device)] = e.device; });
  let fresh = 0, updated = 0;
  Object.keys(devices).forEach(k => {
    const d = devices[k];
    const before = table_(SH.ALERTS).rows.find(a => sameDevice_(a.device, d) && a.status !== 'ปิดแล้ว');
    const r = syncAlertForDevice_(d, false, evs, silent);
    if (r && !before) fresh++;
    else if (r && before && Number(before.count) !== r.count) updated++;
  });
  return { fresh, updated };
}
function apiRunRepeatCheck(token) {
  const s = auth_(token, 'alert.ack');
  const r = withLock_(() => syncAllAlerts_(true));
  audit_(s.display, 'ALERT_CHECK', 'Alerts', '', 'ใหม่ ' + r.fresh + ' · อัปเดต ' + r.updated, '');
  return Object.assign({ ok: true }, r);
}

