function sendLineTo_(to, text) {
  const tok = setting_('line_channel_token');
  if (isTraining_() || !tok || !to) return false;
  try {
    const res = UrlFetchApp.fetch('https://api.line.me/v2/bot/message/push', {
      method: 'post', contentType: 'application/json', muteHttpExceptions: true,
      headers: { Authorization: 'Bearer ' + tok },
      payload: JSON.stringify({ to, messages: [{ type: 'text', text: String(text).slice(0, 4900) }] }),
    });
    return !res || !res.getResponseCode || res.getResponseCode() === 200;
  } catch (e) { console.error('line', e); return false; }
}

