}

/**
 * DailyReport.gs (v1.3 ข้อ 30) : รายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวัน (รอบ 08.30–08.30 น.)
 *  - ใบประหน้าแบบบันทึกข้อความ + ตารางแนบคอลัมน์ตาม Log book
 *  - ส่ง (เจ้าหน้าที่สั่งการกะ 2) → อนุมัติ/ปิดรายงาน (หัวหน้า/ผู้ช่วยหัวหน้า) → ล็อกเหตุการณ์
 *  - แก้หลังปิดรายงานต้องขออนุมัติ แล้วออกฉบับแก้ไข (เก็บฉบับเดิม)
 */

const DR_STATUS = { SUBMITTED: 'ส่งแล้ว', APPROVED: 'อนุมัติแล้ว', NEED_REV: 'ต้องออกฉบับแก้ไข', RETURNED: 'ตีกลับ' };

// ---------------------------------------------------------------- period
function drCutMin_() { const sh = shifts_().find(x => /2/.test(x.name)) || null; return sh ? sh.s : 510; }
function drPeriod_(dateStr) {
  const d = dayStart_(parseDT_(dateStr));
  const m = drCutMin_();
  const from = new Date(d.getFullYear(), d.getMonth(), d.getDate(), Math.floor(m / 60), m % 60);
  return { date: d, from, to: addDays_(from, 1) };
}
/** วันที่ของรายงานที่ครอบคลุมเวลา t */
function drDateOf_(t) {
  const m = drCutMin_();
  const d = dayStart_(t);
  return (t.getHours() * 60 + t.getMinutes()) < m ? addDays_(d, -1) : d;
}
function drId_(d) { return 'DR-' + Utilities.formatDate(d, APP.tz, 'yyyyMMdd'); }
function drRow_(d) { return table_(SH.DAILY).rows.find(r => r.id === drId_(d)) || null; }
function drMeta_(r) {
  let m = {};
  try { m = r && r.changes ? JSON.parse(r.changes) : {}; } catch (e) { m = {}; }
  m.pending = m.pending || []; m.versions = m.versions || [];
  return m;
}

/** รายงานที่อนุมัติแล้ว (ล็อก) ซึ่งครอบคลุมเวลา t */
function lockedReportFor_(t) {
  if (!(t instanceof Date)) return null;
  const r = drRow_(drDateOf_(t));
  return r && (r.status === DR_STATUS.APPROVED || r.status === DR_STATUS.NEED_REV) ? r : null;
}

function markReportChanged_(rep, entry) {
  const t = table_(SH.DAILY, true);
  const r = t.rows.find(x => x.id === rep.id);
  if (!r) return;
  const m = drMeta_(r);
  m.pending.push(Object.assign({ at: fmtDT_(new Date()) }, entry));
  updateRow_(SH.DAILY, r._row, { status: DR_STATUS.NEED_REV, changes: JSON.stringify(m) });
}

// ---------------------------------------------------------------- edit requests
function createEditRequest_(s, kind, eventId, rep, payload, diff) {
  const id = nextIds_(SH.EDITREQ, 'RQ-', 1)[0];
  appendRows_(SH.EDITREQ, [{
    id, event_id: eventId || '', report_id: rep.id, kind, requested_by: s.display, requested_at: new Date(),
    reason: payload.reason || '', payload: JSON.stringify(payload).slice(0, 49000), diff: String(diff || '').slice(0, 5000),
    status: 'รออนุมัติ', decided_by: '', decided_at: '', note: '',
  }]);
  audit_(s.display, 'EDIT_REQUEST', 'EditRequests', id, (eventId || 'เพิ่มรายการ') + ' ในรายงาน ' + rep.id + '\n' + diff, payload.reason || '');
  sendLineTo_(setting_('line_to'), '📝 คำขอแก้ไขหลังปิดรายงาน ' + id + '\n' + (eventId || 'เพิ่มรายการใหม่') + ' (รายงาน ' + rep.id.slice(3) + ')\nโดย ' + s.display + (payload.reason ? '\nเหตุผล: ' + payload.reason : '') + '\nรอหัวหน้า/ผู้ช่วยหัวหน้าอนุมัติ');
  return id;
}

function apiEditRequests(token, f) {
  auth_(token, 'view');
  f = f || {};
  return table_(SH.EDITREQ).rows.filter(q => q.id && (!f.status || q.status === f.status) && (!f.report || q.report_id === f.report)).reverse().slice(0, 200).map(q => ({
    id: q.id, event_id: q.event_id, report_id: q.report_id, kind: q.kind, requested_by: q.requested_by, requested_at: fmtDT_(q.requested_at),
    reason: q.reason, diff: q.diff, status: q.status, decided_by: q.decided_by, decided_at: fmtDT_(q.decided_at), note: q.note,
  }));
}

function apiDecideEditRequest(token, id, approve, note) {
  const s = auth_(token, 'report.approve');
  return withLock_(() => {
    const q = table_(SH.EDITREQ, true).rows.find(x => x.id === id);
    if (!q) return { ok: false, error: 'ไม่พบคำขอ ' + id };
    if (q.status !== 'รออนุมัติ') return { ok: false, error: 'คำขอนี้พิจารณาแล้ว (' + q.status + ')' };
    if (!approve) {
      if (!String(note || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลที่ไม่อนุมัติ' };
      updateRow_(SH.EDITREQ, q._row, { status: 'ไม่อนุมัติ', decided_by: s.display, decided_at: new Date(), note });
      audit_(s.display, 'EDIT_REJECT', 'EditRequests', id, q.event_id, note);
      return { ok: true };
    }
    const payload = JSON.parse(q.payload);
    payload.confirm = true;
    const existing = q.event_id ? events_(true).find(r => r.id === q.event_id) : null;
    const rep = table_(SH.DAILY, true).rows.find(r => r.id === q.report_id) || lockedReportFor_(parseDT_(payload.event.t_notify));
    const res = saveEventCore_(payload, s, { existing, lockRep: rep, requestedBy: q.requested_by, requestNote: 'อนุมัติคำขอ ' + id + ' ของ ' + q.requested_by });
    if (!res.ok) return { ok: false, error: (res.errors || ['บันทึกไม่สำเร็จ']).join(', ') };
    updateRow_(SH.EDITREQ, q._row, { status: 'อนุมัติ', decided_by: s.display, decided_at: new Date(), note: note || '', event_id: res.id });
    audit_(s.display, 'EDIT_APPROVE', 'EditRequests', id, res.id, note || '');
    return { ok: true, id: res.id };
  });
}

// ---------------------------------------------------------------- data
/** เลขไทย (ยกเว้นรหัสอุปกรณ์/เลขที่เหตุการณ์ เช่น 61-015091/160, KSA01F-05, OUT-6911-0001) */
function thaiDigits_(s) {
  return String(s).split(/([A-Za-z0-9]*\d[A-Za-z0-9]*(?:[-\/][A-Za-z0-9]+)+|[A-Za-z]+\d[A-Za-z0-9]*)/).map((part, i) => i % 2 ? part : part.replace(/\d/g, d => '๐๑๒๓๔๕๖๗๘๙'[+d])).join('');
}
function thLongDate_(d) { return d.getDate() + ' ' + TH_MONTH_FULL[d.getMonth()] + ' ' + (d.getFullYear() + 543); }
function hmDot_(d) { return Utilities.formatDate(d, APP.tz, 'HH.mm'); }
function durHM_(m) { if (m === '' || m == null || isNaN(m)) return ''; m = Math.round(m); return Math.floor(m / 60) + ':' + ('0' + (m % 60)).slice(-2); }
function positionOf_(name) {
  const d = table_(SH.DIR).rows.find(x => String(x.name) === String(name));
  return d ? String(d.position) : '';
}

function drData_(dateStr) {
  const p = drPeriod_(dateStr);
  const evs = inRange_(events_(), p.from, p.to, true).sort((a, b) => (a.t_off || evTime_(a)) - (b.t_off || evTime_(b)));
  const main = evs.filter(e => !e.parent_id);
  const k = kpis_(main);
  const rosters = [];
  let sd = p.date, sn = (shifts_().find(x => x.s === drCutMin_()) || shifts_()[0]).name;
  for (let i = 0; i < 3; i++) {
    const r = rosterFor_(sd, sn);
    rosters.push({ shift: sn, date: fmtDate_(sd), head: r ? r.head : '', center: r ? r.center : '' });
    const list = shiftsSorted_();
    const idx = list.findIndex(x => x.name === sn);
    if (idx === list.length - 1) { sn = list[0].name; sd = addDays_(sd, 1); } else sn = list[idx + 1].name;
  }
  return { p, evs, main, k, rosters, tl: main.filter(e => e.type === 'T/L'),
    longest: main.filter(e => Number(e.off_min) >= 1 && PLANNED_TYPES.indexOf(e.type) < 0).sort((a, b) => b.off_min - a.off_min)[0] || null,
    open: main.filter(e => e.status && e.status !== STATUS.CLOSED) };
}

/** ข้อความใบประหน้า (ตามแบบฟอร์มหน่วยงาน — ห้ามเพิ่มข้อมูลอื่น) */
function drBody_(d) {
  const p = d.p;
  return [APP.dept + ' ขอรายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวันที่ ' + thLongDate_(p.date) + ' ตั้งแต่เวลา ' + hmDot_(p.from) + ' น. ถึงวันที่ ' + thLongDate_(p.to) +
    ' เวลา ' + hmDot_(p.to) + ' น. รายละเอียดตามเอกสารแนบ'];
}

