  ['ลำดับที่', 6], ['วัน-เดือน-ปี', 12], ['เวลาไฟดับ|เริ่ม', 10], ['เวลาไฟดับ|ถึง', 10], ['เวลาไฟดับ|รวม', 8],
  ['ระดับแรงดัน\n(HV, LV )', 6.5], ['เหตุการณ์ไฟฟ้าขัดข้อง\n(T/L, T/R, D/F, LT, MT)', 8], ['รหัสอุปกรณ์', 15], ['สถานที่ไฟดับ', 21],
  ['สาเหตุ', 19], ['การแก้ไข', 17], ['อุปกรณ์ที่ใช้', 14], ['การแจ้ง', 7.5], ['เวลารับแจ้ง', 10], ['ผู้รับแจ้ง', 10],
  ['เวลาออกปฏิบัติงาน|ออก', 10], ['เวลาออกปฏิบัติงาน|เข้า', 10], ['เวลาออกปฏิบัติงาน|รวม', 8], ['ผู้ปฏิบัติงาน|พชง.', 11],
  ['ผู้ปฏิบัติงาน|ชชง.1', 11], ['ผู้ปฏิบัติงาน|ชชง.2', 11], ['หัวหน้าเวร', 11], ['เลขที่ใบสั่ง|OMS', 12], ['เลขที่ใบสั่ง|SAP', 12],
  ['สภาพอากาศ', 8], ['หมายเลขรถ', 8], ['รูปภาพ', 13],
];
function drRowValues_(e, i) {
  const hm = d => d instanceof Date ? fmtHM_(d) : '';
  return [i + 1, e.t_off ? thNum_(e.t_off) : thNum_(e.date), hm(e.t_off), hm(e.t_on), durHM_(e.off_min), e.voltage, e.type, e.device + (e.device2 ? ' / ' + e.device2 : ''),
    placeText_(e), e.cause || e.cause_cat, e.action || e.action_cat, e.materials, e.notify, hm(e.t_notify), e.receiver,
    hm(e.t_depart), hm(e.t_back), durHM_(e.work_min), e.lead, e.crew1, e.crew2, e.head, e.oms, e.sap, e.weather, e.vehicle,
    '']; // คอลัมน์รูปภาพ: แสดงเฉพาะรูป (ใส่ภายหลัง)
}

// ---------------------------------------------------------------- HTML preview (และใช้เป็น fallback PDF)
function drSignBlock_(label, name, pos) {
  return '<td style="text-align:center;width:50%;padding-top:24px">' + (name ? '' : '<div>ลงชื่อ ..................................................</div>') +
    '<div>(' + (name ? h_(name) : '..................................................') + ')</div><div>' + h_(pos || '') + '</div><div style="color:#555">' + label + '</div></td>';
}
function drCoverHtml_(d, meta) {
  const now = meta.date || new Date();
  const body = drBody_(d).map(t => thaiDigits_(h_(t)));
