    '<tr><td>เลขที่</td><td>วันที่ ' + thaiDigits_(thLongDate_(now)) + '</td></tr></table>' +
    '<p>เรื่อง ขอรายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวันที่ ' + thaiDigits_(thLongDate_(d.p.date)) + (meta.version > 1 ? ' (ฉบับแก้ไขครั้งที่ ' + thaiDigits_(meta.version) + ')' : '') + '</p>' +
    '<p>เรียน ' + h_(setting_('daily_report_salute', 'ผจก.กฟส.กพส.')) + '</p>' +
    body.map(t => '<p style="text-indent:2.5cm;margin:10px 0 6px;text-align:justify">' + t + '</p>').join('') +
