    '<table class="signs"><tr>' + drSignBlock_('ผู้จัดทำ', meta.prepared_by, meta.prepared_pos) + drSignBlock_('ผู้ตรวจสอบ', meta.approved_by, meta.approved_pos) + '</tr></table>' +
    '<div class="foot">' + footer.join('<br>') + '</div></div>';
}
function drTableHtml_(d, meta) {
  const head1 = [], head2 = [];
  let i = 0;
  while (i < DR_COLS.length) {
    const [lab] = DR_COLS[i];
    if (lab.indexOf('|') > 0) {
      const g = lab.split('|')[0];
      let n = 0;
      while (i + n < DR_COLS.length && DR_COLS[i + n][0].split('|')[0] === g && DR_COLS[i + n][0].indexOf('|') > 0) { head2.push('<th>' + h_(DR_COLS[i + n][0].split('|')[1]) + '</th>'); n++; }
      head1.push('<th colspan="' + n + '">' + h_(g) + '</th>');
      i += n;
    } else { head1.push('<th rowspan="2">' + h_(lab).replace(/\n/g, '<br>') + '</th>'); i++; }
  }
  const img = e => { const m = String(e.photo || '').match(/[-\w]{25,}/); return m ? '<img src="https://drive.google.com/thumbnail?id=' + m[0] + '&sz=w240" style="width:100%;max-height:60px;object-fit:cover" referrerpolicy="no-referrer" onerror="this.remove()">' : ''; };
  const rows = d.evs.map((e, k) => '<tr>' + drRowValues_(e, k).map((v, ci) => '<td>' + (ci === DR_COLS.length - 1 ? img(e) : h_(v)) + '</td>').join('') + '</tr>').join('') ||
    '<tr><td colspan="' + DR_COLS.length + '" style="text-align:center">ไม่มีเหตุการณ์ไฟฟ้าขัดข้อง</td></tr>';
  let changes = '';
  if (meta.changes && meta.changes.length) {
    changes = '<h3>รายการแก้ไขหลังปิดรายงาน (ฉบับที่ ' + meta.version + ')</h3><table class="grid"><tr><th>เวลา</th><th>รายการ</th><th>ประเภท</th><th>รายละเอียด</th><th>เหตุผล</th><th>ผู้ขอ</th><th>ผู้อนุมัติ</th></tr>' +
      meta.changes.map(c => '<tr><td>' + h_(c.at) + '</td><td>' + h_(c.event_id) + '</td><td>' + h_(c.kind) + '</td><td style="white-space:pre-wrap">' + h_(c.diff) + '</td><td>' + h_(c.reason) + '</td><td>' + h_(c.by) + '</td><td>' + h_(c.approved_by) + '</td></tr>').join('') + '</table>';
  }
  return '<div class="page land"><div class="t1">' + h_(setting_('org_name', 'กฟส.กำแพงแสน')) + '</div><div class="t2">บันทึกการปฏิบัติงานของพนักงานช่างอยู่เวรแก้ไขกระแสไฟฟ้าขัดข้อง ประจำวันที่ ' +
    h_(thDate_(d.p.from)) + ' (' + hmDot_(d.p.from) + ' น.) ถึง ' + h_(thDate_(d.p.to)) + ' (' + hmDot_(d.p.to) + ' น.)</div>' +
    '<table class="grid lb"><colgroup>' + DR_COLS.map(c => '<col style="width:' + (c[1] / DR_COLS.reduce((a, x) => a + x[1], 0) * 100).toFixed(2) + '%">').join('') + '</colgroup><thead><tr>' + head1.join('') + '</tr><tr>' + head2.join('') + '</tr></thead><tbody>' + rows + '</tbody></table>' + changes + '</div>';
}
function drHtml_(d, meta) {
  // หน้าจอ: แสดงเหมือนกระดาษ · พิมพ์: ใบประหน้า A4 แนวตั้งเต็มหน้า (16pt ระยะขอบตามหนังสือราชการ) + ตารางแนบ A4 แนวนอน หัวตารางซ้ำทุกหน้า
