// ---------------------------------------------------------------- list / preview / due
function drSer_(r, dateStr) {
  const m = drMeta_(r);
  return {
    date: dateStr, id: r ? r.id : '', status: r ? r.status : 'ร่าง', version: r ? Number(r.version) || 1 : 0,
    prepared_by: r ? r.prepared_by : '', submitted_at: r ? fmtDT_(r.submitted_at) : '', approved_by: r ? r.approved_by : '', approved_at: r ? fmtDT_(r.approved_at) : '',
    hash: r ? String(r.hash || '') : '', files: r && r.pdf_id ? { pdf: r.pdf_id, pdf2: r.pdf2_id, xlsx: r.xlsx_id, sheet: r.sheet_id } : null,
    pending: m.pending, versions: m.versions.map(v => ({ version: v.version, approved_by: v.approved_by, approved_at: v.approved_at, hash: v.hash, files: v.files })),
    note: r ? String(r.summary || '') : '',
  };
}

function dailyReportDue_() {
  const now = new Date();
  const d = addDays_(drDateOf_(now), -1);
  const r = drRow_(d);
  const late = hm_(setting_('daily_report_late', '09:30'));
  const cur = drPeriod_(fmtDate_(d)).to;
  const deadline = new Date(cur.getFullYear(), cur.getMonth(), cur.getDate(), Math.floor(late / 60), late % 60);
  const status = r ? r.status : 'ร่าง';
  return { date: fmtDate_(d), status, deadline: fmtDT_(deadline), late: now > deadline && ['ร่าง', DR_STATUS.RETURNED, DR_STATUS.SUBMITTED].indexOf(status) >= 0,
    needApproval: status === DR_STATUS.SUBMITTED, needRevision: status === DR_STATUS.NEED_REV,
    pendingRequests: table_(SH.EDITREQ).rows.filter(q => q.status === 'รออนุมัติ').length };
}

function dailyReportLateCheck_() {
  const due = dailyReportDue_();
  if (!due.late) return;
  const props = PropertiesService.getScriptProperties();
  const key = 'dr_late_' + due.date;
  if (props.getProperty(key)) return;
  sendLineTo_(setting_('line_to'), '⏰ รายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวันที่ ' + thNum_(parseDT_(due.date)) + ' ' +
    (due.status === DR_STATUS.SUBMITTED ? 'ส่งแล้ว รอหัวหน้า/ผู้ช่วยหัวหน้าอนุมัติ' : 'ยังไม่ได้ส่ง (สถานะ: ' + due.status + ')') + '\nกำหนด ' + setting_('daily_report_late', '09:30') + ' น.');
  props.setProperty(key, '1');
}

function apiDailyList(token, f) {
  auth_(token, 'view');
  f = f || {};
  const last = addDays_(drDateOf_(new Date()), 0);
  const n = Math.min(+f.days || 14, 62);
  const out = [];
  for (let i = 0; i < n; i++) {
    const d = addDays_(last, -i);
    const r = drRow_(d);
    const p = drPeriod_(fmtDate_(d));
    const ser = drSer_(r, fmtDate_(d));
    ser.inProgress = p.to > new Date();
    ser.count = inRange_(events_(), p.from, p.to).length;
    ser.requests = table_(SH.EDITREQ).rows.filter(q => q.report_id === drId_(d) && q.status === 'รออนุมัติ').length;
    out.push(ser);
  }
  return { rows: out, due: dailyReportDue_() };
}

function apiDailyPreview(token, dateStr) {
  auth_(token, 'view');
  const d = drData_(dateStr);
  const r = drRow_(d.p.date);
  const m = drMeta_(r);
  const s = drSer_(r, fmtDate_(d.p.date));
  const meta = { prepared_by: r ? r.prepared_by : '', prepared_pos: r ? r.prepared_pos : '', approved_by: r && r.status !== DR_STATUS.SUBMITTED ? r.approved_by : '', approved_pos: r ? r.approved_pos : '',
    version: r ? Number(r.version) || 1 : 1, changes: m.pending, date: r && r.approved_at instanceof Date ? r.approved_at : new Date() };
  return Object.assign(s, { html: drHtml_(d, meta), count: d.evs.length, inProgress: d.p.to > new Date(), period: { from: fmtDT_(d.p.from), to: fmtDT_(d.p.to) }, rosters: d.rosters,
    requests: apiEditRequests(token, { report: drId_(d.p.date) }) });
}

function posLine_(name) { const p = positionOf_(name); return (p ? p + ' ' : '') + 'ผปบ.' + setting_('org_name', 'กฟส.กำแพงแสน'); }

function apiDailySubmit(token, dateStr, note) {
  const s = auth_(token, 'report.submit');
  const p = drPeriod_(dateStr);
  if (p.to > new Date()) return { ok: false, error: 'ยังไม่ครบรอบ (ถึง ' + thNum_(p.to) + ' ' + hmDot_(p.to) + ' น.)' };
  return withLock_(() => {
    const t = table_(SH.DAILY, true);
    const r = t.rows.find(x => x.id === drId_(p.date));
    if (r && [DR_STATUS.APPROVED, DR_STATUS.NEED_REV].indexOf(r.status) >= 0) return { ok: false, error: 'รายงานนี้อนุมัติแล้ว' };
    const ids = inRange_(events_(), p.from, p.to, true).map(e => e.id).join(', ');
    const rec = { status: DR_STATUS.SUBMITTED, prepared_by: s.display, prepared_pos: posLine_(s.display), submitted_at: new Date(), event_ids: ids, summary: note || '' };
    if (r) updateRow_(SH.DAILY, r._row, rec);
    else appendRows_(SH.DAILY, [Object.assign({ id: drId_(p.date), date: p.date, period_from: p.from, period_to: p.to, version: 1, changes: '{}' }, rec)]);
    audit_(s.display, 'REPORT_SUBMIT', 'DailyReports', drId_(p.date), ids, note || '');
    sendLineTo_(setting_('line_to'), '📄 ส่งรายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวันที่ ' + thNum_(p.date) + ' แล้ว โดย ' + s.display + '\nรอหัวหน้า/ผู้ช่วยหัวหน้าตรวจสอบและอนุมัติ');
    return { ok: true };
  });
}

function apiDailyReturn(token, dateStr, note) {
  const s = auth_(token, 'report.approve');
  if (!String(note || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลที่ตีกลับ' };
  return withLock_(() => {
    const r = table_(SH.DAILY, true).rows.find(x => x.id === drId_(drPeriod_(dateStr).date));
    if (!r || r.status !== DR_STATUS.SUBMITTED) return { ok: false, error: 'ตีกลับได้เฉพาะรายงานที่ส่งแล้วและยังไม่อนุมัติ' };
    updateRow_(SH.DAILY, r._row, { status: DR_STATUS.RETURNED, summary: 'ตีกลับ: ' + note });
    audit_(s.display, 'REPORT_RETURN', 'DailyReports', r.id, '', note);
    return { ok: true };
  });
}

/** อนุมัติ/ปิดรายงาน หรือออกฉบับแก้ไข → สร้างไฟล์ แล้วล็อก */
function apiDailyApprove(token, dateStr) {
  const s = auth_(token, 'report.approve');
  return withLock_(() => {
    const p = drPeriod_(dateStr);
    const r = table_(SH.DAILY, true).rows.find(x => x.id === drId_(p.date));
    if (!r || [DR_STATUS.SUBMITTED, DR_STATUS.NEED_REV].indexOf(r.status) < 0) return { ok: false, error: 'อนุมัติได้เมื่อรายงานถูกส่งแล้ว หรืออยู่ในสถานะต้องออกฉบับแก้ไข' };
    const pendingReq = table_(SH.EDITREQ).rows.filter(q => q.report_id === r.id && q.status === 'รออนุมัติ').length;
    if (pendingReq) return { ok: false, error: 'ยังมีคำขอแก้ไขรออนุมัติ ' + pendingReq + ' รายการ กรุณาพิจารณาก่อน' };
    const m = drMeta_(r);
    const isRev = r.status === DR_STATUS.NEED_REV;
    const version = isRev ? (Number(r.version) || 1) + 1 : (Number(r.version) || 1);
    const now = new Date();
    const meta = { prepared_by: r.prepared_by, prepared_pos: r.prepared_pos, approved_by: s.display, approved_pos: posLine_(s.display), version, changes: isRev ? m.pending : [], date: now };
    const d = drData_(dateStr);
    const files = drMakeFiles_(d, meta);
    if (isRev) m.versions.push({ version: Number(r.version) || 1, approved_by: r.approved_by, approved_at: fmtDT_(r.approved_at), hash: r.hash, files: { pdf: r.pdf_id, pdf2: r.pdf2_id, xlsx: r.xlsx_id, sheet: r.sheet_id } });
    const appliedChanges = isRev ? m.pending : [];
    m.pending = [];
    if (isRev) { m.lastChanges = appliedChanges; }
    updateRow_(SH.DAILY, r._row, {
      status: DR_STATUS.APPROVED, version, approved_by: s.display, approved_pos: meta.approved_pos, approved_at: now,
      pdf_id: files.pdf, pdf2_id: files.pdf2, xlsx_id: files.xlsx, sheet_id: files.sheet, hash: files.hash,
      event_ids: d.evs.map(e => e.id).join(', '), changes: JSON.stringify(m),
    });
    audit_(s.display, isRev ? 'REPORT_REVISE' : 'REPORT_APPROVE', 'DailyReports', r.id, 'ฉบับที่ ' + version + ' · SHA-256 ' + files.hash, '');
    return { ok: true, version, hash: files.hash, warning: files.warning || '' };
  });
}

// ---------------------------------------------------------------- files (Google Sheet → PDF/XLSX)
function drFolder_() { return getFolder_('daily_report_folder_id', 'OMS-กำแพงแสน-รายงานประจำวัน'); }

function drMakeFiles_(d, meta) {
  const name = 'รายงานไฟฟ้าขัดข้องประจำวันที่_' + Utilities.formatDate(d.p.date, APP.tz, 'yyyy-MM-dd') + '_ฉบับที่' + meta.version;
  const folder = drFolder_();
  let warning = '';
  try {
    const ss = drBuildSpreadsheet_(d, meta, name);
    SpreadsheetApp.flush();
    const id = ss.getId();
    DriveApp.getFileById(id).moveTo(folder);
    const cover = drExport_(id, ss.getSheets()[0].getSheetId(), 'pdf', true).setName(name + '_ใบประหน้า.pdf');
    const table = drExport_(id, ss.getSheets()[1].getSheetId(), 'pdf', false).setName(name + '_ตารางแนบ.pdf');
    const xlsx = drExport_(id, null, 'xlsx').setName(name + '.xlsx');
    const f1 = folder.createFile(cover), f2 = folder.createFile(table), f3 = folder.createFile(xlsx);
    const hash = sha256Hex_([].concat(cover.getBytes(), table.getBytes(), xlsx.getBytes()));
    [f1, f2, f3].forEach(f => f.setDescription('รายงานที่อนุมัติแล้ว SHA-256 ' + hash + ' — ห้ามแก้ไข'));
    return { pdf: f1.getId(), pdf2: f2.getId(), xlsx: f3.getId(), sheet: id, hash };
  } catch (e) {
    // สำรอง: PDF จาก HTML ไฟล์เดียว
    console.error('drMakeFiles', e);
    warning = 'สร้างไฟล์จาก Google Sheet ไม่สำเร็จ ใช้ PDF แบบสำรองแทน (' + e.message + ')';
    const blob = HtmlService.createHtmlOutput(drHtml_(d, meta)).getBlob().getAs(MimeType.PDF).setName(name + '.pdf');
    const f = folder.createFile(blob);
    const hash = sha256Hex_(blob.getBytes());
    f.setDescription('รายงานที่อนุมัติแล้ว SHA-256 ' + hash);
    return { pdf: f.getId(), pdf2: '', xlsx: '', sheet: '', hash, warning };
  }
}

function sha256Hex_(bytes) {
  return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, bytes).map(b => ('0' + (b & 0xff).toString(16)).slice(-2)).join('');
}

function drExport_(ssId, gid, format, portrait) {
  let url = 'https://docs.google.com/spreadsheets/d/' + ssId + '/export?format=' + format;
  if (format === 'pdf') {
    url += '&gid=' + gid + '&size=A4&portrait=' + (portrait ? 'true' : 'false') + '&fitw=true&gridlines=false&printtitle=false&sheetnames=false' +
      '&pagenum=' + (portrait ? 'UNDEFINED' : 'CENTER') + '&fzr=true' + (portrait ? '&top_margin=0.79&bottom_margin=0.59&left_margin=1.18&right_margin=0.79' : '&top_margin=0.3&bottom_margin=0.35&left_margin=0.28&right_margin=0.28');
  }
  const res = UrlFetchApp.fetch(url, { headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true });
  if (res.getResponseCode() !== 200) throw new Error('export ' + format + ' HTTP ' + res.getResponseCode());
  return res.getBlob();
}

function drBuildSpreadsheet_(d, meta, name) {
  const ss = SpreadsheetApp.create(name);
  const cv = ss.getSheets()[0].setName('ใบประหน้า');
  const tb = ss.insertSheet('ตารางแนบ');
  const font = 'Sarabun';
  // ---- ใบประหน้า (A4 แนวตั้ง 8 คอลัมน์ · 16pt · ระยะขอบตามหนังสือราชการ · ท้ายกระดาษชิดล่าง)
  //  พื้นที่พิมพ์ 6.3 × 10.31 นิ้ว ↔ แผ่นงานกว้าง 704 px → สูงได้ ~1150 px
  const PAGE_H = 1150, LH = 31;
  cv.setHiddenGridlines(true);
  cv.getRange('A1:H40').setFontFamily(font).setFontSize(16).setVerticalAlignment('top');
  [1, 2, 3, 4, 5, 6, 7, 8].forEach(c => cv.setColumnWidth(c, 88));
  try { cv.insertImage(letterheadBlob_(), 1, 1).setWidth(118).setHeight(102); } catch (e) { console.warn('logo', e); }
  let used = 0;
  const hgt = (r, h) => { cv.setRowHeight(r, h); used += h; };
  for (let r = 1; r <= 5; r++) hgt(r, 22);
  const line = (r, text, opt) => {
    opt = opt || {};
    const rg = cv.getRange(r, 1, 1, 8).merge().setValue(text).setWrap(true);
    if (opt.align) rg.setHorizontalAlignment(opt.align);
    hgt(r, LH * Math.max(1, opt.lines || Math.ceil(String(text).length / (opt.cpl || 62))));
    return rg;
  };
  cv.getRange('A6').setValue('จาก ' + setting_('daily_report_from', 'ผปบ.กฟส.กำแพงแสน')); cv.getRange('E6').setValue('ถึง ' + setting_('daily_report_to', 'ผจก.กฟส.กำแพงแสน')); hgt(6, LH);
  cv.getRange('A7').setValue('เลขที่'); cv.getRange('E7').setValue('วันที่ ' + thaiDigits_(thLongDate_(meta.date))); hgt(7, LH);
  line(8, 'เรื่อง ขอรายงานเหตุการณ์ไฟฟ้าขัดข้องประจำวันที่ ' + thaiDigits_(thLongDate_(d.p.date)) + (meta.version > 1 ? ' (ฉบับแก้ไขครั้งที่ ' + thaiDigits_(meta.version) + ')' : ''));
  line(9, 'เรียน ' + setting_('daily_report_salute', 'ผจก.กฟส.กพส.'));
  hgt(10, 8);
  let row = 11;
  drBody_(d).forEach(t => { line(row, '                    ' + thaiDigits_(t)).setHorizontalAlignment('left'); row++; });
  hgt(row, 8); row++;
  line(row, '                    จึงเรียนมาเพื่อโปรดทราบ'); row++;
  hgt(row, 40); hgt(row + 1, 40); row += 2;
  const sign = (col, label, nm, pos) => {
    cv.getRange(row, col, 1, 4).merge().setValue(nm ? '' : 'ลงชื่อ ..................................................').setHorizontalAlignment('center');
    cv.getRange(row + 1, col, 1, 4).merge().setValue('(' + (nm || '..................................................') + ')').setHorizontalAlignment('center');
    cv.getRange(row + 2, col, 1, 4).merge().setValue(pos || '').setHorizontalAlignment('center').setWrap(true);
    cv.getRange(row + 3, col, 1, 4).merge().setValue(label).setHorizontalAlignment('center').setFontColor('#555555');
  };
  sign(1, 'ผู้จัดทำ', meta.prepared_by, meta.prepared_pos);
  sign(5, 'ผู้ตรวจสอบ', meta.approved_by, meta.approved_pos);
  const posLines = Math.max(1, ...[meta.prepared_pos, meta.approved_pos].map(x => Math.ceil(String(x || '').length / 30)));
  hgt(row, LH); hgt(row + 1, LH); hgt(row + 2, LH * posLines); hgt(row + 3, LH);
  row += 4;
  const foot = String(setting_('daily_report_footer', APP.dept)).split('|');
  const footH = 26 * foot.length;
  hgt(row, Math.max(10, PAGE_H - used - footH)); row++; // ดันท้ายกระดาษลงล่างสุด
  foot.forEach((t, i) => { cv.getRange(row + i, 1, 1, 8).merge().setValue(thaiDigits_(t)).setFontSize(14); cv.setRowHeight(row + i, 26); });
  const lastCv = row + foot.length - 1;
  if (cv.getMaxRows() > lastCv) cv.deleteRows(lastCv + 1, cv.getMaxRows() - lastCv);
  if (cv.getMaxColumns() > 8) cv.deleteColumns(9, cv.getMaxColumns() - 8);
  // ---- ตารางแนบ (คอลัมน์ตาม Log book)
  const n = DR_COLS.length;
  tb.setHiddenGridlines(true);
  tb.getRange(1, 1, 1, n).merge().setValue(setting_('org_name', 'กฟส.กำแพงแสน')).setHorizontalAlignment('center').setFontWeight('bold');
  tb.getRange(2, 1, 1, n).merge().setValue('บันทึกการปฏิบัติงานของพนักงานช่างอยู่เวรแก้ไขกระแสไฟฟ้าขัดข้อง ประจำวันที่ ' + thDate_(d.p.from) + ' (' + hmDot_(d.p.from) + ' น.) ถึง ' + thDate_(d.p.to) + ' (' + hmDot_(d.p.to) + ' น.)')
    .setHorizontalAlignment('center').setFontWeight('bold');
  let c = 0;
  while (c < n) {
    const lab = DR_COLS[c][0];
    if (lab.indexOf('|') > 0) {
      const g = lab.split('|')[0];
      let k = 0;
      while (c + k < n && DR_COLS[c + k][0].indexOf('|') > 0 && DR_COLS[c + k][0].split('|')[0] === g) { tb.getRange(4, c + k + 1).setValue(DR_COLS[c + k][0].split('|')[1]); k++; }
      tb.getRange(3, c + 1, 1, k).merge().setValue(g);
      c += k;
    } else { tb.getRange(3, c + 1, 2, 1).merge().setValue(lab); c++; }
  }
  DR_COLS.forEach((col, i) => tb.setColumnWidth(i + 1, Math.round(col[1] * 4.2)));
  const hdr = tb.getRange(3, 1, 2, n);
  hdr.setFontWeight('bold').setBackground('#e8e8e8').setHorizontalAlignment('center').setVerticalAlignment('middle').setWrap(true);
  const data = d.evs.map((e, i) => drRowValues_(e, i).map(v => v == null ? '' : v));
  if (data.length) tb.getRange(5, 1, data.length, n).setValues(data).setWrap(true).setVerticalAlignment('top').setNumberFormat('@');
  else tb.getRange(5, 1, 1, n).merge().setValue('ไม่มีเหตุการณ์ไฟฟ้าขัดข้อง').setHorizontalAlignment('center');
  const lastRow = 4 + Math.max(1, data.length);
  tb.getRange(3, 1, lastRow - 2, n).setBorder(true, true, true, true, true, true, '#444444', SpreadsheetApp.BorderStyle.SOLID);
  tb.getRange(1, 1, lastRow, n).setFontFamily(font).setFontSize(10);
  tb.getRange(1, 1, 2, n).setFontSize(12);
  tb.setFrozenRows(4);
  // รูปภาพ: รูปแรกของแต่ละเหตุการณ์
  d.evs.forEach((e, i) => {
    const pid = String(e.photo || '').split(',').map(x => x.trim()).filter(Boolean)[0];
    if (!pid) return;
    try {
      const m = pid.match(/[-\w]{25,}/);
      const f = DriveApp.getFileById(m[0]);
      const blob = f.getThumbnail() || f.getBlob();
      tb.setRowHeight(5 + i, 70);
      tb.insertImage(blob, n, 5 + i).setWidth(90).setHeight(64);
    } catch (err) { console.warn('photo', pid, err); }
  });
  // รายการแก้ไขหลังปิดรายงาน
  if (meta.changes && meta.changes.length) {
    let r0 = lastRow + 2;
    tb.getRange(r0, 1, 1, 8).merge().setValue('รายการแก้ไขหลังปิดรายงาน (ฉบับที่ ' + meta.version + ')').setFontWeight('bold');
    const ch = [['เวลา', 'รายการ', 'ประเภท', 'รายละเอียด', 'เหตุผล', 'ผู้ขอ', 'ผู้อนุมัติ']].concat(meta.changes.map(x => [x.at, x.event_id, x.kind, x.diff, x.reason, x.by, x.approved_by]));
    tb.getRange(r0 + 1, 1, ch.length, 7).setValues(ch).setWrap(true).setFontFamily(font).setFontSize(9)
      .setBorder(true, true, true, true, true, true, '#444444', SpreadsheetApp.BorderStyle.SOLID);
  }
  return ss;
}

/** ไฟล์รายงานที่อนุมัติแล้ว (base64) สำหรับดาวน์โหลด/รวมเล่มในเบราว์เซอร์ */
function apiDailyFiles(token, dateStr, version) {
  auth_(token, 'view');
  const r = drRow_(drPeriod_(dateStr).date);
  if (!r || !r.pdf_id) return { ok: false, error: 'ยังไม่มีไฟล์ (ต้องอนุมัติก่อน)' };
  let ids = { pdf: r.pdf_id, pdf2: r.pdf2_id, xlsx: r.xlsx_id };
  if (version && Number(version) !== Number(r.version)) {
    const v = drMeta_(r).versions.find(x => Number(x.version) === Number(version));
    if (!v) return { ok: false, error: 'ไม่พบฉบับที่ ' + version };
    ids = v.files;
  }
  const get = id => {
    if (!id) return null;
    const f = DriveApp.getFileById(id);
    const b = f.getBlob();
    return { name: f.getName(), url: f.getUrl(), dataUrl: 'data:' + b.getContentType() + ';base64,' + Utilities.base64Encode(b.getBytes()) };
  };
  return { ok: true, version: version || r.version, hash: r.hash, cover: get(ids.pdf), table: get(ids.pdf2), xlsx: get(ids.xlsx) };
}

/**
 * Jobs.gs (v1.4) : งาน PM แบบเต็ม (ข้อ 10) และงานคำร้อง/บริการ (ข้อ 20)
 *  ใช้กลไกเดียวกัน: ผู้รับผิดชอบ · กำหนดเสร็จ · โอน/ส่งต่อ · ตีกลับ · ประวัติ (timeline) · รูปปิดงาน
 */

// ---------------------------------------------------------------- shared helpers
function histOf_(r) { try { return JSON.parse(r.history || '[]') || []; } catch (e) { return []; } }
function histAdd_(r, user, act, note) {
  const h = histOf_(r);
  h.push({ at: fmtDT_(new Date()), by: user, act, note: String(note || '').slice(0, 500) });
  return JSON.stringify(h).slice(0, 45000);
}
function dueFor_(priority, from) {
  const days = priority === 'ด่วน' ? settingNum_('pm_due_urgent_days', 7) : settingNum_('pm_due_normal_days', 30);
  return addDays_(dayStart_(from || new Date()), days);
}
function asDate_(v) { return v instanceof Date ? v : (v ? parseDT_(v) : null); }
function overdue_(due, open) { const d = asDate_(due); return !!(open && d && new Date() > addDays_(dayStart_(d), 1)); }
function pmOverdue_(p) { return overdue_(p.due, pmOpen_(p) && !wbsWaiting_(p)); }
function photoList_(v) { return String(v || '').split(',').map(x => x.trim()).filter(Boolean); }
function isManager_(s) { return ROLES[s.role].indexOf('pm.update') >= 0; }
/** v1.11 ข้อ 95: พนักงานทุกคน (ยกเว้นผู้บริหาร) ทำงานเองได้ */
function isStaff_(s) { return permsOf_(s).indexOf('work.do') >= 0; }

// ---------------------------------------------------------------- PM (ข้อ 10)
function serPm_(p, me) {
  return {
    id: p.id, created_at: fmtDT_(p.created_at), created_by: p.created_by, source: p.source, event_ids: String(p.event_ids || ''),
    alert_id: p.alert_id, device: p.device, feeder: p.feeder, tambon: p.tambon, location: p.location, lat: p.lat === '' ? '' : +p.lat, lon: p.lon === '' ? '' : +p.lon,
    category: p.category, cat_note: String(p.cat_note || ''), sap: String(p.sap || ''), priority: p.priority, detail: p.detail, status: p.status, result: p.result, done_at: fmtDT_(p.done_at),
    updated_by: p.updated_by, updated_at: fmtDT_(p.updated_at), recheck: p.recheck, sent_at: fmtDT_(p.sent_at),
    age: p.created_at instanceof Date ? Math.floor((Date.now() - p.created_at) / 86400000) : '',
    owner: String(p.owner || ''), due: p.due instanceof Date ? fmtDate_(p.due) : String(p.due || ''), overdue: pmOverdue_(p),
    photos: photoList_(p.photos), photos_before: photoList_(p.photos_before), needs_outage: String(p.needs_outage).toUpperCase() === 'TRUE', planned_id: String(p.planned_id || ''),
    mine: !!me && String(p.owner) === me, wbs_id: String(p.wbs_id || ''), wbs_wait: wbsWaiting_(p),
    purpose: String(p.purpose || ''), meters: String(p.meters || ''), handover_at: p.handover_at instanceof Date ? fmtDate_(p.handover_at) : String(p.handover_at || ''),
  };
}

