/**
 * การกระทำกับงาน PM: assign · start · close · transfer · return · cancel · reopen · edit · outage
 *  - หัวหน้า/ผู้ช่วยหัวหน้า/วิศวกร (pm.update) ทำได้ทุกอย่าง
 *  - ผู้รับผิดชอบปัจจุบัน: โอน · ตีกลับ · เริ่มงาน · ปิดงาน ของงานตัวเอง
 */
function apiPmUpdate(token, o) {
  const s = auth_(token, 'view');
  requireFeature_('pm');
  o = o || {};
  const act = o.action || (o.status ? 'status' : 'edit');
  return withLock_(() => {
    const p = table_(SH.PM, true).rows.find(x => x.id === o.id);
    if (!p) return { ok: false, error: 'ไม่พบงาน ' + o.id };
    const mgr = isManager_(s), owner = !!p.owner && String(p.owner) === s.display, staff = isStaff_(s);
    const need = (cond, msg) => { if (!cond) throw new Error(msg || 'ไม่มีสิทธิ์ทำรายการนี้'); };
    const now = new Date(), upd = { updated_by: s.display, updated_at: now };
    let note = '';
    if (act === 'assign') {
      need(mgr || staff, 'ไม่มีสิทธิ์มอบหมายงาน');
      if (!String(o.owner || '').trim()) return { ok: false, error: 'กรุณาเลือกผู้รับผิดชอบ' };
      upd.owner = String(o.owner).trim();
      // แก้กำหนดเสร็จหลังสร้างงาน = หัวหน้าเท่านั้น
      upd.due = o.due && (mgr || !p.due) ? parseDT_(o.due) : (p.due instanceof Date ? p.due : dueFor_(p.priority));
      if (['ใหม่', 'ตีกลับ'].indexOf(p.status) >= 0) upd.status = 'รับเรื่อง';
      note = 'มอบหมาย ' + upd.owner + ' · กำหนด ' + thNum_(upd.due);
    } else if (act === 'take') { // รับงานนี้ (ยังไม่มีผู้รับผิดชอบ)
      need(staff || mgr, 'ไม่มีสิทธิ์รับงาน');
      if (String(p.owner || '').trim()) return { ok: false, error: 'งานนี้มีผู้รับผิดชอบแล้ว: ' + p.owner };
      upd.owner = s.display; upd.due = p.due instanceof Date ? p.due : dueFor_(p.priority);
      if (['ใหม่', 'ตีกลับ'].indexOf(p.status) >= 0) upd.status = 'รับเรื่อง';
      note = 'รับงานเอง';
    } else if (act === 'start') {
      need(mgr || owner || staff);
      upd.status = 'กำลังดำเนินการ'; note = 'เริ่มดำเนินการ';
    } else if (act === 'close') {
      need(mgr || owner || staff);
      if (!String(o.result || '').trim()) return { ok: false, error: 'กรุณาระบุผลการดำเนินงานก่อนปิดงาน' };
      const photos = photoList_(p.photos).concat(o.photos || []).filter((x, i, a) => a.indexOf(x) === i);
      if (!photos.length) return { ok: false, error: 'กรุณาแนบรูปหลังทำงานอย่างน้อย 1 รูปก่อนปิดงาน' };
      upd.status = 'เสร็จ'; upd.result = String(o.result).trim(); upd.done_at = now; upd.recheck = ''; upd.photos = photos.join(',');
      if (o.sap !== undefined) upd.sap = String(o.sap || '').trim();
      if (o.handover || /มิเตอร์/.test(String(p.purpose || ''))) { upd.handover_at = now; upd.result = 'ส่งต่อผู้รับจ้างดูแลแล้ว · ' + upd.result; }
      if (o.materials) {
        const mats = materialRows_(o.materials, p.id, now, s.display);
        replaceJobMaterials_(p.id, mats.rows.map(m => Object.assign(m, { work_type: 'PM', ref_id: p.id, event_id: '' })));
      }
      note = (owner || !p.owner ? '' : 'ปิดโดย ' + s.display + ' แทน ' + p.owner + ' · ') + 'ปิดงาน: ' + upd.result;
    } else if (act === 'transfer') {
      need(mgr || owner || staff, 'ส่งต่อได้โดยผู้รับผิดชอบปัจจุบัน หรือหัวหน้า/ผู้ช่วยหัวหน้า/วิศวกร');
      if (!String(o.to || '').trim()) return { ok: false, error: 'กรุณาระบุผู้รับงานต่อ' };
      if (!String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลการส่งต่อ' };
      upd.owner = String(o.to).trim(); note = 'ส่งต่อจาก ' + (p.owner || '-') + ' → ' + upd.owner + ' · เหตุผล: ' + o.reason;
      if (p.status === 'ใหม่') upd.status = 'รับเรื่อง';
    } else if (act === 'return') {
      need(mgr || owner);
      if (!String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลที่ตีกลับ' };
      upd.status = 'ตีกลับ'; upd.owner = String(p.created_by || ''); note = 'ตีกลับ: ' + o.reason;
    } else if (act === 'cancel') {
      need(mgr);
      upd.status = 'ยกเลิก'; note = 'ยกเลิก' + (o.reason ? ': ' + o.reason : '');
    } else if (act === 'reopen') {
      need(mgr || String(p.created_by) === s.display);
      upd.status = p.owner ? 'รับเรื่อง' : 'ใหม่'; note = 'เปิดงานอีกครั้ง' + (o.reason ? ': ' + o.reason : '');
      if (o.detail) upd.detail = String(o.detail).slice(0, 1500);
    } else if (act === 'outage') {
      need(mgr || ROLES[s.role].indexOf('planned.write') >= 0);
      if (p.category === HOTLINE_CAT) return { ok: false, error: 'งาน Hotline ทำโดยไม่ดับไฟ — ถ้าต้องดับไฟ ให้เปลี่ยนประเภทงานก่อน' };
      if (!o.date || !o.t_start || !o.t_end) return { ok: false, error: 'กรุณาระบุวันที่และเวลาดับไฟ' };
      const pid = createPlannedFromJob_({ date: o.date, t_start: o.t_start, t_end: o.t_end, device: p.device, feeder: p.feeder, tambon: p.tambon,
        location: p.location, reason: 'งาน PM ' + p.id + ' ' + p.category + (p.detail ? ' — ' + String(p.detail).slice(0, 80) : ''), pm_ids: p.id }, s.display);
      upd.needs_outage = true; upd.planned_id = pid; note = 'สร้างแผนดับไฟ ' + pid + ' วันที่ ' + thNum_(parseDT_(o.date));
    } else if (act === 'status') {
      need(mgr, 'การเปลี่ยนสถานะทำได้โดยหัวหน้า/ผู้ช่วยหัวหน้า/วิศวกร');
      if (PM_STATUS.indexOf(o.status) < 0) return { ok: false, error: 'สถานะไม่ถูกต้อง' };
      if (o.status === 'เสร็จ') return apiPmUpdateClose_(p, o, s);
      upd.status = o.status; note = 'สถานะ: ' + o.status;
      ['priority', 'category', 'detail'].forEach(k => { if (o[k] !== undefined) upd[k] = o[k]; });
      if (o.result !== undefined) upd.result = o.result;
    } else { // edit
      need(mgr);
      ['priority', 'category', 'detail'].forEach(k => { if (o[k] !== undefined) upd[k] = o[k]; });
      if (o.category !== undefined && pmCategories_().indexOf(o.category) < 0) return { ok: false, error: 'ประเภทงานไม่ถูกต้อง' };
      if (o.due) upd.due = parseDT_(o.due);
      if (o.needs_outage !== undefined) upd.needs_outage = !!o.needs_outage;
      note = 'แก้ไขรายละเอียด';
    }
    upd.history = histAdd_(p, s.display, act, note);
    updateRow_(SH.PM, p._row, upd);
    audit_(s.display, 'PM_' + act.toUpperCase(), 'PMQueue', p.id, note, o.reason || '');
    return { ok: true };
  });
}
function apiPmUpdateClose_(p, o, s) {
  // ปิดงานผ่านช่องสถานะ (รูปแบบเดิม) — ใช้กติกาเดียวกับ action=close
  if (!String(o.result || '').trim()) return { ok: false, error: 'กรุณาระบุผลการดำเนินงานก่อนปิดงาน' };
  const photos = photoList_(p.photos).concat(o.photos || []);
  if (!photos.length) return { ok: false, error: 'กรุณาแนบรูปหลังทำงานอย่างน้อย 1 รูปก่อนปิดงาน' };
  const now = new Date();
  updateRow_(SH.PM, p._row, { status: 'เสร็จ', result: String(o.result).trim(), done_at: now, recheck: '', photos: photos.join(','),
    updated_by: s.display, updated_at: now, history: histAdd_(p, s.display, 'close', 'ปิดงาน: ' + o.result) });
  audit_(s.display, 'PM_CLOSE', 'PMQueue', p.id, String(o.result), '');
  return { ok: true };
}

/** แทนที่วัสดุของงาน (PM/คำร้อง) ตาม ref_id */
function replaceJobMaterials_(refId, rows) {
  const t = table_(SH.MATUSE, true);
  const old = t.rows.filter(m => String(m.ref_id) === refId).map(m => m._row).sort((a, b) => b - a);
  old.forEach(r => t.sh.deleteRow(r));
  if (old.length) invalidate_(SH.MATUSE);
  if (rows.length) {
    const ids = nextIds_(SH.MATUSE, 'MU-', rows.length);
    rows.forEach((r, i) => { r.id = ids[i]; });
    appendRows_(SH.MATUSE, rows);
  }
}

function createPlannedFromJob_(o, user) {
  const id = nextIds_(SH.PLANNED, 'PL-', 1)[0];
