  appendRows_(SH.PLANNED, [{ id, date: parseDT_(o.date), t_start: o.t_start, t_end: o.t_end, device: o.device || '', feeder: o.feeder || (reg && reg.feeder) || '',
    tambon: o.tambon || '', location: o.location || '', reason: o.reason || '', customers: reg && reg.customers !== '' ? reg.customers : '', notice: '',
    team: '', status: 'วางแผน', event_id: '', notified_at: '', created_by: user, created_at: new Date(), updated_by: '', updated_at: '', pm_ids: o.pm_ids || '' }]);
