  return id;
}

// ---------------------------------------------------------------- งานคำร้อง/บริการ (ข้อ 20)
const REQ_TYPES = ['ย้ายเสาไฟฟ้า', 'ไฟตก', 'ย้ายแนว', 'ตัดต้นไม้', 'ย้ายสายยึดโยง', 'พาดสายเพิ่ม', 'ตรวจสอบระบบไฟฟ้า', 'อื่นๆ'];
const REQ_CHANNELS = ['โทรแจ้ง', 'หนังสือทางการ', 'คำร้อง', 'แผนก', 'ติดต่อด้วยตนเอง', 'LINE/ออนไลน์'];
const REQ_STATUS = ['ใหม่', 'รับเรื่อง', 'กำลังดำเนินการ', 'ส่งต่อแผนกอื่น', 'ตีกลับ', 'เสร็จ', 'ยกเลิก'];
function reqOpen_(r) { return ['เสร็จ', 'ยกเลิก'].indexOf(r.status) < 0; }
function reqOverdue_(r) { return overdue_(r.due, reqOpen_(r) && r.status !== 'ส่งต่อแผนกอื่น' && !wbsWaiting_(r)); }

function serReq_(r, me) {
  return {
    id: r.id, received_at: r.received_at instanceof Date ? fmtDate_(r.received_at) : String(r.received_at || ''), channel: r.channel, type: r.type,
    type_note: String(r.type_note || ''), requester: r.requester, phone: String(r.phone || ''), address: r.address, tambon: r.tambon, detail: r.detail, doc_no: String(r.doc_no || ''),
    br1_book: String(r.br1_book || ''), br1_no: String(r.br1_no || ''), owner: String(r.owner || ''),
    due: r.due instanceof Date ? fmtDate_(r.due) : String(r.due || ''), status: r.status, result: r.result, done_at: fmtDT_(r.done_at),
    transfer_to: r.transfer_to, photos: photoList_(r.photos), links: String(r.links || ''), lat: r.lat === '' ? '' : +r.lat, lon: r.lon === '' ? '' : +r.lon,
    created_by: r.created_by, created_at: fmtDT_(r.created_at), updated_by: r.updated_by, updated_at: fmtDT_(r.updated_at), legacy: String(r.legacy || ''),
    overdue: reqOverdue_(r), mine: !!me && String(r.owner) === me, wbs_id: String(r.wbs_id || ''), wbs_wait: wbsWaiting_(r),
    age: r.received_at instanceof Date ? Math.floor((Date.now() - r.received_at) / 86400000) : '',
  };
}

function apiReqList(token, f) {
  const s = auth_(token, 'view');
  requireFeature_('requests');
