  const q = String(f.q || '').toLowerCase().replace(/[-\s]/g, '');
  let rows = table_(SH.REQ).rows.filter(r => r.id);
  if (f.status === 'open') rows = rows.filter(reqOpen_);
  else if (f.status) rows = rows.filter(r => r.status === f.status);
  if (f.type) rows = rows.filter(r => r.type === f.type);
  if (f.mine) rows = rows.filter(r => String(r.owner) === s.display);
  if (f.overdue) rows = rows.filter(reqOverdue_);
  if (q) rows = rows.filter(r => [r.id, r.requester, r.phone, r.address, r.tambon, r.detail, r.doc_no, r.br1_book, r.br1_no, r.owner, r.result, r.transfer_to].join(' ').toLowerCase().replace(/[-\s]/g, '').indexOf(q) >= 0);
