function apiReqGet(token, id) {
  const s = auth_(token, 'view');
  const r = table_(SH.REQ).rows.find(x => x.id === id);
  if (!r) return { ok: false, error: 'ไม่พบงาน ' + id };
  const history = histOf_(r);
  // ประวัติเรื่องอื่นของผู้ร้อง/เบอร์เดียวกัน
