    .slice(0, 10).map(x => ({ id: x.id, type: x.type, status: x.status, received_at: x.received_at instanceof Date ? fmtDate_(x.received_at) : '' }));
  return { ok: true, req: serReq_(r, s.display), history, related, canWrite: ROLES[s.role].indexOf('req.write') >= 0 };
}

function apiReqSave(token, o) {
  const s = auth_(token, 'req.write');
  requireFeature_('requests');
  o = o || {};
  const err = [];
  if (REQ_TYPES.indexOf(o.type) < 0) err.push('กรุณาเลือกประเภทงาน');
  if (!String(o.detail || '').trim() && !String(o.requester || '').trim()) err.push('กรุณาระบุผู้ร้องหรือรายละเอียด');
  if (err.length) return { ok: false, errors: err };
  return withLock_(() => {
    const now = new Date();
    const fields = { received_at: o.received_at ? parseDT_(o.received_at) : now, channel: o.channel || '', type: o.type, requester: String(o.requester || '').trim(),
      phone: String(o.phone || '').trim(), address: String(o.address || '').trim(), tambon: o.tambon || '', detail: String(o.detail || '').trim(),
      doc_no: String(o.doc_no || '').trim(), type_note: o.type === 'อื่นๆ' ? String(o.type_note || '').trim() : '' };
    if (o.type === 'อื่นๆ' && !fields.type_note) return { ok: false, errors: ['กรุณาระบุประเภทงาน (อื่นๆ)'] };
    if (o.br1_book !== undefined) { fields.br1_book = String(o.br1_book || '').trim(); fields.br1_no = String(o.br1_no || '').trim(); }
    if (o.lat !== undefined) { fields.lat = o.lat; fields.lon = o.lon; }
    if (o.id) {
      const r = table_(SH.REQ, true).rows.find(x => x.id === o.id);
      if (!r) return { ok: false, errors: ['ไม่พบงาน ' + o.id] };
      const ch = Object.keys(fields).filter(k => cmpVal_(r[k]) !== cmpVal_(fields[k]));
      if (!ch.length) return { ok: true, id: o.id, unchanged: true };
      updateRow_(SH.REQ, r._row, Object.assign(fields, { updated_by: s.display, updated_at: now, history: histAdd_(r, s.display, 'edit', 'แก้ไข: ' + ch.join(', ')) }));
      audit_(s.display, 'REQ_UPDATE', 'Requests', o.id, ch.map(k => k + ': ' + cmpVal_(r[k]) + ' → ' + cmpVal_(fields[k])).join('\n'), '');
      return { ok: true, id: o.id };
    }
    const id = nextIds_(SH.REQ, 'CR-', 1)[0];
    const hist = [{ at: fmtDT_(now), by: s.display, act: 'รับเรื่อง', note: fields.channel }];
    let owner = '', due = dueFor_('ปกติ', now), st = 'ใหม่';
    if (o.owner && isManager_(s)) { owner = String(o.owner).trim(); due = o.due ? parseDT_(o.due) : due; st = 'รับเรื่อง'; hist.push({ at: fmtDT_(now), by: s.display, act: 'assign', note: 'มอบหมาย ' + owner + ' · กำหนด ' + thNum_(due) }); }
    else if (o.due && isManager_(s)) due = parseDT_(o.due);
    if (fields.lat && !fields.tambon) fields.tambon = tambonAt_(+fields.lat, +fields.lon) || '';
    appendRows_(SH.REQ, [Object.assign(fields, { id, status: st, owner, due, result: '', done_at: '', transfer_to: '',
      history: JSON.stringify(hist), photos: '', links: '',
      created_by: s.display, created_at: now, updated_by: '', updated_at: '', legacy: '' })]);
    audit_(s.display, 'REQ_CREATE', 'Requests', id, [fields.type, fields.requester, fields.detail].filter(Boolean).join(' · '), '');
    return { ok: true, id };
  });
}

/** การกระทำกับงานคำร้อง: assign · start · transfer(dept) · return · close · cancel · reopen · link */
function apiReqAction(token, o) {
  const s = auth_(token, 'view');
  requireFeature_('requests');
  o = o || {};
  // v1.11 ข้อ 94/95: งานทั่วไป = ทุกคน · แก้กำหนด/ส่งต่อแผนก/ยกเลิก/เปิดใหม่ = หัวหน้าและสั่งการ (req.write)
  const head = permsOf_(s).indexOf('req.write') >= 0, staff = isStaff_(s);
  const HEAD_ONLY = ['cancel', 'reopen'];
  if (HEAD_ONLY.indexOf(o.action) >= 0 || (o.action === 'transfer' && o.dept)) { if (!head) throw new Error('รายการนี้ทำได้โดยหัวหน้าหรือเจ้าหน้าที่สั่งการ'); }
  else if (!head && !staff) throw new Error('ไม่มีสิทธิ์');
  return withLock_(() => {
    const r = table_(SH.REQ, true).rows.find(x => x.id === o.id);
    if (!r) return { ok: false, error: 'ไม่พบงาน ' + o.id };
    const own = String(r.owner || '') === s.display;
    const now = new Date(), upd = { updated_by: s.display, updated_at: now };
    let note = '';
    switch (o.action) {
      case 'assign':
        if (!String(o.owner || '').trim()) return { ok: false, error: 'กรุณาเลือกผู้รับผิดชอบ' };
        upd.owner = String(o.owner).trim(); upd.due = o.due && (head || !r.due) ? parseDT_(o.due) : (r.due instanceof Date ? r.due : dueFor_('ปกติ'));
        if (['ใหม่', 'ตีกลับ'].indexOf(r.status) >= 0) upd.status = 'รับเรื่อง';
        note = 'มอบหมาย ' + upd.owner + ' · กำหนด ' + thNum_(upd.due); break;
      case 'take':
        if (String(r.owner || '').trim()) return { ok: false, error: 'งานนี้มีผู้รับผิดชอบแล้ว: ' + r.owner };
        upd.owner = s.display; upd.due = r.due instanceof Date ? r.due : dueFor_('ปกติ');
        if (['ใหม่', 'ตีกลับ'].indexOf(r.status) >= 0) upd.status = 'รับเรื่อง';
        note = 'รับงานเอง'; break;
      case 'start': upd.status = 'กำลังดำเนินการ'; note = 'เริ่มดำเนินการ'; break;
      case 'transfer':
        if (!String(o.to || '').trim() || !String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุผู้รับ/แผนก และเหตุผล' };
        if (o.dept) { upd.status = 'ส่งต่อแผนกอื่น'; upd.transfer_to = String(o.to).trim(); }
        else { upd.owner = String(o.to).trim(); if (r.status === 'ใหม่') upd.status = 'รับเรื่อง'; }
        note = (o.dept ? 'ส่งต่อแผนก ' + o.to : 'ส่งต่อจาก ' + (r.owner || '-') + ' → ' + o.to) + ' · เหตุผล: ' + o.reason; break;
      case 'return':
        if (!String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลที่ตีกลับ' };
        upd.status = 'ตีกลับ'; upd.owner = String(r.created_by || ''); note = 'ตีกลับ: ' + o.reason; break;
      case 'close': {
        if (!String(o.result || '').trim()) return { ok: false, error: 'กรุณาระบุผลการดำเนินการ' };
        const photos = photoList_(r.photos).concat(o.photos || []).filter((x, i, a) => a.indexOf(x) === i);
        upd.status = 'เสร็จ'; upd.result = String(o.result).trim(); upd.done_at = now; upd.photos = photos.join(',');
        note = (own || !r.owner ? '' : 'ปิดโดย ' + s.display + ' แทน ' + r.owner + ' · ') + 'ปิดงาน: ' + upd.result; break;
      }
      case 'cancel': upd.status = 'ยกเลิก'; upd.result = o.reason || r.result || 'ยกเลิก'; upd.done_at = now; note = 'ยกเลิก' + (o.reason ? ': ' + o.reason : ''); break;
      case 'reopen': upd.status = r.owner ? 'รับเรื่อง' : 'ใหม่'; upd.done_at = ''; note = 'เปิดงานอีกครั้ง' + (o.reason ? ': ' + o.reason : ''); break;
      case 'link': {
        const links = String(r.links || '').split(/[,\s]+/).filter(Boolean);
        if (o.link && links.indexOf(o.link) < 0) links.push(o.link);
        upd.links = links.join(', '); note = 'เชื่อมโยง ' + o.link; break;
      }
      case 'photos': upd.photos = photoList_(r.photos).concat(o.photos || []).filter((x, i, a) => a.indexOf(x) === i).join(','); note = 'เพิ่มรูป'; break;
      default: return { ok: false, error: 'ไม่รู้จักคำสั่ง ' + o.action };
    }
    upd.history = histAdd_(r, s.display, o.action, note);
    updateRow_(SH.REQ, r._row, upd);
    audit_(s.display, 'REQ_' + String(o.action).toUpperCase(), 'Requests', r.id, note, o.reason || '');
    return { ok: true };
  });
}

/** นำเข้าสมุดคุมรับเรื่องเดิม: นำไฟล์ Excel เข้าเป็นชีตชื่อ "สมุดคุมรับเรื่อง" (ไฟล์ › นำเข้า › แทรกชีตใหม่) แล้วกดเมนูนี้ */
function importRequestsBook(silent, src) {
  // v1.9 ข้อ 72: src = { name, values, apply, by } → นำเข้าจากไฟล์ในหน้าเว็บ (ไม่ต้องสร้างชีต)
  const ss = src ? null : ss_();
  const sh = src ? { getName: () => src.name, getDataRange: () => ({ getValues: () => src.values }) } : ss.getSheets().find(x => /สมุดคุม/.test(x.getName()));
  const ui = msg => { if (!silent) { try { SpreadsheetApp.getUi().alert(msg); } catch (e) { console.log(msg); } } };
  if (!sh) { ui('ไม่พบชีตชื่อ "สมุดคุมรับเรื่อง" — ให้นำไฟล์ Excel เข้ามาก่อน (ไฟล์ › นำเข้า › อัปโหลด › แทรกชีตใหม่)'); return { added: 0 }; }
  ensureSheet_(SH.REQ);
  const values = sh.getDataRange().getValues();
  let hr = values.findIndex(r => r.map(String).indexOf('วันที่แจ้ง') >= 0);
  if (hr < 0) { ui('ไม่พบหัวตาราง (คอลัมน์ "วันที่แจ้ง") ในชีตสมุดคุม'); return { added: 0 }; }
  const H = values[hr].map(x => String(x).replace(/\s+/g, ' ').trim());
  const col = name => H.findIndex(h => h.indexOf(name) === 0);
  const c = { no: col('ที่'), job: col('งาน'), date: col('วันที่แจ้ง'), ch: col('ช่องทาง'), tb: col('ตำบล'), detail: col('รายละเอียดงาน'), recvOk: col('Check รับเรื่อง'),
    recvAt: col('วันที่รับเรื่อง'), recvBy: col('ชื่อผู้รับเรื่อง'), doer: col('ชื่อผู้ดำเนินการสุดท้าย'), result: col('รายละเอียดดำเนินการ'), doneOk: col('Check แล้วเสร็จ'),
    doneAt: col('วันที่แล้วเสร็จ'), closer: col('ชื่อผู้ปิดงาน'), status: col('สถานะ'), fwdOk: col('Check ส่งงานต่อ'), fwdTo: col('แผนกที่รับงานต่อ'), note: col('หมายเหตุ') };
  const have = {};
  table_(SH.REQ, true).rows.forEach(r => { if (r.legacy) have[String(r.legacy)] = true; });
  const tambons = table_(SH.TAMBON).rows.map(t => String(t.name));
  const clean = n => String(n || '').replace(/^(นาย|นางสาว|นาง|น\.ส\.)\s*/, '').trim();
  const v = (r, i) => i >= 0 ? r[i] : '';
  const rows = []; let skipped = 0;
  for (let i = hr + 1; i < values.length; i++) {
    const r = values[i];
    const job = String(v(r, c.job) || '').trim();
    if (!job) continue;
    const legacy = 'สมุดคุม ' + sh.getName() + ' #' + v(r, c.no);
    if (have[legacy]) { skipped++; continue; }
    const detail = String(v(r, c.detail) || '').trim();
    const phone = (detail.match(/0\d{1,2}-?\d{3}-?\d{3,4}/) || [''])[0];
    const firstLine = detail.split('\n')[0].replace(phone, '').trim();
    const result = String(v(r, c.result) || '').trim();
    const done = v(r, c.doneOk) === true || /เสร็จ/.test(String(v(r, c.status)));
    const fwd = v(r, c.fwdOk) === true || !!String(v(r, c.fwdTo) || '').trim();
    let status = done ? (/^ยกเลิก/.test(result) ? 'ยกเลิก' : 'เสร็จ') : fwd ? 'ส่งต่อแผนกอื่น' : v(r, c.recvOk) === true ? 'กำลังดำเนินการ' : 'ใหม่';
    const tbRaw = String(v(r, c.tb) || '');
    const tb = tambons.find(t => tbRaw.indexOf(t) >= 0) || '';
    const at = v(r, c.date) instanceof Date ? v(r, c.date) : null;
    const owner = clean(v(r, c.doer) || v(r, c.recvBy));
    const typ = REQ_TYPES.indexOf(job) >= 0 ? job : 'อื่นๆ';
    rows.push({ id: '', received_at: at || '', channel: String(v(r, c.ch) || ''), type: typ, requester: firstLine.slice(0, 120), phone,
      address: tbRaw, tambon: tb, detail: (typ === 'อื่นๆ' && job !== 'อื่นๆ' ? '[' + job + '] ' : '') + detail, doc_no: '', br1_book: '', br1_no: '', owner,
      due: at ? dueFor_('ปกติ', at) : '', status, result, done_at: done && v(r, c.doneAt) instanceof Date ? v(r, c.doneAt) : '', transfer_to: String(v(r, c.fwdTo) || ''),
      history: JSON.stringify([{ at: at ? fmtDT_(at) : '', by: clean(v(r, c.recvBy)), act: 'นำเข้าจากสมุดคุมเดิม', note: String(v(r, c.note) || '') }]),
      photos: '', links: '', lat: '', lon: '', created_by: 'นำเข้าข้อมูลเดิม', created_at: new Date(), updated_by: '', updated_at: '', legacy });
  }
  rows.sort((a, b) => (a.received_at || 0) - (b.received_at || 0));
  if (src && !src.apply) return { add: rows.length, skip: skipped, sample: rows.slice(0, 50).map(r => ({ at: r.received_at ? fmtDate_(r.received_at) : '', type: r.type, requester: r.requester, tambon: r.tambon, status: r.status, owner: r.owner })) };
  const ids = rows.length ? nextIds_(SH.REQ, 'CR-', rows.length) : [];
  rows.forEach((r, i) => { r.id = ids[i]; });
  if (rows.length) appendRows_(SH.REQ, rows);
  audit_(src ? src.by : 'system', 'IMPORT_REQUESTS', 'Requests', '', 'นำเข้า ' + rows.length + ' เรื่องจาก ' + sh.getName(), '');
  ui('นำเข้างานคำร้องจากสมุดคุมเดิม ' + rows.length + ' เรื่อง ✔ (เรื่องที่เคยนำเข้าแล้วจะไม่ซ้ำ)');
  return { added: rows.length };
}

/**
 * Fault.gs (v1.4 ข้อ 13) : ข้อมูล Fault ของเหตุการณ์แรงสูง + แนะนำจุดตรวจจากสถิติเหตุการณ์เดิม
 *  - ดึงค่ากระแส/เฟส/ระยะ/ผลค้นหา จากข้อความ Log book เดิม (ต้องให้คนตรวจทาน)
 *  - เทียบเหตุการณ์ใหม่กับเหตุการณ์เดิมของอุปกรณ์เดียวกัน (เฟส + กระแสใกล้เคียง)
 */
const FAULT_FIELDS = ['fault_device', 'fault_phase', 'fault_i', 'fault_ia', 'fault_ib', 'fault_ic', 'fault_in', 'fault_reclose', 'fault_src', 'fault_found', 'fault_lat', 'fault_lon', 'fault_dist', 'fault_note'];
const FAULT_LEGACY_NOTE = 'ดึงจากข้อความเดิม';

function faultNum_(s) { const n = Number(String(s || '').replace(/,/g, '').replace(/\.$/, '')); return isFinite(n) && n > 0 ? n : null; }
function normPhase_(s) {
  const t = String(s || '').toUpperCase();
  const out = ['A', 'B', 'C', 'G'].filter(x => t.indexOf(x) >= 0);
  return out.join(',');
}

/** แยกข้อมูล Fault จากข้อความอิสระ (คืน null ถ้าไม่พบค่ากระแส) */
function faultParse_(text) {
  const t = String(text || '').replace(/\s+/g, ' ');
  let i = null;
  const m1 = t.match(/(?:I\s*_?\s*F(?:AULT)?|IFAULT|กระแส(?:\s*FAULT)?|FAULT)\s*[=:]?\s*([\d][\d,\.]*)/i);
  if (m1) i = faultNum_(m1[1]);
  if (!i && /โชว์|ทริป|T\/R|T\/L|TRIP/i.test(t)) {
    const m2 = t.match(/([\d]{1,2},?\d{3}|\d{3,5})\s*(?:A\b|A\.|แอมป์)/);
    if (m2) { const v = faultNum_(m2[1]); if (v && v >= 300) i = v; }
  }
  if (!i || i > 30000) return null;
  const ph = t.match(/โชว์\s*(?:เฟส)?\s*([ABCGabcg][ABCGabcg ,\.\-\/]*)/);
  const rc = t.match(/T\/R\s*(\d+)\s*ครั้ง/i);
  const dm = t.match(/ห่าง(?:จาก)?[^\d]{0,40}?([\d]+(?:\.\d+)?)\s*(กม|กิโล|km|ม\.|เมตร)/i);
  let dist = '';
  if (dm) dist = /กม|กิโล|km/i.test(dm[2]) ? +dm[1] : Math.round(+dm[1]) / 1000;
  const found = /ไม่พบ|หาไม่เจอ|ไม่เจอ/.test(t) ? 'ไม่พบ' : /พบ|ช็อต|ช๊อต|ชอต|ไหม้|ขาด/.test(t) ? 'พบ' : '';
  return { i, phase: ph ? normPhase_(ph[1]) : '', reclose: rc ? +rc[1] : '', dist, found };
}

/** หาพิกัดจากรหัสหม้อแปลง/อุปกรณ์ที่อยู่ในข้อความ */
function faultPointFromText_(text) {
  const t = String(text || '');
  const cands = (t.match(/\d{2,3}\/\d{2}-\d{5,6}|\b\d{2}-\d{5,6}(?:\/\d+)?|[A-Z]{3}\d{2}[FSR]-\d{1,3}/g) || []);
  for (const c of cands) {
    const code = c.indexOf('/') > 0 && /^\d{2,3}\//.test(c) ? c.split('/')[1] : c;
    const reg = regOf_(code);
    if (reg && reg.lat !== '' && reg.lon !== '') return { lat: +reg.lat, lon: +reg.lon, code: String(reg.code) };
  }
  return null;
}

/** อัปเกรด v1.4: ดึงข้อมูล Fault เดิมจากข้อความของเหตุการณ์แรงสูง */
function backfillFault_() {
  const t = table_(SH.EVENTS, true);
  if (t.map.fault_i == null) return 0;
  const last = t.sh.getLastRow();
  if (last < 2) return 0;
  const cols = FAULT_FIELDS.map(k => t.map[k]);
  const minC = Math.min.apply(null, cols), maxC = Math.max.apply(null, cols);
  const rng = t.sh.getRange(2, minC + 1, last - 1, maxC - minC + 1);
  const vals = rng.getValues();
  let n = 0;
  t.rows.forEach(r => {
    if (r.voltage !== 'HV' || r.fault_i !== '' && r.fault_i != null) return;
    const text = [r.cause, r.action, r.location, r.remark].join(' ');
    const f = faultParse_(text);
    if (!f) return;
    const row = vals[r._row - 2];
    const set = (k, v) => { row[t.map[k] - minC] = v; };
    const pt = faultPointFromText_(text);
    set('fault_device', r.device); set('fault_phase', f.phase); set('fault_i', f.i); set('fault_reclose', f.reclose);
    set('fault_found', f.found); set('fault_dist', f.dist); set('fault_src', 'Log book');
    if (pt) { set('fault_lat', pt.lat); set('fault_lon', pt.lon); }
    set('fault_note', FAULT_LEGACY_NOTE);
    n++;
  });
  if (n) { rng.setValues(vals); invalidate_(SH.EVENTS); }
  return n;
}

function hasFault_(e) { return [e.fault_i, e.fault_ia, e.fault_ib, e.fault_ic, e.fault_in].some(v => v !== '' && v != null && +v > 0); }
function faultI_(e) { const v = [e.fault_i, e.fault_ia, e.fault_ib, e.fault_ic, e.fault_in].map(Number).filter(x => x > 0); return v.length ? Math.max.apply(null, v) : null; }

/** เหตุการณ์คล้ายกันในอดีต: อุปกรณ์ที่ทริปเดียวกัน (ไม่พอค่อยขยายเป็นฟีดเดอร์เดียวกัน) เรียงตามเฟส + กระแส */
function apiFaultSimilar(token, o) {
  auth_(token, 'view');
  requireFeature_('fault');
  o = o || {};
  const dev = normDevice_(o.device || '').code;
  if (!dev) return { ok: false, error: 'กรุณาระบุอุปกรณ์ที่ทริป' };
  const I = faultNum_(o.i), ph = normPhase_(o.phase);
  const reg = regOf_(dev);
  const feeder = (reg && reg.feeder) || normDevice_(dev).feeder || '';
  const all = events_().filter(e => e.id !== o.exclude && hasFault_(e));
  const same = all.filter(e => sameDevice_(e.fault_device || e.device, dev));
  let pool = same.map(e => ({ e, scope: 'อุปกรณ์เดียวกัน' }));
  if (o.withFeeder !== false && pool.length < 5 && feeder) pool = pool.concat(all.filter(e => same.indexOf(e) < 0 && (e.feeder === feeder || ((regOf_(e.fault_device || e.device) || {}).feeder === feeder))).map(e => ({ e, scope: 'ฟีดเดอร์เดียวกัน' })));
  const phaseSim = (a, b) => { const A = a.split(',').filter(Boolean), B = b.split(',').filter(Boolean); if (!A.length || !B.length) return 0.5; const inter = A.filter(x => B.indexOf(x) >= 0).length; return inter / (A.length + B.length - inter); };
  const rows = pool.map(({ e, scope }) => {
    const ei = faultI_(e);
    const diff = I && ei ? Math.abs(ei - I) / I : null;
    const ps = phaseSim(ph, normPhase_(e.fault_phase));
    const found = e.fault_found === 'พบ';
    const score = (scope === 'อุปกรณ์เดียวกัน' ? 1 : 0.7) * ((scope === 'อุปกรณ์เดียวกัน' ? 0.15 : 0) + 0.35 * ps + 0.4 * (diff == null ? 0.3 : Math.max(0, 1 - diff / 0.3)) + (found ? 0.1 : 0));
    const r2 = regOf_(e.device);
    const lat = e.fault_lat !== '' && e.fault_lat != null ? +e.fault_lat : null;
    return { id: e.id, time: fmtDT_(evTime_(e)), device: e.device, fault_device: e.fault_device || e.device, phase: normPhase_(e.fault_phase), i: ei,
      diff: diff == null ? '' : Math.round(diff * 100), reclose: e.fault_reclose, found: e.fault_found || '', dist: e.fault_dist, cause_cat: e.cause_cat,
      cause: String(e.cause || '').slice(0, 160), location: placeText_(e, 60), scope, score: Math.round(score * 100),
      lat: lat != null ? lat : (r2 && r2.lat !== '' ? +r2.lat : ''), lon: lat != null ? +e.fault_lon : (r2 && r2.lon !== '' ? +r2.lon : ''), pinned: lat != null,
      legacy: String(e.fault_note || '').indexOf(FAULT_LEGACY_NOTE) === 0 };
  }).sort((a, b) => (a.scope === b.scope ? 0 : a.scope === 'อุปกรณ์เดียวกัน' ? -1 : 1) || b.score - a.score).slice(0, 12);
  const n = same.length, foundN = same.filter(e => e.fault_found === 'พบ').length;
  const og = regOf_(dev);
  return { ok: true, device: dev, feeder, rows, origin: og && og.lat !== '' ? { lat: +og.lat, lon: +og.lon } : null, stats: { sameDevice: n, found: foundN, notFound: same.filter(e => e.fault_found === 'ไม่พบ').length },
    note: n < 5 ? 'ข้อมูลของอุปกรณ์นี้ยังน้อย (' + n + ' ครั้ง) — ใช้ประกอบการตัดสินใจเท่านั้น' : '' };
}

/** สรุปข้อมูล Fault ตามอุปกรณ์/ฟีดเดอร์ */
function apiFaultSummary(token) {
  auth_(token, 'view');
  requireFeature_('fault');
  const evs = events_().filter(hasFault_);
  const by = {};
  evs.forEach(e => {
    const k = e.fault_device || e.device;
    const o = by[k] || (by[k] = { device: k, n: 0, found: 0, legacy: 0, imax: 0, imin: 1e9, last: null });
    const I = faultI_(e);
    o.n++; if (e.fault_found === 'พบ') o.found++; if (e.fault_note === FAULT_LEGACY_NOTE) o.legacy++;
    if (I) { o.imax = Math.max(o.imax, I); o.imin = Math.min(o.imin, I); }
    if (!o.last || evTime_(e) > o.last) o.last = evTime_(e);
  });
  return { total: evs.length, pending: evs.filter(e => e.fault_note === FAULT_LEGACY_NOTE).length,
    rows: Object.values(by).sort((a, b) => b.n - a.n).map(o => Object.assign(o, { imin: o.imin === 1e9 ? '' : o.imin, last: fmtDT_(o.last) })) };
}

/**
 * V14.gs : สวิตช์เปิด/ปิดโมดูล (ข้อ 22) · อัปเกรด v1.4 · ชุดเสริม (ข้อ 11) · บีบอัดรูปเดิม (ข้อ 12)
 */

// =====================================================================  ข้อ 22 สวิตช์โมดูล
const FEATURES = [
