/** แทนที่รูปเดิมด้วยรูปที่ย่อแล้ว: อัปโหลดไฟล์ใหม่ → เปลี่ยนการอ้างอิงในทุกชีต → ย้ายไฟล์เดิมไปถังขยะ */
function apiReplacePhoto(token, oldId, dataUrl) {
  const s = auth_(token, 'admin');
  const m = String(dataUrl || '').match(/^data:(image\/[a-z+]+);base64,(.+)$/);
  if (!m) return { ok: false, error: 'ไฟล์รูปไม่ถูกต้อง' };
  const old = DriveApp.getFileById(oldId);
  const bytes = Utilities.base64Decode(m[2]);
  if (bytes.length >= old.getSize()) return { ok: true, skipped: true, reason: 'ไฟล์ใหม่ไม่เล็กกว่าเดิม' };
  const folder = getFolder_('photo_folder_id', 'OMS-กำแพงแสน-รูปภาพ');
  const name = old.getName().replace(/\.[a-z]+$/i, '') + '_c.jpg';
  const nf = folder.createFile(Utilities.newBlob(bytes, 'image/jpeg', name));
  nf.setDescription((old.getDescription() || '') + ' · ย่อโดย ' + s.display);
  let refs = 0;
  withLock_(() => {
    PHOTO_REFS.forEach(([sheet, key]) => {
      const t = table_(sheet, true);
      if (t.map[key] == null) return;
      t.rows.forEach(r => {
        const v = String(r[key] || '');
        if (v.indexOf(oldId) < 0) return;
        const u = {}; u[key] = v.split(oldId).join(nf.getId());
        updateRow_(sheet, r._row, u); refs++;
