    const keys = { feeder: fdr, cause: e.cause_cat || '(ไม่ระบุ)', shift: e.shift || '(ไม่ระบุ)', month: evTime_(e) ? Utilities.formatDate(evTime_(e), APP.tz, 'yyyy-MM') : '' };
    Object.keys(by).forEach(k => { if (keys[k]) addTo(by[k][keys[k]] || (by[k][keys[k]] = grp()), e); });
    if (!e.device) return;
