      customers: reg && reg.customers !== '' ? +reg.customers : '', lat: reg && reg.lat !== '' ? +reg.lat : '', lon: reg && reg.lon !== '' ? +reg.lon : '' }, stats(D, 0));
  });
  const S = stats(sys, total);
  S.mttf_h = sys.n ? r1(rg.days * 24 / sys.n) : ''; S.customers = total; S.n = evs.length; S.sustained = sus.length; S.momentary = mom.length;
  const breakdown = {};
  Object.keys(by).forEach(k => {
    breakdown[k] = Object.keys(by[k]).map(key => Object.assign({ key, label: k === 'month' ? monthLabel_(key) : key }, stats(by[k][key], 0)))
      .filter(x => x.timed).sort((a, b) => k === 'month' ? a.key.localeCompare(b.key) : ((b.wn || 0) + (b.wd || 0) + (b.mttr || 0)) - ((a.wn || 0) + (a.wd || 0) + (a.mttr || 0))).slice(0, k === 'month' ? 24 : 12);
  });
  const fdT = feeders.filter(x => x.timed >= 2 && x.feeder[0] !== '(');
  // ข้อ 48: อัตราความเสียหายแยกตามสาเหตุ (ครั้ง/ปี) ต่อฟีดเดอร์ — ใช้ประเภทสาเหตุตาม OMS ถ้ามี ไม่งั้นใช้กลุ่มสาเหตุเดิม
  const rbc = {};
  evs.forEach(e => { if (momentary_(e)) return; const fdr = feederOf_(e) || '(ไม่ทราบฟีดเดอร์)', c = e.cause_type || e.cause_cat || '(ไม่ระบุ)'; const o = rbc[fdr] || (rbc[fdr] = { feeder: fdr, total: 0, causes: {} }); o.total++; o.causes[c] = (o.causes[c] || 0) + 1; });
  const rateByCause = Object.values(rbc).map(o => ({ feeder: o.feeder, total: r1(o.total / years), causes: Object.keys(o.causes).map(c => ({ cause: c, n: o.causes[c], rate: r1(o.causes[c] / years) })).sort((a, b) => b.n - a.n) }))
