// =====================================================================  ข้อ 16 หน้าต่างการบำรุงรักษา
/** งาน PM ที่ยังเปิดอยู่ใกล้จุด/ฟีดเดอร์เดียวกัน */
function pmNear_(o) {
  const reg = o.device ? regOf_(o.device) : null;
  const pt = o.lat ? { lat: +o.lat, lon: +o.lon } : (reg && reg.lat !== '' ? { lat: +reg.lat, lon: +reg.lon } : null);
  const feeder = o.feeder || (reg && reg.feeder) || (o.device ? normDevice_(o.device).feeder : '') || '';
  const radius = settingNum_('window_radius_km', 1);
  const out = [];
  table_(SH.PM).rows.filter(p => p.id && pmOpen_(p) && (p.category !== HOTLINE_CAT || String(p.needs_outage).toUpperCase() === 'TRUE')).forEach(p => {
    const preg = p.device ? regOf_(p.device) : null;
    const ppt = p.lat !== '' && p.lat != null ? { lat: +p.lat, lon: +p.lon } : (preg && preg.lat !== '' ? { lat: +preg.lat, lon: +preg.lon } : null);
    const km = kmBetween_(pt, ppt);
    const pf = p.feeder || (preg && preg.feeder) || '';
    const near = km != null && km <= radius, sameF = !!feeder && pf === feeder;
    if (!near && !sameF) return;
    out.push(Object.assign(serPm_(p), { km: km == null ? '' : Math.round(km * 100) / 100, why: near ? 'ห่าง ' + (Math.round(km * 10) / 10) + ' กม.' : 'ฟีดเดอร์ ' + pf }));
  });
