}
function apiPmNear(token, o) {
  auth_(token, 'view');
  if (!feature_('maint_window') || !feature_('pm')) return { ok: true, rows: [] };
  return { ok: true, rows: pmNear_(o || {}).slice(0, 30) };
}
function windowStats_(rg) {
  const pl = table_(SH.PLANNED).rows.filter(p => p.id && p.pm_ids && (!rg || ((p.date instanceof Date ? p.date : parseDT_(p.date)) >= rg.from && (p.date instanceof Date ? p.date : parseDT_(p.date)) < rg.to)));
  const done = pl.filter(p => p.status === 'ดำเนินการแล้ว');
  const cnt = list => list.reduce((a, p) => a + String(p.pm_ids).split(/[,\s]+/).filter(Boolean).length, 0);
  return { plans: pl.length, pmPlanned: cnt(pl), plansDone: done.length, saved: cnt(done) };
