// =====================================================================  ข้อ 17 แผนตรวจ/ลาดตระเวนตามความเสี่ยง
const INSP_TYPES = ['ลาดตระเวน', 'Thermoscan', 'สำรวจต้นไม้', 'ระยะต้นไม้', 'Partial Discharge', 'วัดค่าความต้านทานดิน'];
const INSP_SEVERITY = ['ปกติ', 'เฝ้าระวัง', 'ต้องแก้ไข', 'เร่งด่วน'];
const CAUSE_WEIGHT = [[/ต้นไม้|กิ่งไม้/, 1.0, 'ต้นไม้'], [/สัตว์|งู|กระรอก|นก/, 1.0, 'สัตว์'], [/หลวม|จุดต่อ|จั๊ม/, 1.0, 'หลวมจุดต่อ'],
  [/อุปกรณ์ชำรุด|ลูกถ้วย|LA|DO/, 0.8, 'อุปกรณ์ชำรุด'], [/สายขาด|สายชำรุด/, 0.6, 'สายขาด/ชำรุด'], [/ฟิวส์.*ไม่ระบุ|ป้องกันทำงาน/, 0.5, 'ไม่ทราบสาเหตุ'],
  [/ฟ้าผ่า|พายุ/, 0.3, 'ฟ้าผ่า/พายุ'], [/ภายในผู้ใช้ไฟ|รถ|บุคคลภายนอก|มิเตอร์|ตามแผน/, 0, '']];
function causeWeight_(c) { for (const [re, w, lab] of CAUSE_WEIGHT) if (re.test(String(c || ''))) return { w, lab }; return { w: 0.2, lab: 'อื่นๆ' }; }
function zoneOf_(e) { const f = feederOf_(e) || '?'; return f + '|' + (e.tambon || '?'); }
function zoneLabel_(z) { const [f, t] = z.split('|'); return f === '?' ? 'ต.' + (t === '?' ? 'ไม่ระบุ' : t) + ' (ไม่ทราบฟีดเดอร์)' : 'ฟีดเดอร์ ' + f + ' · ต.' + (t === '?' ? 'ไม่ระบุ' : t); }

function patrolRank_(asOf) {
  const now = asOf || new Date();
  const all = events_().filter(e => !e.parent_id && PLANNED_TYPES.indexOf(e.type) < 0 && evTime_(e));
  const yr = all.filter(e => now - evTime_(e) <= 365 * 86400000);
  // ฤดูกาล: สัดส่วนของสาเหตุนั้นในเดือนใกล้เคียง เทียบค่าเฉลี่ยทั้งปี (จากข้อมูลทั้งหมด)
  const m0 = now.getMonth(), monthCnt = {}, totCnt = {};
  all.forEach(e => { const lab = causeWeight_(e.cause_cat).lab; const m = evTime_(e).getMonth(); totCnt[lab] = (totCnt[lab] || 0) + 1; if ([m0, (m0 + 11) % 12, (m0 + 1) % 12].indexOf(m) >= 0) monthCnt[lab] = (monthCnt[lab] || 0) + 1; });
  const season = lab => totCnt[lab] ? Math.max(0.5, Math.min(2, ((monthCnt[lab] || 0) / 3) / (totCnt[lab] / 12))) : 1;
  const Z = {};
  const zget = z => Z[z] || (Z[z] = { zone: z, score: 0, n: 0, n180: 0, causes: {}, devices: {}, customers: 0, pm: 0, meas: 0, lastInsp: null });
  yr.forEach(e => {
    const cw = causeWeight_(e.cause_cat);
    if (!cw.w) return;
    const age = (now - evTime_(e)) / 86400000;
    const z = zget(zoneOf_(e));
    z.score += cw.w * Math.exp(-age / 120) * season(cw.lab);
    z.n++; if (age <= 180) { z.n180++; z.causes[cw.lab] = (z.causes[cw.lab] || 0) + 1; }
    const k = e.device || '';
    if (k) z.devices[k] = (z.devices[k] || 0) + 1;
  });
  table_(SH.DEVICES).rows.forEach(d => { if (/หม้อแปลง/.test(String(d.kind))) { const z = Z[(d.feeder || '?') + '|' + (d.tambon || '?')]; if (z) z.customers += Number(d.customers) || 0; } });
  table_(SH.PM).rows.filter(p => p.id && pmOpen_(p)).forEach(p => { const z = Z[(p.feeder || '?') + '|' + (p.tambon || '?')]; if (z) z.pm++; });
  const since = new Date(now - 180 * 86400000);
  table_(SH.MEAS).rows.filter(m => m.flags && m.date instanceof Date && m.date >= since && !isDeleted_(m)).forEach(m => {
    const reg = regOf_(m.device); if (!reg) return; const z = Z[(reg.feeder || '?') + '|' + (reg.tambon || '?')]; if (z) z.meas++;
  });
  table_(SH.INSP).rows.forEach(i => { const z = Z[i.zone]; const d = asDate_(i.date); if (z && d && (!z.lastInsp || d > z.lastInsp)) z.lastInsp = d; });
  const maxDays = settingNum_('patrol_max_days', 180);
  return Object.values(Z).filter(z => z.score > 0 && z.zone !== '?|?').map(z => {
    const days = z.lastInsp ? Math.floor((now - z.lastInsp) / 86400000) : null;
    const overdue = days == null ? 1.5 : Math.min(1.5, days / maxDays);
    const fC = 1 + Math.log10(1 + z.customers) / 4, fO = 1 + 0.5 * overdue;
    const score = (z.score * fC * fO) + z.pm * 0.5 + z.meas * 0.3;
    const r1 = x => Math.round(x * 10) / 10;
    const parts = { events: r1(z.score), customers: r1(z.score * (fC - 1)), overdue: r1(z.score * fC * (fO - 1)), pm: r1(z.pm * 0.5), meas: r1(z.meas * 0.3) };
    const top = Object.keys(z.causes).sort((a, b) => z.causes[b] - z.causes[a]);
    const isMeter = c => /^\d{8,}$/.test(String(c)) && !/[-\/]/.test(String(c));
    const devs = Object.keys(z.devices).sort((a, b) => (isMeter(a) - isMeter(b)) || (z.devices[b] - z.devices[a])).slice(0, 8).map(code => {
      const reg = regOf_(code); return { device: code, n: z.devices[code], meter: isMeter(code), lat: reg && reg.lat !== '' ? +reg.lat : '', lon: reg && reg.lon !== '' ? +reg.lon : '' };
    });
    let center = null;
    if (!devs.some(d => d.lat !== '')) { const tb = z.zone.split('|')[1]; const t = table_(SH.TAMBON).rows.find(x => String(x.name) === tb); if (t && t.lat !== '') center = { lat: +t.lat, lon: +t.lon, label: 'กลาง ต.' + tb }; }
    const pts = devs.filter(d => d.lat !== '');
    const nav = !pts.length && center ? 'https://www.google.com/maps/dir/?api=1&destination=' + center.lat + ',' + center.lon : pts.length ? 'https://www.google.com/maps/dir/?api=1&destination=' + pts[0].lat + ',' + pts[0].lon + (pts.length > 1 ? '&waypoints=' + pts.slice(1, 9).map(p => p.lat + ',' + p.lon).join('|') : '') : '';
    const reasons = [];
    if (top.length) reasons.push(top.slice(0, 3).map(c => c + ' ' + z.causes[c] + ' ครั้ง').join(', ') + ' ใน 6 เดือน');
    if (z.customers) reasons.push('ผู้ใช้ไฟ ' + z.customers.toLocaleString() + ' ราย');
    reasons.push(days == null ? 'ยังไม่เคยตรวจ' : 'ไม่ได้ตรวจ ' + days + ' วัน');
    if (z.pm) reasons.push('งาน PM ค้าง ' + z.pm);
    if (z.meas) reasons.push('ค่าวัดโหลดเกินเกณฑ์ ' + z.meas);
    const [feeder, tambon] = z.zone.split('|');
    return { zone: z.zone, label: zoneLabel_(z.zone), feeder: feeder === '?' ? '' : feeder, tambon: tambon === '?' ? '' : tambon, score: Math.round(score * 10) / 10,
      n: z.n, n180: z.n180, customers: z.customers, pm: z.pm, meas: z.meas, lastInsp: z.lastInsp ? fmtDate_(z.lastInsp) : '', days, reasons: reasons.join(' · '), devices: devs, nav, center, parts };
  }).sort((a, b) => b.score - a.score);
}

function apiPatrol(token, f) {
  auth_(token, 'view');
