/** วัดผล: เหตุการณ์ (สาเหตุป้องกันได้) ต่อพื้นที่ใน 90 วันหลังตรวจ เทียบ 90 วันก่อนตรวจ และเทียบพื้นที่ที่ไม่ได้ตรวจ */
function patrolEffect_() {
  const now = new Date();
  const evs = events_().filter(e => !e.parent_id && causeWeight_(e.cause_cat).w > 0 && evTime_(e));
  const insp = table_(SH.INSP).rows.filter(i => asDate_(i.date) && now - asDate_(i.date) >= 90 * 86400000 && now - asDate_(i.date) <= 455 * 86400000);
  if (!insp.length) return { inspected: 0, note: 'ยังไม่มีข้อมูลการตรวจที่ครบ 90 วัน' };
  let before = 0, after = 0;
  const zones = {};
  insp.forEach(i => {
    const d = asDate_(i.date); zones[i.zone] = true;
    evs.forEach(e => { if (zoneOf_(e) !== i.zone) return; const dt = (evTime_(e) - d) / 86400000; if (dt > 0 && dt <= 90) after++; else if (dt <= 0 && dt > -90) before++; });
  });
  const others = {};
  evs.forEach(e => { const z = zoneOf_(e); if (zones[z]) return; const age = (now - evTime_(e)) / 86400000; const o = others[z] || (others[z] = [0, 0]); if (age <= 90) o[1]++; else if (age <= 180) o[0]++; });
  const ov = Object.values(others), ob = ov.reduce((a, x) => a + x[0], 0), oa = ov.reduce((a, x) => a + x[1], 0);
  const pct = (b, a) => b ? Math.round((a - b) / b * 100) : null;
  return { inspected: insp.length, before, after, change: pct(before, after), otherBefore: ob, otherAfter: oa, otherChange: pct(ob, oa) };
}

function apiInspectionSave(token, o) {
  const s = auth_(token, 'inspect.write');
  requireFeature_('patrol');
  o = o || {};
  if (INSP_TYPES.indexOf(o.type) < 0) return { ok: false, error: 'กรุณาเลือกชนิดการตรวจ' };
  if (!o.zone && !o.device && !o.lat) return { ok: false, error: 'กรุณาระบุพื้นที่ อุปกรณ์ หรือปักหมุดจุดตรวจ' };
  let sev = o.severity;
  if (o.type === 'Thermoscan' && o.delta_t !== '' && o.delta_t != null && !sev) { const d = +o.delta_t; sev = d > 35 ? 'เร่งด่วน' : d > 10 ? 'เฝ้าระวัง' : 'ปกติ'; }
  // ข้อ 32: สภาพตามคู่มือ → ระดับและกำหนดเสร็จงาน PM (ไม่ดี 7 วัน · พอใช้ 90 วัน)
  if (o.cond === 'ไม่ดี' && !o.severity) sev = 'ต้องแก้ไข';
  if (o.cond === 'พอใช้' && !o.severity && sev === 'ปกติ') { sev = 'เฝ้าระวัง'; o.createPm = true; }
  if (INSP_SEVERITY.indexOf(sev) < 0) sev = 'ปกติ';
  return withLock_(() => {
    const reg = o.device ? regOf_(o.device) : null;
    const zone = o.zone || ((reg && reg.feeder) || '?') + '|' + ((reg && reg.tambon) || o.tambon || '?');
    const id = nextIds_(SH.INSP, 'IN-', 1)[0];
    let pmId = '';
    if ((sev === 'เร่งด่วน' || sev === 'ต้องแก้ไข' || o.createPm) && feature_('pm')) {
      const cat = o.pmCategory || (o.type === 'สำรวจต้นไม้' ? 'ตัดต้นไม้' : o.type === 'Thermoscan' ? 'ตรวจ Thermoscan/ขันจุดต่อ' : 'อื่นๆ');
      const codes = String(o.codes || '');
      pmId = pmUpsert_({ source: 'ผลตรวจ ' + id + (codes ? ' [' + codes + ']' : ''), device: o.device ? normDevice_(o.device).code : '', feeder: zone.split('|')[0].replace('?', ''), tambon: o.tambon || zone.split('|')[1].replace('?', ''),
        location: o.findings ? String(o.findings).slice(0, 80) : zoneLabel_(zone), category: cat, priority: sev === 'เร่งด่วน' ? 'ด่วน' : 'ปกติ',
        detail: o.type + (o.delta_t ? ' ΔT ' + o.delta_t + '°C' : '') + (o.tree_dist ? ' ระยะต้นไม้ ' + o.tree_dist + ' ม.' : '') + ' — ' + (o.findings || ''), photos_before: o.photos || [] }, s.display); // v1.11 ข้อ 90
    }
    appendRows_(SH.INSP, [{ id, date: o.date ? parseDT_(o.date) : new Date(), type: o.type, zone, feeder: zone.split('|')[0].replace('?', ''), tambon: o.tambon || zone.split('|')[1].replace('?', ''),
      device: o.device || '', lat: o.lat || (reg && reg.lat) || '', lon: o.lon || (reg && reg.lon) || '', findings: String(o.findings || '').slice(0, 1500), delta_t: o.delta_t || '',
      severity: sev, tree_dist: o.tree_dist || '', photos: (o.photos || []).join(','), inspector: o.inspector || s.display, pm_id: pmId, created_by: s.display, created_at: new Date(),
      codes: String(o.codes || ''), cond: String(o.cond || '') }]);
    if (pmId && o.cond && COND_DUE[o.cond]) { const p = table_(SH.PM, true).rows.find(x => x.id === pmId); if (p && !p.due) updateRow_(SH.PM, p._row, { due: new Date(Date.now() + COND_DUE[o.cond] * 86400000) }); }
    audit_(s.display, 'INSPECTION', 'Inspections', id, [o.type, zoneLabel_(zone), sev, o.findings].filter(Boolean).join(' · '), '');
    return { ok: true, id, pmId, severity: sev };
  });
}
