// =====================================================================  ข้อ 19 ครอบกันสัตว์ (v1.5: แยกหม้อแปลง/ดร็อปเอาท์ · เก็บประวัติทุกครั้ง)
const AG_PARTS = [['ag_hv', 'บุชชิ่ง HV'], ['ag_lv', 'บุชชิ่ง LV'], ['ag_do', 'ดร็อปเอาท์'], ['ag_la', 'ล่อฟ้า']];
const AG_VALUES = ['มี', 'ไม่มี', 'ชำรุด', 'ไม่มีอุปกรณ์นี้'];
/** ชนิดสำหรับครอบกันสัตว์: หม้อแปลง / ดร็อปเอาท์ (D/F) */
function agKind_(d) { return /หม้อแปลง/.test(String(d.kind)) || /^\d{2}-\d+/.test(String(d.code)) ? 'หม้อแปลง' : /ดร็อปเอาท์|ฟิวส์/.test(String(d.kind)) ? 'ดร็อปเอาท์' : ''; }
function devRetired_(d) { return String(d.dev_status || '') === 'เลิกใช้งาน'; }
function agStatus_(d) {
  const parts = agKind_(d) === 'ดร็อปเอาท์' ? AG_PARTS.filter(([k]) => k === 'ag_do' || k === 'ag_la') : AG_PARTS;
  const v = parts.map(([k]) => String(d[k] || ''));
  if (!d.ag_date) return 'ยังไม่สำรวจ';
  if (v.indexOf('ไม่มี') >= 0) return 'ยังไม่มีครอบ';
  if (v.indexOf('ชำรุด') >= 0) return 'ชำรุด';
  return 'ครบ';
}
function saveAnimalGuard_(rec, ag, user) {
  if (!rec.device) return;
  const vals = {};
  AG_PARTS.forEach(([k]) => { const x = ag[k.slice(3)] || ag[k]; if (AG_VALUES.indexOf(x) >= 0) vals[k] = x; });
  if (!Object.keys(vals).length) return;
  const t = table_(SH.DEVICES, true);
  const key = deviceKey_(normDevice_(rec.device).code);
  const d = t.rows.find(x => deviceKey_(x.code) === key);
  const now = new Date();
  const upd = Object.assign({}, vals, { ag_date: now, ag_by: user, ag_photo: ag.photo || (d && d.ag_photo) || '', ag_event: rec.id || '' });
  if (d) updateRow_(SH.DEVICES, d._row, upd);
  else appendRows_(SH.DEVICES, [Object.assign({ code: normDevice_(rec.device).code, key, kind: normDevice_(rec.device).kind, tambon: rec.tambon, location: placeText_(rec, 60), source: 'สำรวจครอบกันสัตว์' }, upd)]);
  try {
    appendRows_(SH.AGLOG, [{ id: nextIds_(SH.AGLOG, 'AG-', 1)[0], at: now, code: d ? String(d.code) : normDevice_(rec.device).code, hv: vals.ag_hv || '', lv: vals.ag_lv || '', do: vals.ag_do || '', la: vals.ag_la || '', by: user, photo: ag.photo || '', event_id: rec.id || '' }]);
  } catch (e) { console.warn('AGLOG ' + e.message); }
  audit_(user, 'ANIMAL_GUARD', 'Devices', rec.device, AG_PARTS.filter(([k]) => vals[k]).map(([k, l]) => l + ': ' + vals[k]).join(', '), rec.id || '');
}

function apiAnimalGuard(token, f) {
  auth_(token, 'view');
  requireFeature_('animal_guard');
  f = f || {};
  const animal = {};
  const since = new Date(Date.now() - 3 * 365 * 86400000);
  events_().filter(e => /สัตว์|งู|กระรอก|นก/.test(String(e.cause_cat) + String(e.cause)) && evTime_(e) >= since).forEach(e => { const k = deviceKey_(e.device); animal[k] = (animal[k] || 0) + 1; });
  const tr = table_(SH.DEVICES).rows.filter(d => agKind_(d) && !devRetired_(d));
  const blank = () => ({ total: 0, surveyed: 0, missing: 0, damaged: 0, complete: 0, pct: 0 });
  const stats = { 'หม้อแปลง': blank(), 'ดร็อปเอาท์': blank() };
  const pts = [], rank = [];
  const pmOpenAg = {};
  table_(SH.PM).rows.forEach(p => { if (pmOpen_(p) && p.category === 'ติดครอบกันสัตว์' && p.device) pmOpenAg[deviceKey_(p.device)] = true; });
  tr.forEach(d => {
    const kind = agKind_(d), st = agStatus_(d), S = stats[kind];
    S.total++; if (st !== 'ยังไม่สำรวจ') S.surveyed++; if (st === 'ยังไม่มีครอบ') S.missing++; if (st === 'ชำรุด') S.damaged++; if (st === 'ครบ') S.complete++;
    const n = animal[deviceKey_(d.code)] || 0;
    if (d.lat !== '' && d.lon !== '' && (st !== 'ยังไม่สำรวจ' || n)) pts.push([+d.lat, +d.lon, st, String(d.code), n, kind]);
    if ((st === 'ยังไม่มีครอบ' || st === 'ชำรุด') || (st === 'ยังไม่สำรวจ' && n)) {
      rank.push({ code: String(d.code), kind, feeder: d.feeder, tambon: d.tambon, location: d.location, customers: Number(d.customers) || 0, animal: n, status: st,
        parts: AG_PARTS.filter(([k]) => /^(ไม่มี|ชำรุด)$/.test(String(d[k] || ''))).map(([k, l]) => l + ' ' + d[k]).join(', '),
        date: d.ag_date instanceof Date ? fmtDate_(d.ag_date) : '', by: d.ag_by || '', photo: d.ag_photo || '', event: d.ag_event || '',
        lat: d.lat !== '' ? +d.lat : '', lon: d.lon !== '' ? +d.lon : '', pm: !!pmOpenAg[deviceKey_(d.code)] });
    }
  });
  Object.values(stats).forEach(S => { S.pct = S.total ? Math.round(S.surveyed / S.total * 100) : 0; });
  rank.sort((a, b) => (b.status !== 'ยังไม่สำรวจ') - (a.status !== 'ยังไม่สำรวจ') || b.animal - a.animal || b.customers - a.customers);
  const K = f.kind && stats[f.kind] ? f.kind : '';
  return { stats, stat: stats['หม้อแปลง'], rank: rank.filter(x => !K || x.kind === K).slice(0, 300), points: f.points ? pts.filter(x => !K || x[5] === K) : [] };
}

