function upgradeV15(silent) {
  [SH.EVENTS, SH.DEVICES, SH.PM, SH.PLANNED, SH.REQ, SH.USERS, SH.FEEDBACK, SH.DEVLOG, SH.AGLOG, SH.WBS, SH.AREAS].forEach(n => { ensureSheet_(n); cacheDrop_(n); });
  __settings = null;
  const keys = table_(SH.SETTINGS, true).rows.map(r => String(r.key).trim());
  const add = V15_SETTINGS.filter(([k]) => keys.indexOf(k) < 0).map(([key, value, desc]) => ({ key, value, desc }));
  if (add.length) appendRows_(SH.SETTINGS, add);
  invalidate_(SH.SETTINGS);
  // สิทธิ์ WBS รายบุคคล
  const names = String(setting_('wbs_users', '')).split(',').map(x => x.trim()).filter(Boolean);
  let nWbs = 0;
  table_(SH.USERS, true).rows.forEach(u => {
    const disp = String(u.display || '');
    if (!names.some(n => disp.indexOf(n) >= 0 || n.indexOf(disp) >= 0 && disp.length > 3)) return;
    const ex = String(u.extra_perms || '').split(/[,\s]+/).filter(Boolean);
    if (ex.indexOf('wbs.write') < 0) { ex.push('wbs.write'); updateRow_(SH.USERS, u._row, { extra_perms: ex.join(', ') }); nWbs++; }
  });
  // ประกาศแผนดับไฟเดิม → อื่นๆ
  table_(SH.PLANNED, true).rows.filter(p => p.id && p.notice && !p.notice_json).forEach(p => updateRow_(SH.PLANNED, p._row, { notice_json: JSON.stringify({ other: { on: true, date: '', text: String(p.notice) } }) }));
  // ประวัติครอบกันสัตว์เริ่มจากผลล่าสุด
  if (table_(SH.AGLOG, true).rows.filter(r => r.id).length === 0) {
    const rows = table_(SH.DEVICES).rows.filter(d => d.ag_date);
    if (rows.length) {
      const ids = nextIds_(SH.AGLOG, 'AG-', rows.length);
      appendRows_(SH.AGLOG, rows.map((d, i) => ({ id: ids[i], at: d.ag_date, code: String(d.code), hv: d.ag_hv || '', lv: d.ag_lv || '', do: d.ag_do || '', la: d.ag_la || '', by: d.ag_by || '', photo: d.ag_photo || '', event_id: d.ag_event || '' })));
    }
  }
  try { CacheService.getScriptCache().remove('boot_static'); } catch (e) { /* ignore */ }
  audit_('system', 'UPGRADE', 'System', '1.5.0', 'สิทธิ์ WBS ' + nWbs + ' คน', '');
  if (!silent) { try { SpreadsheetApp.getUi().alert('อัปเดตเป็น v1.5 เรียบร้อย ✔\nให้สิทธิ์งาน WBS ' + nWbs + ' คน (ปรับได้ในชีต Users คอลัมน์ "สิทธิ์เพิ่มรายบุคคล")\n\nอย่าลืม Deploy เวอร์ชันใหม่ของเว็บแอป'); } catch (e) { /* editor */ } }
  return { wbsUsers: nWbs };
}
function v15Static_() {
  return { tripKinds: TRIP_KINDS, relays: RELAYS, noticeChannels: NOTICE_CHANNELS, wbsStatus: WBS_STATUS, wbsKinds: WBS_KINDS, wbsReasonGroups: wbsReasonGroups_(),
    hotline: HOTLINE_CAT, plannedNoticeDays: settingNum_('planned_notice_days', 3), hvBig: { customers: settingNum_('hv_report_customers', 1000), minutes: settingNum_('hv_report_minutes', 60) },
    wideRemind: settingNum_('wide_remind_min', 30), relDefs: RELIABILITY_DEFS };
