function wbsReasonGroups_() {
  const custom = String(setting_('wbs_reasons', '') || '').split('|').map(x => x.trim()).filter(Boolean);
  if (!custom.length) return WBS_REASON_GROUPS;
  const known = {}; WBS_REASON_GROUPS.forEach(([g, l]) => l.forEach(x => { known[x] = g; }));
  const out = WBS_REASON_GROUPS.map(([g]) => [g, []]).concat([['อื่นๆ', []]]);
  custom.forEach(x => { const g = known[x] || 'อื่นๆ'; out.find(o => o[0] === g)[1].push(x); });
  return out.filter(o => o[1].length);
}

