  if (!String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุเหตุผลการแก้ตำแหน่ง' };
  const n = normDevice_(o.code);
  if (!n.code) return { ok: false, error: 'รหัสอุปกรณ์ไม่ถูกต้อง' };
