    else appendRows_(SH.DEVICES, [Object.assign({ code: n.code, key: deviceKey_(n.code), kind: n.kind, source: 'แก้ตำแหน่งในเว็บ' }, upd)]);
    devLog_({ code: d ? String(d.code) : n.code, action: 'แก้ตำแหน่ง', old_lat: d ? d.lat : '', old_lon: d ? d.lon : '', new_lat: upd.lat, new_lon: upd.lon, reason: String(o.reason).trim(), by: s.display, ref: o.ref || '' });
    audit_(s.display, 'DEVICE_MOVE', 'Devices', n.code, (d ? d.lat + ',' + d.lon : '-') + ' → ' + upd.lat + ',' + upd.lon, o.reason);
    invalidate_(SH.DEVICES);
    return { ok: true, tambon: upd.tambon || '' };
  });
