function apiDeviceTimeline(token, code) {
  auth_(token, 'view');
  const n = normDevice_(code);
  const key = deviceKey_(n.code || code);
  const same = c => !!c && deviceKey_(c) === key;
  const reg = regOf_(n.code || code);
  const items = [];
  const now = new Date();
  const evs = events_().filter(e => same(e.device) || same(e.device2) || same(e.fault_device)).sort((a, b) => (evTime_(a) || 0) - (evTime_(b) || 0));
  evs.forEach(e => items.push({ kind: 'CM', at: fmtDT_(evTime_(e)), ts: +evTime_(e) || 0, id: e.id, title: [e.voltage, e.type].filter(Boolean).join(' ') + ' · ' + (e.cause || e.cause_cat || ''),
    detail: [e.action ? 'แก้ไข: ' + e.action : '', Number(e.off_min) >= 1 ? 'ดับ ' + e.off_min + ' นาที' : '', e.customers ? e.customers + ' ราย' : '', e.lead ? 'พชง. ' + e.lead : ''].filter(Boolean).join(' · '),
    photos: photoList_(e.photo) }));
  table_(SH.PM).rows.filter(p => p.id && same(p.device)).forEach(p => {
