function ringsOf_(g) {
  if (!g) return [];
  if (typeof g === 'string') { try { g = JSON.parse(g); } catch (e) { return []; } }
  if (g.type === 'Feature') g = g.geometry;
  if (g.type === 'FeatureCollection') return [].concat(...g.features.map(f => ringsOf_(f.geometry)));
  if (g.type === 'Polygon') return [g.coordinates];
  if (g.type === 'MultiPolygon') return g.coordinates;
  return [];
}
function pointInArea_(lat, lon, area) {
  if (!(lat > 0)) return false;
  return ringsOf_(area).some(p => pointInRing_(lon, lat, p[0]) && !p.slice(1).some(h => pointInRing_(lon, lat, h)));
}
function villagesOf_(devs) {
  const v = {};
  devs.forEach(d => {
    const tb = String(d.tambon || '');
    const m = String(d.location || '').match(/(?:ม\.|หมู่(?:ที่)?\s*)(\d{1,2})/);
    if (!tb) return;
    (v[tb] = v[tb] || {});
    if (m) v[tb][+m[1]] = true;
  });
  return Object.keys(v).sort((a, b) => a.localeCompare(b, 'th')).map(t => ({ tambon: t, moo: Object.keys(v[t]).map(Number).sort((a, b) => a - b) }));
}
function areaSummary_(devs) {
  const tr = devs.filter(d => /หม้อแปลง/.test(String(d.kind)) && !devRetired_(d));
  const villages = villagesOf_(tr);
  const fc = {}; tr.forEach(d => { const f = String(d.feeder || ''); if (f) fc[f] = (fc[f] || 0) + 1; });
  return { feeders: Object.keys(fc).sort((a, b) => fc[b] - fc[a]), codes: tr.map(d => String(d.code)), transformers: tr.length, customers: tr.reduce((a, d) => a + (Number(d.customers) || 0), 0), villages,
    tambons: villages.map(v => v.tambon), mooCount: villages.reduce((a, v) => a + v.moo.length, 0) };
}
function apiDevicesInArea(token, area) {
