/** พื้นที่ของงาน WBS: ขอบเขตที่วาด > รัศมี 2 กม.จากหมุด > ฟีดเดอร์ (ใช้เมื่อรายการไม่มีพิกัด) */
function inWbsZone_(z, lat, lon, feeder) {
  const has = lat !== '' && lat != null && !isNaN(+lat) && +lat > 0;
  const sameF = !!z.feeder && String(feeder || '') === z.feeder;
  if (z.area) return has ? pointInArea_(+lat, +lon, z.area) : false;
  if (z.pt) { if (has) { const km = kmBetween_(z.pt, { lat: +lat, lon: +lon }); return km != null && km <= 2; } return sameF; }
  return sameF;
}
function apiWbsGet(token, id) {
  const s = auth_(token, 'view');
