  if (!w) return { ok: false, error: 'ไม่พบ ' + id };
  const evIds = String(w.event_ids || '').split(/[,\s]+/).filter(Boolean);
  const evAll = events_();
  const linkedEv = evAll.filter(e => evIds.indexOf(e.id) >= 0).map(e => ({ id: e.id, at: fmtDT_(evTime_(e)), type: e.type, device: e.device, cause: e.cause || e.cause_cat }));
  const linkedPm = table_(SH.PM).rows.filter(p => p.wbs_id === id).map(p => ({ id: p.id, category: p.category, device: p.device, status: p.status, location: p.location }));
  const linkedReq = table_(SH.REQ).rows.filter(r => r.wbs_id === id).map(r => ({ id: r.id, type: r.type, requester: r.requester, status: r.status }));
  // ผู้สมัคร: งานในพื้นที่/ฟีดเดอร์เดียวกันที่ยังไม่ได้ผูก
  const z = wbsArea_(w);
  const cand = { events: [], pm: [], req: [] };
  if (z.pt || z.area || z.feeder) {
    const since = new Date(Date.now() - 3 * 365 * 86400000);
    evAll.filter(e => !e.parent_id && evTime_(e) >= since && evIds.indexOf(e.id) < 0).forEach(e => {
      const reg = regOf_(e.device);
      if (inWbsZone_(z, reg ? reg.lat : '', reg ? reg.lon : '', feederOf_(e))) cand.events.push({ id: e.id, at: fmtDT_(evTime_(e)), type: e.type, device: e.device, cause: e.cause || e.cause_cat });
    });
    table_(SH.PM).rows.filter(p => p.id && pmOpen_(p) && p.wbs_id !== id).forEach(p => { if (inWbsZone_(z, p.lat, p.lon, p.feeder)) cand.pm.push({ id: p.id, category: p.category, device: p.device, location: p.location, wbs_id: p.wbs_id || '' }); });
    table_(SH.REQ).rows.filter(r => r.id && reqOpen_(r) && r.wbs_id !== id).forEach(r => { if (inWbsZone_(z, r.lat, r.lon, '') || (!z.area && !z.pt && false)) cand.req.push({ id: r.id, type: r.type, requester: r.requester, wbs_id: r.wbs_id || '' }); });
    if (w.tambon) table_(SH.REQ).rows.filter(r => r.id && reqOpen_(r) && r.wbs_id !== id && r.tambon === w.tambon && !cand.req.some(c => c.id === r.id)).forEach(r => cand.req.push({ id: r.id, type: r.type, requester: r.requester, wbs_id: r.wbs_id || '', byTambon: true }));
    cand.events = cand.events.slice(-100).reverse();
  }
  // วัดผล 12 เดือนก่อน/หลังแล้วเสร็จ
  let effect = null;
  const done = asDate_(w.done_at);
  if (done && w.status === 'แล้วเสร็จ') {
    const zoneEv = evAll.filter(e => !e.parent_id && PLANNED_TYPES.indexOf(e.type) < 0 && (evIds.indexOf(e.id) >= 0 || (() => { const reg = regOf_(e.device); return inWbsZone_(z, reg ? reg.lat : '', reg ? reg.lon : '', feederOf_(e)); })()));
    const win = (a, b) => zoneEv.filter(e => evTime_(e) >= a && evTime_(e) < b);
    const before = win(addDays_(done, -365), done), after = win(done, addDays_(done, 365));
    const cmi = l => l.reduce((x, e) => x + cmiOf_(e), 0);
    const dropReq = t => table_(SH.REQ).rows.filter(r => /ไฟตก/.test(r.type) && asDate_(r.received_at) && (w.tambon ? r.tambon === w.tambon : true) && t(asDate_(r.received_at))).length;
    const afterDays = Math.min(365, Math.round((Date.now() - done) / 86400000));
    const first = evAll.reduce((m, e) => { const t = evTime_(e); return t && (!m || t < m) ? t : m; }, null);
    const beforeDays = first ? Math.max(0, Math.min(365, Math.round((done - first) / 86400000))) : 0;
    effect = { before: before.length, after: after.length, afterDays, beforeDays, cmiBefore: Math.round(cmi(before)), cmiAfter: Math.round(cmi(after)),
      reqBefore: dropReq(d => d >= addDays_(done, -365) && d < done), reqAfter: dropReq(d => d >= done && d < addDays_(done, 365)) };
  }
  return { ok: true, wbs: serWbs_(w), history: histOf_(w), linked: { events: linkedEv, pm: linkedPm, req: linkedReq }, cand, effect,
    canWrite: permsOf_(s).indexOf('wbs.write') >= 0, reasonGroups: wbsReasonGroups_() };
}
function apiWbsSave(token, o) {
