      owner: String(o.owner || '').trim(), feeder: String(o.feeder || '').trim(), tambon: o.tambon || '', lat: o.lat || '', lon: o.lon || '', area: o.area ? (typeof o.area === 'string' ? o.area : JSON.stringify(o.area)) : '',
      status: o.status || 'เสนอ', reasons: JSON.stringify(reasons), main_reason: o.main_reason || (reasons[0] ? reasons[0].name : ''), note: String(o.note || '').slice(0, 1500) };
