    if (wt === 'CM') {
      const e = ev[m.event_id]; if (!e) return;
      j = { wt, ref: e.id, date: e.date, oms: clean(e.oms), sap: clean(e.sap), book: String(e.br1_book || ''), no: String(e.br1_no || ''), device: e.device, tambon: e.tambon };
    } else {
      const p = pm[m.ref_id || m.event_id]; if (!p) return;
      j = { wt, ref: p.id, date: m.date instanceof Date ? m.date : p.done_at, oms: '', sap: clean(p.sap), book: '', no: '', device: p.device, tambon: p.tambon };
    }
    const d = j.date instanceof Date ? j.date : parseDT_(j.date);
    if (!refs.length && from && (!d || d < from)) return;
    if (!refs.length && to && (!d || d >= to)) return;
    if (f.work_type && f.work_type !== wt) return;
    if (f.noSap && j.sap) return;
    if (!hit(j)) return;
    out.push({ wt, ref: j.ref, date: d ? fmtDate_(d) : '', oms: j.oms, sap: j.sap, book: j.book, no: j.no, device: j.device || '', tambon: j.tambon || '',
      code: m.code, name: m.name, size: m.size, qty: m.qty === '' ? '' : Number(m.qty), unit: m.unit });
  });
  out.sort((a, b) => (a.sap || '~').localeCompare(b.sap || '~') || a.date.localeCompare(b.date) || a.ref.localeCompare(b.ref));
  const jobs = {}; out.forEach(r => { jobs[r.ref] = 1; });
  return { rows: out.slice(0, 5000), jobs: Object.keys(jobs).length, noSap: out.filter(r => !r.sap).length, truncated: out.length > 5000 };
}

