function apiTambonAt(token, lat, lon) {
  auth_(token, 'view');
  return { tambon: tambonAt_(+lat, +lon) || '' };
}
/** ผู้ใช้ไฟใต้อุปกรณ์ (GIS NUMBEROFUS) — เบรกเกอร์ต้นฟีดเดอร์ใช้ผลรวมหม้อแปลงทั้งฟีดเดอร์ */
function apiDeviceCustomers(token, codes) {
  auth_(token, 'view');
  const served = feederServed_();
  const out = {};
  (codes || []).slice(0, 50).forEach(c => {
    const n = normDevice_(c), reg = regOf_(n.code || c);
    let v = reg && Number(reg.customers) > 0 ? Number(reg.customers) : '';
    const feeder = (reg && reg.feeder) || n.feeder || '';
    const isCB = /VB|CB/.test(String(n.code || c)) || /เบรกเกอร์/.test(String((reg && reg.kind) || ''));
    if (isCB && feeder && served[feeder]) v = served[feeder];
    out[c] = { customers: v, feeder, kind: (reg && reg.kind) || n.kind || '' };
  });
  return out;
}

