  // 45: ประเภทงาน PM ใหม่ (ต่อท้ายก่อน "อื่นๆ")
  const st = table_(SH.SETTINGS, true).rows.find(r => r.key === 'pm_categories');
  if (st) {
    const cur = String(st.value || '').split(',').map(x => x.trim()).filter(Boolean);
    const miss = NEW_PM_CATS.filter(c => cur.indexOf(c) < 0);
    if (miss.length) {
      const oi = cur.indexOf('อื่นๆ'); const nx = oi >= 0 ? cur.slice(0, oi).concat(miss, cur.slice(oi)) : cur.concat(miss);
      updateRow_(SH.SETTINGS, st._row, { value: nx.join(', ') });
    }
  }
  invalidate_(SH.SETTINGS);
  const n44 = legacyCauseParse_();
  try { CacheService.getScriptCache().remove('boot_static'); } catch (e) { /* ignore */ }
  const msg = 'อัปเดต v1.7 เรียบร้อย — ตั้งค่าใหม่ ' + add.length + ' รายการ · แปลงสาเหตุเดิมอัตโนมัติ ' + n44 + ' เหตุการณ์';
  if (!silent) { try { SpreadsheetApp.getUi().alert(msg); } catch (e) { /* ignore */ } }
  return msg;
}

