/** แปลงข้อมูลเดิมที่ชัดเจน: อาการ + เฟส และประเภทสาเหตุที่จับคู่ได้แน่นอน (ไม่ทับค่าที่มีแล้ว) */
function legacyCauseParse_() {
  const t = table_(SH.EVENTS, true); let n = 0;
  const catMap = { 'สัตว์ (งู/กระรอก/นก/หนู ฯลฯ)': 'สัตว์', 'ต้นไม้/กิ่งไม้': 'ต้นไม้', 'โหลดเกิน': 'โหลดเกินพิกัด', 'อุปกรณ์ชำรุด (LT/DO/LA/ลูกถ้วย ฯลฯ)': 'อุปกรณ์', 'หม้อแปลงชำรุด': 'อุปกรณ์' };
  const subOf = (type, txt) => {
    if (type === 'สัตว์') { if (/งู/.test(txt)) return 'งู'; if (/กระรอก|กระแต|หนู/.test(txt)) return 'กระรอก/กระแต/หนู'; if (/นก|ค้างคาว/.test(txt)) return 'นก/ค้างคาว'; if (/ตุ๊กแก|ตะกวด|กิ้งก่า/.test(txt)) return 'ตุ๊กแก/ตะกวด/กิ้งก่า/ตัวเงินตัวทอง'; return ''; }
    if (type === 'ต้นไม้') { if (/ล้ม/.test(txt)) return 'ต้นไม้ล้มทับสาย'; if (/กิ่ง/.test(txt)) return 'กิ่งไม้หักพาดสาย'; return ''; }
    if (type === 'โหลดเกินพิกัด') return 'โหลดเกินพิกัด';
    if (type === 'อุปกรณ์') return 'ชำรุด';
    return '';
  };
  const ups = [];
  t.rows.forEach(e => {
    if (String(e.sym || '').trim() || String(e.cause_type || '').trim()) return;
    const txt = String(e.cause || ''), o = {};
    if (/ฟิวส์\s*แรงสูง|HV\s*fuse/i.test(txt)) o.sym = 'ฟิวส์แรงสูงขาด';
    else if (/ฟิวส์\s*แรงต่ำ/.test(txt)) o.sym = 'ฟิวส์แรงต่ำขาด';
    else if (/หลวม|จั้ม|จั๊ม/.test(txt) && e.voltage !== 'HV') o.sym = 'จุดต่อหลวม/ไหม้';
    else if (/ไฟตก/.test(txt)) o.sym = e.voltage === 'HV' ? 'ไฟตก/แรงดันผิดปกติ' : 'ไฟตก/ไฟเกิน';
    const ph = (txt.match(/เฟส\s*([ABC](?:\s*[,/]?\s*[ABC])*)/i) || txt.match(/ขาด\s*([ABC])\b/) || [])[1];
    if (ph && !String(e.phase || '').trim()) o.phase = ph.toUpperCase().replace(/[^ABC]/g, '').split('').join(',');
    const ty = catMap[String(e.cause_cat || '')];
    if (ty) { o.cause_type = ty; const s = subOf(ty, txt); if (s) o.cause_sub = s; o.known = 'ทราบสาเหตุ'; }
    if (String(e.cause_cat || '') === 'ไม่พบสาเหตุ' || String(e.cause_cat || '') === 'ระบบป้องกันทำงาน (ไม่พบสาเหตุ)') o.known = 'สันนิษฐาน';
    if (String(e.cause_cat || '') === 'หลวมจุดต่อ/จุดจั๊ม') { o.cause_type = 'อุปกรณ์'; o.cause_sub = 'ชำรุด'; o.part = e.voltage === 'HV' ? 'จุดต่อสาย' : 'จุดต่อสายแรงต่ำ'; o.known = 'ทราบสาเหตุ'; }
    if (Object.keys(o).length) { ups.push([e._row, o]); n++; }
  });
  batchUpdate_(SH.EVENTS, ups);
  return n;
}

/** เขียนหลายแถวในครั้งเดียว (เร็วกว่า updateRow_ ทีละแถวมาก) — ups: [[rowNumber, {key: value}], ...] */
function batchUpdate_(name, ups) {
  // v1.12 ข้อ 103: เขียนเฉพาะแถวที่เปลี่ยน (เดิมเขียนทั้งชีต) · แถวที่อยู่ติดกัน/ใกล้กันรวมเป็นช่วงเดียว
  if (!ups.length) return;
  const t = shape_(name), byRow = {};
  ups.forEach(([r, o]) => { if (r >= 2) byRow[r] = Object.assign(byRow[r] || {}, o); });
  const rows = Object.keys(byRow).map(Number).sort((a, b) => a - b); if (!rows.length) return;
  const runs = []; let cur = [rows[0]];
  for (let i = 1; i < rows.length; i++) { if (rows[i] - cur[cur.length - 1] <= 8) cur.push(rows[i]); else { runs.push(cur); cur = [rows[i]]; } }
  runs.push(cur);
  runs.forEach(run => {
    const r0 = run[0], n = run[run.length - 1] - r0 + 1, rng = t.sh.getRange(r0, 1, n, t.width), vals = rng.getValues();
    run.forEach(r => { vals[r - r0] = toRowArray_(t, byRow[r], vals[r - r0]); });
    rng.setValues(vals);
  });
  invalidate_(name);
}
/** ใช้ทั้งฝั่งรายงานและดัชนี: เหตุการณ์ถูกยกเว้นจากดัชนีตามเกณฑ์ กฟภ. หรือไม่ */
