  if (!c) { const m = table_(SH.MATERIAL).rows.find(x => x.code === code); if (m) c = sizeMapOf_(m)[String(size || '').trim().toUpperCase()] || ''; }
  if (!c) { const a = aliasMap_()[aliasKey_(code, name, size)]; if (a) c = String(a.sap_code || ''); }
  const p = pm[c]; return { code: c, name: p ? String(p.name) : '', price: p ? +p.price || '' : '' };
}
const TH_STOP = /[\s\-\/().,×x*]+/;
function tokens_(s) { return String(s || '').toLowerCase().replace(/(\d+)\s*(a|kva|ตร\.?มม\.?|มม\.?|sqmm|mm2)/g, '$1$2').split(TH_STOP).filter(t => t.length > 1 || /\d/.test(t)); }
function suggestSap_(text, prices, n) {
