  return prices.map(p => { const pt = String(p.name).toLowerCase(); let sc = 0; tk.forEach(t => { if (pt.indexOf(t) >= 0) sc += /\d/.test(t) ? 2 : 1; }); return [sc, p]; })
    .filter(x => x[0] > 0).sort((a, b) => b[0] - a[0]).slice(0, n || 5).map(x => ({ code: String(x[1].sap_code), name: String(x[1].name), unit: String(x[1].unit || ''), price: +x[1].price || 0 }));
}
/** หน้าจับคู่: รายการที่ยังไม่มีรหัส SAP (จัดกลุ่มตามชื่อ+ขนาด) และรายการที่จับคู่แล้ว */
function apiMatPending(token) {
  const s = auth_(token, 'view'); if (!canMatSap_(s)) throw new Error('เฉพาะผู้ดูแลระบบและเจ้าหน้าที่สั่งการ');
