/** จับคู่/แก้/ยกเลิก — เขียนรหัส SAP ลงทุกแถวที่ใช้ชื่อนั้น (ราคาใน บร.1 ที่บันทึกไว้แล้วไม่เปลี่ยน เพราะเก็บแยกไว้กับเหตุการณ์) */
function apiMatMatch(token, o) {
