/** 42: ค้นหาวัสดุ (ทุกคน) */
function apiMatSearch(token, f) {
  auth_(token, 'view'); f = f || {};
  const q = String(f.q || '').trim().toLowerCase(), qn = q.replace(/\s+/g, '');
  const prices = table_(SH.PRICE).rows.filter(r => r.sap_code);
  const aliases = {}; table_(SH.MATALIAS).rows.forEach(a => { if (!a.sap_code) return; (aliases[a.sap_code] = aliases[a.sap_code] || []).push(String(a.alias).split('|').slice(1).filter(Boolean).join(' ')); });
  table_(SH.MATERIAL).rows.forEach(m => { const sm = sizeMapOf_(m); Object.keys(sm).forEach(sz => { (aliases[sm[sz]] = aliases[sm[sz]] || []).push(m.name + ' ' + sz); }); });
  const now = Date.now(), use = {};
  table_(SH.MATUSE).rows.forEach(m => {
    const c = String(m.sap_code || ''); if (!c) return; const d = m.date instanceof Date ? m.date.getTime() : Date.parse(m.date) || 0;
    const u = use[c] || (use[c] = { q30: 0, q365: 0, jobs: {} }); const age = (now - d) / 86400000;
    if (age <= 30) u.q30 += +m.qty || 0; if (age <= 365) { u.q365 += +m.qty || 0; u.jobs[m.ref_id || m.event_id] = 1; }
  });
  const mk = settingNum_('br1_markup_pct', 40);
  let res = prices.map(p => {
    const c = String(p.sap_code), al = aliases[c] || [], u = use[c] || { q30: 0, q365: 0, jobs: {} };
    return { manual: p.manual === true || String(p.manual).toUpperCase() === 'TRUE', added_by: String(p.added_by || ''), cat: String(p.sheet || ''), code: c, name: String(p.name), unit: String(p.unit || ''), price: +p.price || 0, br1: Math.round((+p.price || 0) * (1 + mk / 100)),
      cat: String(p.sheet || ''), aliases: al.slice(0, 6), q30: u.q30, q365: u.q365, jobs: Object.keys(u.jobs).length };
  });
  if (f.cat) res = res.filter(r => r.cat === f.cat);
