      const hay = (r.code + ' ' + r.name + ' ' + r.aliases.join(' ')).toLowerCase(); let sc = 0;
      if (r.code.indexOf(qn) === 0) sc += 10; tk.forEach(t => { if (hay.indexOf(t) >= 0) sc += /\d/.test(t) ? 2 : 1; });
