// ---------------------------------------------------------------- 46: ผลวิเคราะห์ในรายงาน PDF ผู้บริหาร
function rcaDraft_(code, evs) {
  const n = evs.length; if (n < 2) return '';
  const cnt = {}, part = {}; let pres = 0;
  evs.forEach(e => {
    const unk = e.known === 'สันนิษฐาน' || (!e.cause_type && /ไม่พบสาเหตุ|ไม่ระบุสาเหตุ|^อื่นๆ$/.test(String(e.cause_cat || '')));
    if (unk) { pres++; return; }
    const c = e.cause_type ? e.cause_type + (e.cause_sub && e.cause_sub !== e.cause_type ? ' (' + e.cause_sub + ')' : '') : String(e.cause_cat || ''); if (c) cnt[c] = (cnt[c] || 0) + 1; if (e.part) part[e.part] = (part[e.part] || 0) + 1;
  });
  const top = Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a])[0], topP = Object.keys(part).sort((a, b) => part[b] - part[a])[0];
  const tl = evs.filter(e => e.type === 'T/L').length, tr = evs.filter(e => e.type === 'T/R').length;
  let t = code + ' เกิดเหตุ ' + n + ' ครั้ง' + (tl || tr ? ' (T/L ' + tl + ', T/R ' + tr + ')' : '');
  if (top && cnt[top] >= 2) t += ' สาเหตุส่วนใหญ่เป็น' + top + ' ' + cnt[top] + ' ครั้ง' + (topP ? ' ที่' + topP : '');
  if (pres) t += (top ? ' และ' : ' ') + 'ไม่ทราบสาเหตุ ' + pres + ' ครั้ง';
  const pm = table_(SH.PM).rows.filter(p => deviceKey_(p.device || '') === deviceKey_(code));
  const done = pm.filter(p => p.status === 'เสร็จ').slice(-2), open = pm.filter(pmOpen_);
  if (done.length) t += ' · ดำเนินการแล้ว: ' + done.map(p => p.category + (p.done_at instanceof Date ? ' (' + thNum_(p.done_at) + ')' : '')).join(', ');
  const reg = regOf_(code);
  if (reg && reg.ag_date) t += ' · สำรวจครอบกันสัตว์ล่าสุด ' + (reg.ag_date instanceof Date ? thNum_(reg.ag_date) : reg.ag_date);
  const typ = (top || '').split(' (')[0];
  const sug = (PREVENT_PM[typ] || []).slice(0, 2);
  let g = '';
  if (pres >= Math.ceil(n / 2)) g = 'ควรลาดตระเวนตรวจหาสาเหตุตลอดแนวป้องกันของอุปกรณ์นี้';
  if (sug.length) g += (g ? ' และ' : 'ควร') + sug.join(' / ');
  if (open.length) g += (g ? ' · ' : '') + 'มีงาน PM รอดำเนินการ ' + open.length + ' งาน (' + open.map(p => p.category).join(', ') + ')';
  return t + (g ? '\nแนวทาง: ' + g : '');
}
function apiRcaGet(token, month) {
  auth_(token, 'view');
  const m = String(month || ''); if (!/^\d{4}-\d{2}$/.test(m)) throw new Error('เดือนไม่ถูกต้อง');
