/** เมนู: ติดตั้งเวอร์ชันใหม่จากไฟล์ใน Drive */
function installFromDrive() {
  const ui = SpreadsheetApp.getUi();
  try {
    const found = instFindBundles_();
    let fileId = '';
    const hint = found.length
      ? 'พบไฟล์ใน Drive:\n' + found.slice(0, 5).map((f, i) => (i + 1) + ') ' + f.name + ' · ' + Utilities.formatDate(f.at, APP.tz, 'd/M HH:mm')).join('\n') + '\n\nพิมพ์เลขที่ต้องการ (ว่าง = 1) หรือวางลิงก์ไฟล์อื่น'
      : 'ไม่พบไฟล์ MILIN_Platform_v*.json ใน Drive\nอัปโหลดไฟล์ไว้ใน Drive แล้ววางลิงก์ไฟล์ที่นี่';
    const r = ui.prompt('ติดตั้งเวอร์ชันใหม่จากไฟล์', hint, ui.ButtonSet.OK_CANCEL);
    if (r.getSelectedButton() !== ui.Button.OK) return;
    const t = r.getResponseText().trim();
    if (found.length && (!t || /^\d+$/.test(t))) { const f = found[(Number(t) || 1) - 1]; if (!f) throw new Error('ไม่มีลำดับที่ ' + t); fileId = f.id; }
    else fileId = instIdFromText_(t);
    if (!fileId) throw new Error('อ่านลิงก์ไฟล์ไม่ได้');
    const file = DriveApp.getFileById(fileId);
    let bundle; try { bundle = JSON.parse(file.getBlob().getDataAsString('UTF-8')); } catch (e) { throw new Error('ไฟล์ ' + file.getName() + ' ไม่ใช่ไฟล์ชุดติดตั้ง (JSON)'); }
    const b = instValidate_(bundle);
    const ok = ui.alert('ยืนยันการติดตั้ง', 'ติดตั้ง v' + b.version + ' (' + b.files.length + ' ไฟล์) แทนโค้ดปัจจุบัน v' + APP.version + '\n\nระบบจะสำรองโค้ดเดิมไว้ก่อน ย้อนกลับได้จากเมนู "ย้อนกลับเวอร์ชันก่อนหน้า"', ui.ButtonSet.OK_CANCEL);
    if (ok !== ui.Button.OK) return;
    const res = instApply_(bundle, 'ติดตั้ง');
    audit_('system', 'install', 'code', 'v' + res.version, { file: file.getName(), backup: res.backup.name, deploy: res.deploy, deployError: res.deployError });
    try { auditFlush_(); } catch (e) { /* ignore */ }
    ui.alert(instReport_(res, 'ติดตั้ง'));
  } catch (e) { ui.alert('ติดตั้งไม่สำเร็จ', String(e.message || e), ui.ButtonSet.OK); }
}

/** เมนู: ย้อนกลับไปโค้ดที่สำรองไว้ */
function rollbackInstall() {
  const ui = SpreadsheetApp.getUi();
  try {
    const it = instFolder_().getFiles(), list = [];
    while (it.hasNext()) { const f = it.next(); if (/^backup_.*\.json$/.test(f.getName())) list.push(f); }
    list.sort((a, b) => b.getDateCreated() - a.getDateCreated());
    if (!list.length) throw new Error('ยังไม่มีโค้ดที่สำรองไว้');
    const r = ui.prompt('ย้อนกลับเวอร์ชัน', 'โค้ดที่สำรองไว้:\n' + list.slice(0, 8).map((f, i) => (i + 1) + ') ' + f.getName()).join('\n') + '\n\nพิมพ์เลขที่ต้องการ (ว่าง = 1)', ui.ButtonSet.OK_CANCEL);
    if (r.getSelectedButton() !== ui.Button.OK) return;
    const f = list[(Number(r.getResponseText().trim()) || 1) - 1]; if (!f) throw new Error('ไม่มีลำดับนี้');
    const bundle = JSON.parse(f.getBlob().getDataAsString('UTF-8'));
    const res = instApply_(bundle, 'ย้อนกลับ');
    audit_('system', 'rollback', 'code', 'v' + res.version, { file: f.getName(), backup: res.backup.name });
    try { auditFlush_(); } catch (e) { /* ignore */ }
    ui.alert(instReport_(res, 'ย้อนกลับเป็น'));
  } catch (e) { ui.alert('ย้อนกลับไม่สำเร็จ', String(e.message || e), ui.ButtonSet.OK); }
}

