/** แทนที่ v1.12: เพิ่มวันที่ · ขั้นตอนงาน · งานมอบหมาย (kind 'as') */
function apiJobProgress(token, kind, id, text, photos, opt) {
  const s = auth_(token, 'view'); opt = opt || {};
  text = String(text || '').trim().slice(0, 600);
  photos = (photos || []).map(String).filter(Boolean);
  const cfg = { req: { sh: SH.REQ, head: 'req.write', field: 'result', act: 'REQ_PROGRESS', feat: 'requests' },
    pm: { sh: SH.PM, head: 'pm.update', field: 'result', act: 'PM_PROGRESS', feat: 'pm' },
    wbs: { sh: SH.WBS, head: 'wbs.write', field: 'note', act: 'WBS_PROGRESS', feat: 'wbs' },
    as: { sh: AS_SHEET, head: '', field: 'progress', act: 'AS_PROGRESS', feat: '' } }[kind];
  if (!cfg) return { ok: false, error: 'ชนิดงานไม่ถูกต้อง' };
  if (cfg.feat) requireFeature_(cfg.feat);
  const d = progressDate_(opt.date), perms = permsOf_(s);
  return withLock_(() => {
    const r = table_(cfg.sh, true).rows.find(x => x.id === id); if (!r) return { ok: false, error: 'ไม่พบงาน ' + id };
    const own = kind === 'as' ? asMine_(r, s.display) : String(r.owner || '') === s.display;
    const head = kind === 'as' ? canAssign_(s) : perms.indexOf(cfg.head) >= 0;
    if (!own && !head && !(kind !== 'as' && isStaff_(s))) throw new Error('ไม่มีสิทธิ์อัปเดตงานนี้');
    const closed = kind === 'wbs' ? ['แล้วเสร็จ', 'ยกเลิก'].indexOf(r.status) >= 0 : ['เสร็จ', 'ยกเลิก'].indexOf(r.status) >= 0;
    if (closed) return { ok: false, error: 'งานนี้ปิดแล้ว' };
    let stage = String(opt.stage || '').trim(), sk = '', askClose = false;
    if (stage) {
      sk = stageKindOf_(kind, r); const st = stageSets_();
      if (!sk || st.sets[sk].indexOf(stage) < 0) return { ok: false, error: 'ขั้นตอนไม่ถูกต้อง: ' + stage };
      askClose = st.close[sk] === stage;
    }
    if (!text && !stage) return { ok: false, error: 'กรุณาพิมพ์ความคืบหน้า หรือเลือกขั้นตอน' };
    const body = (stage && stage !== String(r.stage || '') ? '[' + stage + '] ' : '') + (text || (stage ? '' : ''));
    const line = progressLine2_(r[cfg.field], body.trim() || ('[' + stage + ']'), s.display, d), now = new Date();
    const upd = { updated_by: s.display, updated_at: now, last_progress_at: now };
    upd[cfg.field] = (String(r[cfg.field] || '').trim() ? String(r[cfg.field]).replace(/\s+$/, '') + '\n' : '') + line;
    if (stage) { upd.stage = stage; const sa = stageAt_(r); if (!sa[stage]) sa[stage] = fmtDate_(d); upd.stage_at = JSON.stringify(sa); }
    if (kind === 'as') { if (r.status === 'รอเริ่ม') upd.status = 'กำลังทำ'; }
