/** การกระทำกับงานมอบหมาย: move(ลากบนบอร์ด) · ms(ติ๊กขั้นย่อย) · review(ส่งให้ตรวจ) · done · back · cancel · reopen · take · transfer */
function apiAsAction(token, o) {
  const s = auth_(token, 'view'); o = o || {};
  return withLock_(() => {
    const r = table_(AS_SHEET, true).rows.find(x => x.id === o.id); if (!r) return { ok: false, error: 'ไม่พบงาน ' + o.id };
    const mine = asMine_(r, s.display), head = canAssign_(s) || String(r.created_by) === s.display;
    const need = (c, m) => { if (!c) throw new Error(m || 'ไม่มีสิทธิ์ทำรายการนี้'); };
    const now = new Date(), upd = { updated_by: s.display, updated_at: now }; let note = '';
    const setStatus = st => {
      upd.status = st;
      if (st === 'เสร็จ') { upd.done_at = now; const ms = msOf_(r); if (ms.length) { ms.forEach(m => { if (!m.done) { m.done = true; m.by = s.display; m.at = fmtDate_(now); } }); upd.milestones = JSON.stringify(ms); } upd.pct = 100; }
      else if (r.status === 'เสร็จ') upd.done_at = '';
    };
    switch (o.action) {
      case 'move': {
        const st = String(o.status || ''); if (AS_STATUS.indexOf(st) < 0 || st === 'ยกเลิก') return { ok: false, error: 'สถานะไม่ถูกต้อง' };
        if (st === 'เสร็จ') need(head || (mine && String(r.created_by) === s.display), 'ย้ายไป "เสร็จ" ได้โดยผู้มอบหมาย/หัวหน้า — เจ้าของงานกด "ส่งให้ตรวจ"');
        else need(head || mine);
        setStatus(st); note = 'สถานะ: ' + st; break;
      }
      case 'ms': {
        need(head || mine); const ms = msOf_(r), i = Number(o.i); if (!ms[i]) return { ok: false, error: 'ไม่พบขั้นย่อย' };
        ms[i].done = !ms[i].done; ms[i].by = ms[i].done ? s.display : ''; ms[i].at = ms[i].done ? fmtDate_(now) : '';
        upd.milestones = JSON.stringify(ms); upd.pct = pctOf_(ms); upd.last_progress_at = now;
        if (r.status === 'รอเริ่ม' && ms[i].done) upd.status = 'กำลังทำ';
        note = (ms[i].done ? '✓ ' : 'ยกเลิกติ๊ก ') + ms[i].t; break;
      }
      case 'review': need(mine || head); setStatus('รอตรวจ'); note = 'ส่งให้ตรวจ' + (o.note ? ': ' + o.note : ''); break;
      case 'done': need(head, 'ปิดงานได้โดยผู้มอบหมาย/หัวหน้า'); setStatus('เสร็จ'); note = 'ตรวจแล้ว ปิดงาน' + (o.note ? ': ' + o.note : ''); break;
      case 'back': need(head); if (!String(o.note || '').trim()) return { ok: false, error: 'กรุณาระบุสิ่งที่ต้องแก้' }; setStatus('กำลังทำ'); note = 'ส่งกลับแก้ไข: ' + o.note; break;
      case 'cancel': need(head); setStatus('ยกเลิก'); note = 'ยกเลิก' + (o.note ? ': ' + o.note : ''); break;
      case 'reopen': need(head); setStatus('กำลังทำ'); note = 'เปิดงานอีกครั้ง'; break;
      case 'take': need(isStaff_(s) || head); if (String(r.owner || '').trim()) return { ok: false, error: 'งานนี้มีเจ้าของแล้ว: ' + r.owner }; upd.owner = s.display; note = 'รับงานเอง'; break;
      case 'transfer':
        need(mine || head, 'ส่งต่อได้โดยเจ้าของงานหรือหัวหน้า');
        if (!String(o.to || '').trim() || !String(o.reason || '').trim()) return { ok: false, error: 'กรุณาระบุผู้รับงานต่อและเหตุผล' };
        upd.owner = String(o.to).trim(); note = 'ส่งต่อจาก ' + (r.owner || '-') + ' → ' + upd.owner + ' · เหตุผล: ' + o.reason + (String(o.note || '').trim() ? ' · ฝากงาน: ' + o.note : ''); break;
      default: return { ok: false, error: 'ไม่รู้จักคำสั่ง' };
    }
    upd.history = histAdd_(r, s.display, o.action, note);
    updateRow_(AS_SHEET, r._row, upd);
    audit_(s.display, 'AS_' + (o.action === 'transfer' ? 'HANDOVER' : String(o.action).toUpperCase()), AS_SHEET, r.id, note, o.reason || '');
    return { ok: true, status: upd.status || r.status, pct: upd.pct !== undefined ? upd.pct : Number(r.pct) || 0 };
  });
}

/** งานประจำตาม JD: สร้างงานมอบหมายให้ R ทุกรอบ (กันซ้ำด้วยรหัสรอบ) */
function jdPeriod_(freq, d) {
  const y = d.getFullYear(), m = d.getMonth(), be = y + 543, fy = (m >= 9 ? y + 1 : y) + 543, fm = (m + 3) % 12;
  if (freq === 'รายสัปดาห์') { const mon = new Date(y, m, d.getDate() - ((d.getDay() + 6) % 7)); return { key: 'W' + fmtDate_(mon), label: 'สัปดาห์ ' + thNum_(mon), end: new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + 6) }; }
  if (freq === 'รายเดือน') return { key: be + '-' + ('0' + (m + 1)).slice(-2), label: (m + 1) + '/' + be, end: new Date(y, m + 1, 0) };
  if (freq === 'รายไตรมาส') { const q = Math.floor(fm / 3) + 1, endM = m - (fm % 3) + 2; return { key: fy + '-Q' + q, label: 'ไตรมาส ' + q + '/' + fy, end: new Date(y, endM + 1, 0) }; }
  if (freq === 'รายปี') return { key: 'FY' + fy, label: 'ปีงบ ' + fy, end: new Date(fy - 543, 8, 30) };
