const WBS_REC_M = 300;
(function () {
  const _get = apiWbsGet;
  apiWbsGet = function (token, id) {
    const res = _get.apply(this, arguments);
    try {
      if (!res || !res.ok || !res.cand) return res;
      const w = table_(SH.WBS).rows.find(x => x.id === id); if (!w) return res;
      const z = wbsArea_(w), evAll = events_(), byId = {}; evAll.forEach(e => { byId[e.id] = e; });
      const linkedIds = (res.linked.events || []).map(e => e.id);
      const devs = {}, moos = {};
      linkedIds.forEach(i => { const e = byId[i]; if (!e) return; if (e.device) devs[deviceKey_(e.device)] = 1; if (e.tambon && e.moo) moos[e.tambon + '|' + e.moo] = 1; });
      (res.linked.pm || []).forEach(p => { if (p.device) devs[deviceKey_(p.device)] = 1; });
      const distM = (lat, lon) => { if (!z.pt || lat === '' || lat == null || !+lat) return null; const km = kmBetween_(z.pt, { lat: +lat, lon: +lon }); return km == null ? null : Math.round(km * 1000); };
      const inArea = (lat, lon) => !!z.area && lat !== '' && lat != null && +lat > 0 && pointInArea_(+lat, +lon, z.area);
      // เหตุการณ์ย้อนหลัง 3 ปี (เดิมตัดไว้ 100 รายการ) — ส่งข้อมูลครบเพื่อจัดกลุ่ม
      const since = new Date(Date.now() - 3 * 365 * 864e5), out = [];
      if (z.pt || z.area || z.feeder) evAll.filter(e => !e.parent_id && evTime_(e) >= since && linkedIds.indexOf(e.id) < 0).forEach(e => {
        const reg = regOf_(e.device), lat = reg ? reg.lat : '', lon = reg ? reg.lon : '';
        if (!inWbsZone_(z, lat, lon, feederOf_(e))) return;
        const n = normDevice_(e.device), lv = /แรงต่ำ|LV/i.test(String(e.voltage || '')) || n.kind === 'หม้อแปลง';
        const d = distM(lat, lon), why = [];
        if (e.device && devs[deviceKey_(e.device)]) why.push('อุปกรณ์เดียวกับงานที่ผูก');
        if (inArea(lat, lon)) why.push('อยู่ในขอบเขต');
        else if (d != null && d <= WBS_REC_M) why.push('ห่าง ' + d + ' ม.');
        if (e.tambon && e.moo && moos[e.tambon + '|' + e.moo]) why.push('หมู่บ้านเดียวกัน');
        out.push({ id: e.id, at: fmtDT_(evTime_(e)), ts: +evTime_(e), type: e.type, device: String(e.device || ''), cause: String(e.cause || e.cause_cat || ''), cause_cat: String(e.cause_cat || ''),
          hv: !lv, grp: String(e.device || '(ไม่ระบุอุปกรณ์)'), tambon: String(e.tambon || ''), moo: String(e.moo || ''), dist: d, rec: why.length > 0, why: why.join(' · ') });
      });
      res.cand.events = out.sort((a, b) => b.ts - a.ts);
      const pmBy = {}; table_(SH.PM).rows.forEach(p => { pmBy[p.id] = p; });
      (res.cand.pm || []).forEach(x => { const p = pmBy[x.id]; if (!p) return; const d = distM(p.lat, p.lon); x.dist = d;
        x.rec = (p.device && devs[deviceKey_(p.device)]) || inArea(p.lat, p.lon) || (d != null && d <= WBS_REC_M); });
      const rqBy = {}; table_(SH.REQ).rows.forEach(r => { rqBy[r.id] = r; });
      (res.cand.req || []).forEach(x => { const r = rqBy[x.id]; if (!r) return; const d = distM(r.lat, r.lon); x.dist = d; x.rec = inArea(r.lat, r.lon) || (d != null && d <= WBS_REC_M); });
      const reason = String(w.main_reason || '') + ' ' + String(w.kind || '');
