    const t = table_(SH.MEAS, true), upd = [], gid = {}; let circ = 0, rows = 0;
    t.rows.filter(r => r.id && !isDeleted_(r)).sort((a, b) => String(a.id).localeCompare(String(b.id))).forEach(r => {
      const ch = {}, c = circNo_(r.circuit);
