      if (!String(r.meas_group || '').trim()) {
        const d = asDate_(r.date), key = c === 'รวม' ? 'id:' + r.id : [r.device, d ? fmtDate_(d) : '', String(r.measured_by || '')].join('|');
        ch.meas_group = gid[key] || (gid[key] = 'MG-' + r.id); rows++;
