}

// ---------------------------------------------------------------- คำนวณ
function irated_(kva, one) { kva = num_(kva); if (!kva) return null; return one ? kva * 1000 / settingNum_('lv_ln_voltage', 230) : kva * 1000 / (Math.sqrt(3) * settingNum_('lv_ll_voltage', 400)); }
