      if (!one) { let mx = -1; ['ia', 'ib', 'ic'].forEach((k, i) => { if (T[k] !== '' && T[k] > mx) { mx = T[k]; maxPh = 'ABC'[i]; } });
        ['ia', 'ib', 'ic'].forEach((k, i) => { if (T[k] !== '' && T[k] > ir) flags.push('เฟส ' + 'ABC'[i] + ' เกินพิกัดหม้อแปลง (' + T[k] + 'A > ' + Math.round(ir) + 'A)'); }); }
    }
    if (!one && I.length === 3 && avg > 0) { unbal = mr1_((Math.max.apply(null, I) - avg) / avg * 100); if (unbal > settingNum_('unbal_warn_pct', 20)) flags.push('กระแสรวมไม่สมดุล ' + unbal + '%'); }
