  return { ok: true, g, prev: prev ? { gid: prev.gid, date: prev.date, time: prev.time, pct: prev.pct, ia: prev.ia, ib: prev.ib, ic: prev.ic } : null, canWrite: permsOf_(s).indexOf('meas.write') >= 0 };
}
/** บันทึกการวัด 1 ครั้ง (หลายวงจร) · o.gid = แก้ไขการวัดเดิม */
function apiMeasGroupSave(token, o, reason) {
