  else if (cirs.some(c => c.circuit === 'รวม')) return { ok: false, errors: ['ค่ารวมระบบคิดให้เอง — กรอกเป็นรายวงจร'] };
  if (!cirs.length) return { ok: false, errors: ['กรุณากรอกกระแสอย่างน้อย 1 วงจร'] };
